window.SDT_LESSONS=window.SDT_LESSONS||{};window.SDT_LESSONS["E2"]={"deck":"E2","slides":[{"p":1,"title":"2강 표지: 친환경 재료 이야기가 시작돼요","terms":[],"pass1":[{"kind":"say","lines":["3주차 2강 표지예요. 제목은 '2. 친환경 재료' 한 줄뿐이에요.","1강에서 배운 다섯 순환 중 '재료 순환' 을 깊게 파는 강의예요.","주문을 다시 외워요. 자연에서 빌려 쓰고, 돌려주며 순환시켜요."]}],"pass2":[],"pass3":[],"pass4":[]},{"p":2,"title":"목차: 2강은 세 덩어리예요","terms":["Wood"],"pass1":[{"kind":"say","lines":["2강 목차 쪽이에요. 큰 번호가 1, 2, 3 세 개예요.","쉽게 말하면 '왜 필요한가 -> 자연 그대로의 재료 -> 가공한 친환경 재료' 순서예요."]},{"kind":"points","head":"세 덩어리를 한 줄씩","items":["1. 친환경 건축과 재료: 왜 필요한지, 이름 구별, 성적표 매기기, 재료별 특성.","2. 천연 건축재료의 특성 및 건축방법: **목재(Wood)**, 흙, 스트로베일(짚).","3. 친환경 건축재료의 특성 및 건축방법: 단열재, 도료, 기타(창호, 접착제, 마감재)."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"1번 안의 네 꼭지","items":["친환경 재료의 필요성 (3쪽, 4쪽)","친환경 건축재료의 유사 개념 (8쪽부터 11쪽)","환경적 관점에서 건축재료의 선정기준 및 평가 (12쪽, 13쪽)","주요 건축재료 별 특성 (14쪽)"]}],"pass3":[],"pass4":[],"walk":{"head":null,"parts":[{"b":[0.06,0.08,0.68,0.31],"c":[0.026,0.064,0.748,0.342],"r":2.9162,"img":"img/E2/walk/p002_20_01.jpg","say":"1. 친환경 건축과 재료. 아래 네 줄이 우리가 지금부터 볼 1쪽부터 14쪽까지예요."},{"b":[0.06,0.43,0.58,0.25],"c":[0.031,0.414,0.638,0.282],"r":3.0165,"img":"img/E2/walk/p002_20_02.jpg","say":"2. 천연 건축재료. **목재(Wood)**(특성, 목구조에 사용되는 목재), 흙(특성, 공법, 국외 적용사례), 스트로베일(짚)."},{"b":[0.06,0.71,0.72,0.25],"c":[0.024,0.694,0.792,0.282],"r":3.7447,"img":"img/E2/walk/p002_20_03.jpg","say":"3. 친환경 건축재료. 단열재, 도료, 기타(창호, 접착제, 마감재)예요."}]}},{"p":3,"title":"친환경 재료의 필요성 ①: 집은 **제3의 피부(Third Skin)** 예요","terms":["Ecosystem","Third Skin","Protective Function","Ventilation Function"],"pass1":[{"kind":"say","lines":["이 쪽의 이야기는 딱 하나예요. 집은 우리 몸을 감싸는 **제3의 피부(Third Skin)** 예요.","우리는 생애의 80-90% 가까운 시간을 건물 안에서 보내요.","그래서 집에 쓴 재료가 우리 몸 상태를 좌우해요."]},{"kind":"analogy","head":"몸, 옷, 집은 세 겹의 껍질이에요","scene":"몸에는 피부가 있고, 그 위에 옷을 입고, 다시 집 안에 들어가 살아요. 셋 다 몸을 감싸는 껍질이에요.","map":[["몸의 피부","첫 번째 껍질"],["옷(의복)","제2의 피부"],["집","**제3의 피부(Third Skin)**"],["땀구멍으로 숨 쉬는 피부","공기가 드나드는 재료, 곧 **환기 기능(Ventilation Function)**"]]},{"kind":"figure","head":"세 겹의 껍질","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"16\" y=\"16\" width=\"300\" height=\"238\" rx=\"2\" class=\"box b3\"/><text x=\"166\" y=\"42\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b3\">제3의 피부: 집<\/text><rect x=\"62\" y=\"58\" width=\"208\" height=\"182\" rx=\"2\" class=\"box2 b2\"/><text x=\"166\" y=\"84\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">제2의 피부: 옷<\/text><circle cx=\"166\" cy=\"162\" r=\"46\" class=\"n2 b1\"/><text x=\"166\" y=\"167\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">몸의 피부<\/text><text x=\"398\" y=\"120\" font-size=\"14\" text-anchor=\"middle\" class=\"t b3\">생애 80-90%<\/text><text x=\"398\" y=\"146\" font-size=\"14\" text-anchor=\"middle\" class=\"t b3\">를 여기서<\/text><\/svg>","caption":"몸의 피부, 옷, 집 순서로 감싸요. 우리는 생애의 80-90% 가까운 시간을 가장 바깥 껍질인 집 안에서 보내요.","builds":3}],"pass2":[{"kind":"points","head":"**생태시스템(Ecosystem)** 부터 읽어요","items":["**생태시스템(Ecosystem)** 은 물, 공기, 토양, 생물, 재생산이 불가능한 자연 재료 등을 말해요.","이것이 건축 재료의 생산, 건물의 시공, 건물을 사용하는 과정에서 소모돼요.","자연으로 되돌리기 불가능한 상태까지 훼손되기도 해요.","쓰레기와 같은 형태로 배출되기도 해요."]},{"kind":"points","head":"필요성 ① 은 '건강' 이에요","items":["생애 80-90% 가까운 시간을 건물 내에서 보내는 상황이에요.","제2의 피부는 의복, **제3의 피부(Third Skin)** 는 집이에요.","그래서 건축재료는 거주자의 건강상태에 크게 기여해요."]},{"kind":"compare","head":"건축재료에 요구되는 기능 두 가지","cols":["번호","기능","하는 일"],"rows":[["1)","**보호 기능(Protective Function)**","화학적 영향이나 기계, 열의 영향을 막아 줘요."],["2)","**환기 기능(Ventilation Function)**","신선한 공기는 들여오고, 오염된 공기는 배출시켜요."]]},{"kind":"points","head":"숨 못 쉬는 재료는 왜 나쁠까요","items":["통기가 전혀 안 되는 재료를 쓰면 실내공기가 악화돼요.","슬라이드 작은 글씨로 '(합성수지-면 옷과 비슷)' 이라고 적혀 있어요.","바람 안 통하는 옷과 면 옷의 차이에 빗댄 말이에요.","**보호 기능(Protective Function)** 만으로는 부족하고 **환기 기능(Ventilation Function)** 이 함께 있어야 해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**제3의 피부(Third Skin)** 는 무엇을 가리킬까요?","choices":["몸의 피부","옷(의복)","집","단열재"],"a":2,"why":"제2의 피부는 의복, **제3의 피부(Third Skin)** 는 집이에요. 순서를 바꾼 보기가 단골 함정이에요."},{"kind":"check","q":"슬라이드가 말한 건축재료의 두 기능을 바르게 고른 것은?","choices":["**보호 기능(Protective Function)** 와 **환기 기능(Ventilation Function)**","장식 기능과 구조 기능","방수 기능과 방음 기능","조명 기능과 난방 기능"],"a":0,"why":"1) 화학적 영향이나 기계, 열의 영향을 막는 **보호 기능(Protective Function)**, 2) 신선한 공기는 들이고 오염된 공기는 내보내는 **환기 기능(Ventilation Function)** 이에요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"건축재료에 요구되는 기능은 화학적 영향이나 기계, 열의 영향을 막아 주는 보호 기능과 신선한 공기는 들여오고 오염된 공기는 배출시키는 환기 기능이다.","ko":"두 기능 이름과 괄호 안 설명을 같이 써야 점수가 나와요.","tip":"'막아 주기' 와 '바꿔 주기' 두 낱말로 묶어서 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["숫자는 생애 80-90% 예요. 하루 몇 시간이 아니라 '생애' 시간의 비율이에요.","제2의 피부가 의복, **제3의 피부(Third Skin)** 가 집이에요. 거꾸로 적으면 틀려요.","**생태시스템(Ecosystem)** 에는 '재생산이 불가능한 자연 재료' 까지 들어가요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2897,0.063],"c":[0.0366,0.0701,0.3187,0.095],"r":4.473,"img":"img/E2/walk/p003_h.jpg"},"parts":[{"b":[0.1,0.225,0.83,0.2],"c":[0.0585,0.209,0.913,0.232],"r":5.2471,"img":"img/E2/walk/p003_24_01.jpg","say":"윗줄 두 덩어리가 **생태시스템(Ecosystem)** 이야기예요. 소모되고, 훼손되고, 쓰레기로 배출돼요."},{"b":[0.12,0.555,0.63,0.15],"c":[0.0885,0.539,0.693,0.182],"r":5.0769,"img":"img/E2/walk/p003_24_02.jpg","say":"필요성 ①. 생애 80-90%, 제2의 피부 의복, **제3의 피부(Third Skin)** 집, 건강상태에 크게 기여."},{"b":[0.15,0.8,0.73,0.11],"c":[0.1135,0.7739,0.803,0.1622],"r":6.6009,"img":"img/E2/walk/p003_24_03.jpg","say":"1) 이 **보호 기능(Protective Function)**, 2) 가 **환기 기능(Ventilation Function)** 이에요. 번호까지 외워요."},{"b":[0.185,0.925,0.75,0.045],"c":[0.1475,0.8333,0.825,0.1667],"r":6.5987,"img":"img/E2/walk/p003_24_04.jpg","say":"맨 아랫줄. 통기가 전혀 안 되는 재료는 실내공기 악화, 괄호 안은 합성수지-면 옷 비유예요."}]}},{"p":4,"title":"필요성 ②: 자원은 끝이 있어요, 그리고 선정기준 1)","terms":["Resource Circulation","Surface Treatment","Sick House Syndrome","Protective Function","Ventilation Function","Wood"],"pass1":[{"kind":"say","lines":["이 쪽의 이야기는 '자원은 무한하지 않다' 예요.","건축 자재는 자연 자원에 매우 기대고 있는데, 그 공급량에는 한계가 있어요.","그래서 **자원의 순환활용(Resource Circulation)** 이 더욱 요구돼요. 자연에서 빌려 쓰고, 돌려주며 순환시켜요."]},{"kind":"analogy","head":"재료 고르기는 장보기와 같아요","scene":"좋은 장보기는 몸에 해롭지 않고, 동네에서 난 것이고, 다시 자라는 것이고, 필요한 만큼이고, 계절에 맞는 것을 골라요.","map":[["몸에 해롭지 않은 음식","1) 유해 성분을 방출하지 않는 재료"],["동네 시장 채소","2) 적은 에너지로 만들고 나르는 재료"],["다시 자라는 채소","3) 재생가능하고 재활용이 가능한 재료"],["필요한 만큼만","4) 이용목적에 적합한 재료"],["계절에 맞는 것","5) 외부환경과 조화되는 재료"]]}],"pass2":[{"kind":"points","head":"필요성 ② 를 그대로 읽어요","items":["건축 자재는 자연 자원의 공급에 매우 의존적이에요.","그런데 자원의 공급량에는 한계가 있어요.","그래서 '**자원의 순환활용(Resource Circulation)**' 이 더욱 요구돼요.","1강의 재료 순환과 똑같은 말이에요."]},{"kind":"points","head":"건축자재 선정 시 고려사항 (5가지)","items":["1) 거주자의 쾌적성과 건강에 유해한 성분을 방출하지 않는 재료","2) 생산, 운송, 사용 과정에서 적은 에너지를 쓰고 유해물질을 방출하지 않는 재료","3) 재생가능하고 재활용이 가능한 재료","4) 이용목적에 적합한 재료","5) 외피재료로서 외부환경과 조화되는 재료"]},{"kind":"points","head":"1) 을 자세히 읽어요","items":["화학, 물리, 열 영향을 막아 주는 기능(**보호 기능(Protective Function)**)과 **환기 기능(Ventilation Function)** 을 함께 가져야 해요.","가급적 자연적이고 가공되지 않은 상태의 것이 좋아요.","**표면처리(Surface Treatment)** 는 유해한 물질의 발산이나 마모가 일어나지 않아야 해요.","무해한 건축재료인 **목재(Wood)** 도 잘못된 **표면처리(Surface Treatment)** 로 자연특성을 잃을 수 있어요.","슬라이드 괄호: (ex. **새집증후군(Sick House Syndrome)** 원인 제공)."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"'자원의 순환활용' 이 더욱 요구되는 이유로 슬라이드가 든 것은?","choices":["건축 자재 값이 싸기 때문에","자연 자원의 공급량에 한계가 있기 때문에","건물 수명이 짧기 때문에","재료 종류가 너무 많기 때문에"],"a":1,"why":"건축 자재는 자연 자원의 공급에 매우 의존적인데 공급량에 한계가 있어서 **자원의 순환활용(Resource Circulation)** 이 요구돼요."},{"kind":"check","q":"무해한 **목재(Wood)** 도 자연특성을 잃을 수 있는 까닭은?","choices":["나무를 너무 굵게 잘라서","잘못된 **표면처리(Surface Treatment)** 때문에","지역에서 생산해서","재활용을 해서"],"a":1,"why":"잘못된 **표면처리(Surface Treatment)** 로 자연특성이 사라지고 **새집증후군(Sick House Syndrome)** 의 원인을 제공할 수 있어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["필요성 ① 은 건강(거주자), 필요성 ② 는 자원(**자원의 순환활용(Resource Circulation)**)이에요.","고려사항은 5가지예요. 4쪽에는 1) 만 나오고 나머지는 5쪽부터 7쪽에 이어져요.","**목재(Wood)** 라서 무조건 안전한 것이 아니에요. **표면처리(Surface Treatment)** 가 문제를 만들어요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.3218,0.1876],"c":[0.035,0.0701,0.354,0.2196],"r":2.1494,"img":"img/E2/walk/p004_h.jpg"},"parts":[{"b":[0.11,0.283,0.8,0.1],"c":[0.07,0.2441,0.88,0.1778],"r":6.5992,"img":"img/E2/walk/p004_23_01.jpg","say":"필요성 ② 두 줄. '자원의 공급량에는 한계' 와 '**자원의 순환활용(Resource Circulation)**' 이 핵심 낱말이에요."},{"b":[0.065,0.462,0.42,0.05],"c":[0.044,0.432,0.462,0.11],"r":5.6,"img":"img/E2/walk/p004_23_02.jpg","say":"여기부터 '건축자재 선정 시 고려사항 (5가지)' 가 시작돼요. 5쪽, 6쪽, 7쪽까지 이어져요."},{"b":[0.068,0.556,0.72,0.05],"c":[0.032,0.501,0.792,0.16],"r":6.6,"img":"img/E2/walk/p004_23_03.jpg","say":"1) 거주자의 쾌적성과 건강에 유해한 성분을 방출하지 않는 재료."},{"b":[0.11,0.738,0.73,0.05],"c":[0.0735,0.6819,0.803,0.1622],"r":6.6009,"img":"img/E2/walk/p004_23_04.jpg","say":"**표면처리(Surface Treatment)** 는 유해한 물질의 발산이나 마모가 일어나지 않아야 해요."},{"b":[0.23,0.858,0.3,0.05],"c":[0.215,0.828,0.33,0.11],"r":4.0,"img":"img/E2/walk/p004_23_05.jpg","say":"괄호 속 예시가 **새집증후군(Sick House Syndrome)** 이에요. 재료가 아니라 '잘못된 처리' 가 원인이에요."}]}},{"p":5,"title":"선정기준 2): 가까운 데서 난 재료가 좋아요","terms":["Local Material","Transport Energy","Decentralized Production","Wood"],"pass1":[{"kind":"say","lines":["이 쪽의 이야기 하나는 '멀리서 오면 에너지가 많이 든다' 예요.","**목재(Wood)**, 흙, 석재는 가까운 곳에서 만들 수 있는 **지역 생산 재료(Local Material)** 이에요.","가까우면 나르는 데 드는 **수송 에너지(Transport Energy)** 가 줄어요."]},{"kind":"figure","head":"재료마다 오는 거리가 달라요","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240\" y=\"24\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">재료가 우리 집까지 오는 거리<\/text><line x1=\"120\" y1=\"222\" x2=\"462\" y2=\"222\" class=\"e\"/><text x=\"108\" y=\"76\" font-size=\"15\" text-anchor=\"end\" class=\"tb b1\">목재<\/text><rect x=\"120\" y=\"60\" width=\"62\" height=\"20\" rx=\"2\" class=\"n3 b1\"/><text x=\"108\" y=\"146\" font-size=\"15\" text-anchor=\"end\" class=\"tb b2\">합성재료<\/text><rect x=\"120\" y=\"130\" width=\"330\" height=\"20\" rx=\"2\" class=\"n4 b2\"/><text x=\"108\" y=\"206\" font-size=\"15\" text-anchor=\"end\" class=\"tb b2\">금속재<\/text><rect x=\"120\" y=\"190\" width=\"342\" height=\"20\" rx=\"2\" class=\"n4 b2\"/><text x=\"290\" y=\"106\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b3\">가까울수록 수송 에너지가 적어요<\/text><\/svg>","caption":"슬라이드 아래 그래프를 아주 단순하게 옮겼어요. 목재 막대는 짧고 합성재료와 금속재 막대는 길어요.","builds":3}],"pass2":[{"kind":"points","head":"2) 를 그대로 읽어요","items":["2) 재료를 생산, 운송, 사용하는 과정에서 적은 에너지를 소비하는 재료예요.","각각의 (유통) 과정에서 유해물질을 방출하지 않는 재료이기도 해요.","에너지 비용 발생은 '금속이나 합성재료 > 자연재료' 예요.","**목재(Wood)**, 흙, 석재 등은 지역적 생산이 가능해요. 이것이 **지역 생산 재료(Local Material)** 이에요."]},{"kind":"points","head":"대규모 생산, 대량 판매 재료의 문제","items":["생산 중 유해물질이 늘어요.","운송 중 교통량이 늘어요. 여러 번 운송하기 때문이에요.","도로 이용이 늘고 탄소배출이 늘어요. 곧 **수송 에너지(Transport Energy)** 가 커져요.","결론 화살표: 분산적으로 자원을 생산한 후 지역 내에서 활용하는 방안이 효과적이에요."]},{"kind":"points","head":"아래 그래프 읽는 법","items":["그래프 제목은 '원료 수송을 포함한 일반 건축재료 수송 거리' 예요.","가로 눈금은 0, 500, 1000, 2000, 3000, 4000, 5000 으로 적혀 있어요.","눈금의 단위는 슬라이드에 적혀 있지 않아요. 그래서 숫자만 기억해요.","위쪽 그림띠는 수송, 재료 및 건축 부품 생산, 수송, 시공현장 순서예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"에너지 비용 발생을 슬라이드대로 바르게 적은 것은?","choices":["금속이나 합성재료 > 자연재료","자연재료 > 금속이나 합성재료","금속 = 자연재료","합성재료 < 자연재료"],"a":0,"why":"슬라이드는 '에너지 비용 발생 - 금속이나 합성재료 > 자연재료' 라고 적었어요."},{"kind":"check","q":"슬라이드가 효과적이라고 결론 내린 방안은?","choices":["한곳에서 대규모로 생산해 전국에 파는 방안","**분산적 생산(Decentralized Production)** 후 지역 내에서 활용하는 방안","수입 재료를 늘리는 방안","운송 횟수를 늘리는 방안"],"a":1,"why":"분산적으로 자원을 생산한 후 지역 내에서 활용하는 방안이 효과적이라고 화살표로 정리했어요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"지역 생산 재료를 사용하면 재료의 수송에서 발생되는 에너지 사용을 절감할 수 있고, 분산적으로 자원을 생산한 후 지역 내에서 활용하는 방안이 효과적이다.","ko":"**지역 생산 재료(Local Material)**, **수송 에너지(Transport Energy)** 절감, **분산적 생산(Decentralized Production)** 세 낱말이 들어가야 해요.","tip":"'가까이서 만들고, 가까이서 쓴다' 로 줄여서 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["부등호 방향에 주의해요. 금속과 합성재료 쪽이 에너지 비용이 더 커요.","그래프 눈금에는 단위가 적혀 있지 않아요. 단위를 지어내서 쓰면 안 돼요.","'대량 생산' 이 아니라 **분산적 생산(Decentralized Production)** 이 답이에요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2897,0.063],"c":[0.0366,0.0701,0.3187,0.095],"r":4.473,"img":"img/E2/walk/p005_h.jpg"},"parts":[{"b":[0.065,0.225,0.82,0.1],"c":[0.024,0.1839,0.902,0.1822],"r":6.6008,"img":"img/E2/walk/p005_23_01.jpg","say":"2) 제목 두 줄이에요. '적은 에너지' 와 '유해물질을 방출하지 않는' 이 두 축이에요."},{"b":[0.11,0.345,0.59,0.05],"c":[0.0805,0.3044,0.649,0.1311],"r":6.6006,"img":"img/E2/walk/p005_23_02.jpg","say":"에너지 비용 발생: 금속이나 합성재료 > 자연재료. 부등호 방향을 그대로 외워요."},{"b":[0.11,0.405,0.79,0.115],"c":[0.0705,0.3747,0.869,0.1756],"r":6.5983,"img":"img/E2/walk/p005_23_03.jpg","say":"**목재(Wood)**, 흙, 석재는 지역적 생산이 가능하고, **지역 생산 재료(Local Material)** 을 쓰면 **수송 에너지(Transport Energy)** 가 줄어요."},{"b":[0.125,0.525,0.67,0.13],"c":[0.0915,0.509,0.737,0.162],"r":6.0658,"img":"img/E2/walk/p005_23_04.jpg","say":"대규모 생산, 대량 판매 재료는 유해물질, 교통량, 도로 이용, 탄소배출이 모두 늘어요."},{"b":[0.11,0.703,0.79,0.05],"c":[0.0705,0.6402,0.869,0.1756],"r":6.5983,"img":"img/E2/walk/p005_23_05.jpg","say":"결론 줄. **분산적 생산(Decentralized Production)** 후 지역 내에서 활용하는 방안이 효과적이에요."},{"b":[0.11,0.77,0.82,0.22],"c":[0.069,0.748,0.902,0.252],"r":4.7725,"img":"img/E2/walk/p005_23_06.jpg","say":"아래 그래프. 목재 막대는 짧고 합성재료, 금속재 막대는 오른쪽 끝까지 길어요."}]}},{"p":6,"title":"선정기준 3)과 4): 다시 자라는 재료, 꼭 필요한 곳에만","terms":["Renewable Material","Surface Treatment","Wood"],"pass1":[{"kind":"say","lines":["이 쪽에는 고려사항 3) 과 4) 가 함께 나와요.","3) 은 '다시 자라는 재료를 쓰자', 4) 는 '비싼 재료를 꼭 필요한 곳에만 쓰자' 예요.","4) 에 아주 중요한 숫자가 하나 나와요. 100배예요."]}],"pass2":[{"kind":"points","head":"3) 재생가능하고 재활용이 가능한 재료","items":["재생 가능한 식물 및 동물성 원료를 쓰면 자연계로의 물질순환이 거의 완벽하게 이루어져요.","이런 원료로 만든 것이 **재생가능 재료(Renewable Material)** 예요.","유해물질이 없고, 주변의 유해물질을 흡수하는 기능도 가능해요.","ex) 덧칠이나 코팅을 하지 않고 가능한 원상태의 자재를 활용할 경우 재활용이 용이해요."]},{"kind":"points","head":"4) 이용목적에 적합한 재료","items":["고품질 건축자재(알루미늄, 합성수지 등)는 적합한 사용인지 평가가 필요해요.","알루미늄, 합성수지의 에너지 소모는 **목재(Wood)** 의 100배예요.","따라서 불필요한 사용이 없었는지 판단이 필요해요."]},{"kind":"steps","head":"100배를 숫자로 느껴 봐요","given":"**목재(Wood)** 창틀 하나를 만드는 에너지를 1 이라고 가정해요. (연습용 가정이에요)","steps":["알루미늄 창틀 하나: 1 곱하기 100 은 100","창틀 3개를 목재로 만들면: 1 곱하기 3 은 3","창틀 3개를 알루미늄으로 만들면: 100 곱하기 3 은 300","차이는 300 빼기 3 으로 297 이에요."],"answer":"알루미늄, 합성수지의 에너지 소모 = **목재(Wood)** 의 100배"},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"알루미늄과 합성수지의 에너지 소모는 **목재(Wood)** 의 몇 배라고 했나요?","choices":["10배","50배","100배","1000배"],"a":2,"why":"4) 이용목적에 적합한 재료에서 '알루미늄, 합성수지의 에너지 소모 - 목재의 100배' 라고 했어요."},{"kind":"check","q":"재생 가능한 식물 및 동물성 원료를 쓸 때 생기는 일로 슬라이드가 든 것은?","choices":["자연계로의 물질순환이 거의 완벽하게 이루어짐","값이 가장 싸짐","강도가 가장 높아짐","수송 거리가 늘어남"],"a":0,"why":"**재생가능 재료(Renewable Material)** 는 자연계로의 물질순환이 거의 완벽하게 이루어지고, 주변의 유해물질을 흡수하는 기능도 가능해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["100배는 '에너지 소모' 비교예요. 값이나 무게가 100배라는 말이 아니에요.","3) 은 재생과 재활용, 4) 는 이용목적 적합이에요. 번호를 바꿔 쓰지 않게 조심해요.","덧칠과 코팅을 하지 않은 원상태 자재가 재활용이 쉬워요. **표면처리(Surface Treatment)** 가 적을수록 좋아요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2897,0.063],"c":[0.0366,0.0701,0.3187,0.095],"r":4.473,"img":"img/E2/walk/p006_h.jpg"},"parts":[{"b":[0.065,0.225,0.44,0.05],"c":[0.043,0.195,0.484,0.11],"r":5.8667,"img":"img/E2/walk/p006_23_01.jpg","say":"3) 재생가능하고 재활용이 가능한 재료. 여기서 **재생가능 재료(Renewable Material)** 이야기가 시작돼요."},{"b":[0.11,0.285,0.82,0.105],"c":[0.069,0.2464,0.902,0.1822],"r":6.6008,"img":"img/E2/walk/p006_23_02.jpg","say":"재생 가능한 식물 및 동물성 원료를 쓰면 자연계로의 물질순환이 거의 완벽하게 이루어져요."},{"b":[0.12,0.465,0.77,0.105],"c":[0.0815,0.4319,0.847,0.1711],"r":6.6004,"img":"img/E2/walk/p006_23_03.jpg","say":"덧칠이나 코팅을 하지 않을수록 재활용이 쉬워요. **표면처리(Surface Treatment)** 를 덜 할수록 되돌리기 쉬워요."},{"b":[0.065,0.645,0.31,0.05],"c":[0.0495,0.615,0.341,0.11],"r":4.1333,"img":"img/E2/walk/p006_23_04.jpg","say":"4) 이용목적에 적합한 재료. 고품질 자재를 꼭 필요한 곳에 썼는지 평가해요."},{"b":[0.11,0.765,0.58,0.05],"c":[0.081,0.7256,0.638,0.1289],"r":6.5994,"img":"img/E2/walk/p006_23_05.jpg","say":"시험에 잘 나오는 줄이에요. 알루미늄, 합성수지의 에너지 소모는 목재의 100배."}]}},{"p":7,"title":"선정기준 5): **외피(Building Envelope)** 재료는 바깥과 어울려야 해요","terms":["Building Envelope","Local Material","Renewable Material"],"pass1":[{"kind":"say","lines":["고려사항의 마지막 5) 예요. 건물의 바깥 껍질인 **외피(Building Envelope)** 이야기예요.","사람으로 치면 피부예요. 피부는 햇빛, 바람, 추위를 조절해요.","쪽 아래에는 다섯 가지를 한 문장으로 묶은 결론이 있어요."]}],"pass2":[{"kind":"points","head":"5) 외피재료로서 외부환경과 조화되는 재료","items":["**외피(Building Envelope)** 의 기능은 실내외 환경 조절이에요.","일사열 및 자연광 조절, 실내외 열류의 조절, 틈새 바람 조절 세 가지예요.","**외피(Building Envelope)** 를 구성하는 재료는 이 기능들과 관련된 부분들에 대한 고려가 필요해요.","예: 단열재, 벽체의 색채, 창과 개구부, 차양 등이에요."]},{"kind":"points","head":"다섯 가지를 한 문장으로 (슬라이드 아래 결론)","items":["인간에게 무해하고 쾌적한 실내 환경을 제공할 뿐 아니라,","재료의 제조 및 운송과정에서의 에너지 사용과 비용을 고려하며,","재료의 기술적 적합성, 재료의 재활용 특성 등을 고려하여 선택해야 해요."]},{"kind":"compare","head":"다섯 기준을 한 줄씩 다시 모아요","cols":["번호","고려사항","핵심 낱말"],"rows":[["1)","유해한 성분을 방출하지 않는 재료","건강, 표면처리"],["2)","적은 에너지, 유해물질 없는 유통","**지역 생산 재료(Local Material)**"],["3)","재생가능하고 재활용이 가능한 재료","**재생가능 재료(Renewable Material)**"],["4)","이용목적에 적합한 재료","100배"],["5)","외피재료로서 외부환경과 조화","**외피(Building Envelope)**"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**외피(Building Envelope)** 의 기능으로 슬라이드가 든 것이 아닌 것은?","choices":["일사열 및 자연광 조절","실내외 열류의 조절","틈새 바람 조절","건물 무게 지지"],"a":3,"why":"슬라이드는 실내외 환경 조절로 일사열 및 자연광, 실내외 열류, 틈새 바람 세 가지를 들었어요. 무게 지지는 없어요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"건축자재는 인간에게 무해하고 쾌적한 실내 환경을 제공할 뿐 아니라, 제조 및 운송과정의 에너지 사용과 비용, 기술적 적합성과 재활용 특성을 고려하여 선택해야 한다.","ko":"슬라이드 아래 결론 세 줄을 그대로 한 문장으로 만든 것이에요.","tip":"'무해와 쾌적 - 에너지와 비용 - 적합성과 재활용' 세 묶음으로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["예시로 든 단열재, 벽체의 색채, 창과 개구부, 차양은 **외피(Building Envelope)** 재료의 예예요.","5) 의 이름은 '외피재료로서 외부환경과 조화되는 재료' 예요. '예쁜 재료' 가 아니에요.","기준은 모두 5가지예요. 4쪽부터 7쪽에 걸쳐 나와요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2897,0.063],"c":[0.0366,0.0701,0.3187,0.095],"r":4.473,"img":"img/E2/walk/p007_h.jpg"},"parts":[{"b":[0.065,0.225,0.49,0.05],"c":[0.0405,0.195,0.539,0.11],"r":6.5333,"img":"img/E2/walk/p007_23_01.jpg","say":"5) 외피재료로서 외부환경과 조화되는 재료. 마지막 기준이에요."},{"b":[0.11,0.285,0.81,0.115],"c":[0.0695,0.2525,0.891,0.18],"r":6.6,"img":"img/E2/walk/p007_23_02.jpg","say":"**외피(Building Envelope)** 의 기능 세 가지예요. 일사열 및 자연광, 실내외 열류, 틈새 바람 조절."},{"b":[0.11,0.405,0.78,0.05],"c":[0.071,0.3433,0.858,0.1733],"r":6.6013,"img":"img/E2/walk/p007_23_03.jpg","say":"외피를 구성하는 재료는 위 기능들과 관련된 부분들에 대한 고려가 필요해요."},{"b":[0.148,0.465,0.51,0.05],"c":[0.1225,0.4333,0.561,0.1133],"r":6.6019,"img":"img/E2/walk/p007_23_04.jpg","say":"예시 네 가지. 단열재, 벽체의 색채, 창과 개구부, 차양 등이에요."},{"b":[0.07,0.645,0.82,0.16],"c":[0.029,0.629,0.902,0.192],"r":6.2639,"img":"img/E2/walk/p007_23_05.jpg","say":"화살표 아래가 다섯 기준의 결론이에요. 무해와 쾌적, 에너지와 비용, 기술적 적합성과 재활용 특성."}]}},{"p":8,"title":"유사개념 1) **천연건축재료(Natural Material)**","terms":["Natural Material","Environmental Material","Sustainable Material","Recycling Material"],"pass1":[{"kind":"say","lines":["여기부터 11쪽까지는 '이름이 비슷한 네 재료' 를 구별하는 곳이에요.","첫 번째는 **천연건축재료(Natural Material)** 예요. 캐서 자르거나 갈기만 한 재료예요.","화학적 성분이 전혀 들어가지 않는다는 점이 핵심이에요."]},{"kind":"analogy","head":"먹을거리로 보는 네 재료","scene":"텃밭에서 막 딴 채소, 기준에 맞춘 무첨가 가공식품, 평생 쓰는 스테인리스 도시락통, 헌 옷으로 만든 가방을 떠올려요.","map":[["텃밭에서 딴 채소 그대로","**천연건축재료(Natural Material)**"],["기준에 맞춘 무첨가 가공식품","**친환경재료(Environmental Material)**"],["만들 때 힘들지만 평생 쓰는 도시락통","**지속가능한 재료(Sustainable Material)**"],["헌 옷으로 만든 가방","**재활용재료(Recycling Material)**"]]}],"pass2":[{"kind":"points","head":"**천연건축재료(Natural Material)** 를 그대로 읽어요","items":["흙, 나무, 돌 등의 원재료를 채취하여 절단 또는 연마한 건축재료예요.","생산, 가공, 사용 과정에서 화학적 성분이 전혀 들어가지 않아요.","순수하게 자연에서 얻어진 재료로 만들어진 것을 뜻해요.","ex) 황토, 목재, 석재, 짚 등이에요."]},{"kind":"points","head":"아래 사진 세 장","items":["왼쪽은 켜 놓은 나무 판재예요.","가운데는 돌을 맞춰 깐 바닥이에요.","오른쪽은 흙벽돌을 쌓은 벽이에요.","셋 다 캐서 자르거나 갈기만 한 **천연건축재료(Natural Material)** 의 모습이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**천연건축재료(Natural Material)** 의 설명으로 옳은 것은?","choices":["환경 기준치에 맞춰 가공한 재료","생산, 가공, 사용 과정에서 화학적 성분이 전혀 들어가지 않는 재료","폐자재를 새 원료로 만든 재료","영구적으로 사용할 수 있는 금속재"],"a":1,"why":"흙, 나무, 돌 등을 채취해 절단 또는 연마하고 화학적 성분이 전혀 들어가지 않는 것이 **천연건축재료(Natural Material)** 예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["'천연' 과 '친환경' 은 다른 말이에요. 9쪽의 **친환경재료(Environmental Material)** 와 꼭 구별해요.","슬라이드 문장에 '자료를 의미' 라고 적혀 있는데 '재료' 의 오타로 보여요.","예시는 황토, 목재, 석재, 짚이에요. 벽돌이나 콘크리트가 아니에요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.4842,0.063],"c":[0.0269,0.0701,0.5327,0.095],"r":7.4765,"img":"img/E2/walk/p008_h.jpg"},"parts":[{"b":[0.068,0.225,0.41,0.05],"c":[0.0475,0.195,0.451,0.11],"r":5.4667,"img":"img/E2/walk/p008_22_01.jpg","say":"제목 줄. 1) 천연건축재료 (Natural Material) 이에요. 영어 이름까지 외워요."},{"b":[0.125,0.285,0.74,0.05],"c":[0.088,0.2278,0.814,0.1645],"r":6.5978,"img":"img/E2/walk/p008_22_02.jpg","say":"원재료를 '채취하여 절단 또는 연마한' 이 만드는 법이에요."},{"b":[0.125,0.345,0.82,0.105],"c":[0.084,0.3064,0.902,0.1822],"r":6.6008,"img":"img/E2/walk/p008_22_03.jpg","say":"가장 중요한 문장이에요. 화학적 성분이 전혀 들어가지 않아요."},{"b":[0.125,0.465,0.32,0.05],"c":[0.109,0.435,0.352,0.11],"r":4.2667,"img":"img/E2/walk/p008_22_04.jpg","say":"예시 네 가지. 황토, 목재, 석재, 짚 등이에요."},{"b":[0.02,0.59,0.96,0.38],"c":[0.0,0.571,1,0.418],"r":3.1898,"img":"img/E2/walk/p008_22_05.jpg","say":"사진 세 장이 나무, 돌, 흙벽돌 순서로 놓여 있어요."}]}},{"p":9,"title":"유사개념 2) **친환경재료(Environmental Material)**","terms":["Environmental Material","Natural Material","한국공기청정협회"],"pass1":[{"kind":"say","lines":["두 번째는 **친환경재료(Environmental Material)** 예요.","천연으로 만든 것은 아니지만, 나라가 정한 환경 기준치에 맞춰 만든 재료예요.","쉽게 말하면 '가공했지만 몸에 해롭지 않게 만든 재료' 예요."]}],"pass2":[{"kind":"points","head":"**친환경재료(Environmental Material)** 를 그대로 읽어요","items":["천연으로 만든 것은 아니지만, 각 나라의 환경 기준치에 맞추어 가공, 생산된 건축재료예요.","물품제조 과정에서 환경부하를 최소화할 수 있고 사용자의 건강을 저해하지 않아요.","자연소재들을 혼합하거나 천연소재와 인공재료를 합성해서 만들어요.","그래서 유독물질이 배출되지 않고, 인체에 해롭지 않게 만들어진 건축재료예요."]},{"kind":"points","head":"인증과 예시","items":["국내에서는 **한국공기청정협회** 에서 건축자재의 품질을 인증해요.","ex) 자연소재 혼합단열재, 분해성 플라스틱, 친환경 페인트 등이에요.","예시가 모두 '만든 물건' 이라는 점이 **천연건축재료(Natural Material)** 와 다른 점이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"국내에서 **친환경재료(Environmental Material)** (건축자재)의 품질을 인증하는 곳은?","choices":["**한국공기청정협회**","한국산업규격","폐기물관리공단","한국건축학회"],"a":0,"why":"슬라이드는 '국내에서는 **한국공기청정협회** 에서 건축자재의 품질 인증' 이라고 적었어요."},{"kind":"check","q":"'자연소재 혼합단열재, 분해성 플라스틱, 친환경 페인트' 는 어느 재료의 예일까요?","choices":["**천연건축재료(Natural Material)**","**친환경재료(Environmental Material)**","지속가능한 재료","재활용재료"],"a":1,"why":"천연은 아니지만 환경 기준치에 맞춰 만든 **친환경재료(Environmental Material)** 의 예예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**친환경재료(Environmental Material)** 는 '천연' 이 아니에요. 천연소재와 인공재료를 합성하기도 해요.","인증 기관 이름을 '한국산업규격' 과 바꿔 내기 좋아요. **한국공기청정협회** 가 맞아요.","기준은 '각 나라의 환경 기준치' 예요. 세계 공통 기준이 아니에요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.4842,0.063],"c":[0.0269,0.0701,0.5327,0.095],"r":7.4765,"img":"img/E2/walk/p009_h.jpg"},"parts":[{"b":[0.068,0.225,0.48,0.05],"c":[0.044,0.195,0.528,0.11],"r":6.4,"img":"img/E2/walk/p009_22_01.jpg","say":"제목 줄. 2) 친환경 재료 (Environmental Material) 이에요."},{"b":[0.125,0.285,0.76,0.105],"c":[0.087,0.2531,0.836,0.1689],"r":6.5996,"img":"img/E2/walk/p009_22_02.jpg","say":"'천연으로 만든 것은 아니지만' 으로 시작해요. 이 한 마디가 1) 과 갈리는 지점이에요."},{"b":[0.125,0.405,0.77,0.105],"c":[0.0865,0.3719,0.847,0.1711],"r":6.6004,"img":"img/E2/walk/p009_22_03.jpg","say":"환경부하를 최소화하고 사용자의 건강을 저해하지 않아요."},{"b":[0.125,0.525,0.78,0.105],"c":[0.086,0.4908,0.858,0.1733],"r":6.6013,"img":"img/E2/walk/p009_22_04.jpg","say":"자연소재를 혼합하거나 천연소재와 인공재료를 합성해요. 유독물질이 배출되지 않아요."},{"b":[0.125,0.645,0.66,0.05],"c":[0.092,0.5967,0.726,0.1467],"r":6.5985,"img":"img/E2/walk/p009_22_05.jpg","say":"국내 인증 기관 줄이에요. **한국공기청정협회** 가 건축자재의 품질을 인증해요."},{"b":[0.125,0.703,0.7,0.05],"c":[0.09,0.6502,0.77,0.1556],"r":6.5981,"img":"img/E2/walk/p009_22_06.jpg","say":"예시 세 가지. 자연소재 혼합단열재, 분해성 플라스틱, 친환경 페인트예요."}]}},{"p":10,"title":"유사개념 3) **지속가능한 재료(Sustainable Material)** 의 두 얼굴","terms":["Sustainable Material","Environmental Impact"],"pass1":[{"kind":"say","lines":["세 번째는 **지속가능한 재료(Sustainable Material)** 예요. 대표는 금속재예요.","이름은 좋아 보이지만 두 얼굴을 가진 재료예요.","버릴 때는 착하고, 만들 때는 사납다고 기억해요."]}],"pass2":[{"kind":"points","head":"**지속가능한 재료(Sustainable Material)** 를 그대로 읽어요","items":["재료가 훼손되지 않고 영구적으로 사용할 수 있는 재료예요.","재활용 폐기 시에는 **환경부하(Environmental Impact)** 가 적어요.","생산 시에는 많은 에너지 소비 및 환경 오염을 유발해요.","마감방식에서 유독성 물질을 사용하기 때문에 **환경부하(Environmental Impact)** 가 커요.","ex) 스틸, 동판, 알루미늄, 강철 등 금속재예요."]},{"kind":"compare","head":"두 얼굴을 표로 갈라 봐요","cols":["언제","환경에 주는 영향"],"rows":[["재활용, 폐기 시","**환경부하(Environmental Impact)** 가 적어요"],["생산 시","많은 에너지 소비와 환경 오염, 마감의 유독성 물질로 **환경부하(Environmental Impact)** 가 커요"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**지속가능한 재료(Sustainable Material)** 에 대한 설명으로 옳은 것은?","choices":["생산할 때 환경부하가 매우 적다","재활용, 폐기할 때 환경부하가 적다","화학 성분이 전혀 들어가지 않는다","폐자재를 원료로 만든다"],"a":1,"why":"영구적으로 쓰고 재활용, 폐기 때 부하가 적지만, 생산 때는 많은 에너지 소비와 환경 오염을 유발해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["이름이 '지속가능' 이라고 모든 단계가 착한 것이 아니에요. 생산 단계가 가장 나빠요.","예시는 스틸, 동판, 알루미늄, 강철 등 금속재예요. 목재나 흙이 아니에요.","마감방식에서 유독성 물질을 쓴다는 말도 함께 나와요. 이것도 **환경부하(Environmental Impact)** 예요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.4842,0.063],"c":[0.0269,0.0701,0.5327,0.095],"r":7.4765,"img":"img/E2/walk/p010_h.jpg"},"parts":[{"b":[0.068,0.225,0.49,0.05],"c":[0.0435,0.195,0.539,0.11],"r":6.5333,"img":"img/E2/walk/p010_22_01.jpg","say":"제목 줄. 3) 지속가능한 재료 (Sustainable Material) 이에요."},{"b":[0.125,0.285,0.63,0.05],"c":[0.0935,0.24,0.693,0.14],"r":6.6,"img":"img/E2/walk/p010_22_02.jpg","say":"훼손되지 않고 영구적으로 사용할 수 있다는 것이 이 재료의 뜻이에요."},{"b":[0.125,0.345,0.4,0.05],"c":[0.105,0.315,0.44,0.11],"r":5.3333,"img":"img/E2/walk/p010_22_03.jpg","say":"착한 얼굴. 재활용 폐기 시에는 **환경부하(Environmental Impact)** 가 적어요."},{"b":[0.125,0.405,0.79,0.105],"c":[0.0855,0.3697,0.869,0.1756],"r":6.5983,"img":"img/E2/walk/p010_22_04.jpg","say":"사나운 얼굴. 생산 시에는 에너지 소비, 환경 오염, 유독성 마감으로 부하가 커요."},{"b":[0.125,0.525,0.47,0.05],"c":[0.1015,0.495,0.517,0.11],"r":6.2667,"img":"img/E2/walk/p010_22_05.jpg","say":"예시. 스틸, 동판, 알루미늄, 강철 등 금속재예요."},{"b":[0.28,0.6,0.71,0.38],"c":[0.219,0.581,0.781,0.418],"r":2.4912,"img":"img/E2/walk/p010_22_06.jpg","say":"사진은 금속 관 묶음과, 금속판으로 겉을 두른 집이에요."}]}},{"p":11,"title":"유사개념 4) **재활용재료(Recycling Material)** 와 네 재료 정리","terms":["Recycling Material","Recycled Aggregate","Natural Material","Environmental Material","Sustainable Material"],"pass1":[{"kind":"say","lines":["네 번째이자 마지막은 **재활용재료(Recycling Material)** 예요.","버려진 것을 다시 원료로 삼아 만든 재료예요.","이 쪽으로 '이름이 비슷한 네 재료' 가 다 모였어요."]},{"kind":"figure","head":"네 재료 한눈에","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"12\" y=\"14\" width=\"222\" height=\"32\" rx=\"2\" class=\"box2 b1\"/><text x=\"123\" y=\"36\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">1) 천연건축재료<\/text><text x=\"123\" y=\"70\" font-size=\"14\" text-anchor=\"middle\" class=\"t b1\">캐서 자르고 갈기만<\/text><text x=\"123\" y=\"94\" font-size=\"13\" text-anchor=\"middle\" class=\"tm b1\">황토, 목재, 석재, 짚<\/text><rect x=\"246\" y=\"14\" width=\"222\" height=\"32\" rx=\"2\" class=\"box2 b2\"/><text x=\"357\" y=\"36\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">2) 친환경재료<\/text><text x=\"357\" y=\"70\" font-size=\"14\" text-anchor=\"middle\" class=\"t b2\">기준에 맞춰 가공<\/text><text x=\"357\" y=\"94\" font-size=\"13\" text-anchor=\"middle\" class=\"tm b2\">혼합단열재, 친환경 페인트<\/text><rect x=\"12\" y=\"140\" width=\"222\" height=\"32\" rx=\"2\" class=\"box2 b3\"/><text x=\"123\" y=\"162\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b3\">3) 지속가능한 재료<\/text><text x=\"123\" y=\"196\" font-size=\"14\" text-anchor=\"middle\" class=\"t b3\">영구히 쓰는 금속재<\/text><text x=\"123\" y=\"220\" font-size=\"13\" text-anchor=\"middle\" class=\"tm b3\">스틸, 동판, 알루미늄, 강철<\/text><rect x=\"246\" y=\"140\" width=\"222\" height=\"32\" rx=\"2\" class=\"box2 b4\"/><text x=\"357\" y=\"162\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b4\">4) 재활용재료<\/text><text x=\"357\" y=\"196\" font-size=\"14\" text-anchor=\"middle\" class=\"t b4\">폐자재를 새 원료로<\/text><text x=\"357\" y=\"220\" font-size=\"13\" text-anchor=\"middle\" class=\"tm b4\">흡음재, 섬유판재, 재활용골재<\/text><\/svg>","caption":"번호 순서대로 켜져요. 가운데 줄은 뜻, 아랫줄은 예예요.","builds":4}],"pass2":[{"kind":"points","head":"**재활용재료(Recycling Material)** 를 그대로 읽어요","items":["폐자재 중에서 새롭게 원료로 이용하여 생산된 재료예요.","폐콘크리트, 폐목재, 폐지, 폐플라스틱 등을 이용하여 생산된 건축재료예요.","ex) 재생섬유 흡음재, 재활용 섬유판재, **재활용골재(Recycled Aggregate)** 예요."]},{"kind":"points","head":"아래 사진과 작은 글씨","items":["사진 세 장의 이름표는 콘크리트용 (25m), 도로공사용 (40m), 아스팔트콘크리트용 (19m) 이에요.","안내문 첫 줄: 순환골재는 폐기물관리법의 기준 및 한국산업규격에 적합하게 생산되고 있습니다.","안내문 둘째 줄: 환경친화적인 신기술 공법으로 생산되어 입형이 부드럽고 강도의 저하가 없는 고품질의 순환골재입니다.","곧 **재활용골재(Recycled Aggregate)** 도 품질을 갖출 수 있다는 예시예요."]},{"kind":"compare","head":"유사개념 네 가지 비교표","cols":["이름","핵심","예"],"rows":[["**천연건축재료(Natural Material)**","화학 성분 전혀 없음","황토, 목재, 석재, 짚"],["**친환경재료(Environmental Material)**","환경 기준치에 맞춰 가공, 무독성","혼합단열재, 분해성 플라스틱, 친환경 페인트"],["**지속가능한 재료(Sustainable Material)**","영구 사용, 생산 때 부하 큼","스틸, 동판, 알루미늄, 강철"],["**재활용재료(Recycling Material)**","폐자재를 새 원료로","재생섬유 흡음재, 재활용 섬유판재, **재활용골재(Recycled Aggregate)**"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**재활용재료(Recycling Material)** 의 원료로 슬라이드에 나오지 않은 것은?","choices":["폐콘크리트","폐목재","폐지","폐금속"],"a":3,"why":"슬라이드가 든 원료는 폐콘크리트, 폐목재, 폐지, 폐플라스틱 네 가지예요."},{"kind":"check","q":"네 유사개념 중 '영구적으로 사용할 수 있는 금속재' 는?","choices":["**천연건축재료(Natural Material)**","**친환경재료(Environmental Material)**","**지속가능한 재료(Sustainable Material)**","**재활용재료(Recycling Material)**"],"a":2,"why":"스틸, 동판, 알루미늄, 강철 등 금속재가 **지속가능한 재료(Sustainable Material)** 예요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"친환경 건축재료의 유사개념은 천연건축재료, 친환경재료, 지속가능한 재료, 재활용재료 네 가지이다.","ko":"네 이름을 순서대로 쓰고, 뒤에 한 줄씩 뜻을 붙이면 좋아요.","tip":"'천연 - 친환경 - 지속가능 - 재활용' 네 글자씩 끊어서 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["사진 이름표의 크기 단위가 m 로 적혀 있어요. 골재 크기라서 mm 로 보이지만 슬라이드 표기는 m 예요.","품질 인증은 **친환경재료(Environmental Material)** 쪽이 **한국공기청정협회**, 골재 안내문은 한국산업규격이에요.","**재활용재료(Recycling Material)** 도 고품질일 수 있다는 것이 사진의 요점이에요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.4842,0.063],"c":[0.0269,0.0701,0.5327,0.095],"r":7.4765,"img":"img/E2/walk/p011_h.jpg"},"parts":[{"b":[0.065,0.225,0.41,0.05],"c":[0.0445,0.195,0.451,0.11],"r":5.4667,"img":"img/E2/walk/p011_23_01.jpg","say":"제목 줄. 4) 재활용 재료 (Recycling Material) 이에요."},{"b":[0.125,0.285,0.6,0.05],"c":[0.095,0.2433,0.66,0.1333],"r":6.6017,"img":"img/E2/walk/p011_23_02.jpg","say":"폐자재 중에서 '새롭게 원료로 이용하여' 생산된 재료예요."},{"b":[0.125,0.345,0.8,0.05],"c":[0.085,0.2811,0.88,0.1778],"r":6.5992,"img":"img/E2/walk/p011_23_03.jpg","say":"원료 네 가지. 폐콘크리트, 폐목재, 폐지, 폐플라스틱이에요."},{"b":[0.125,0.405,0.58,0.05],"c":[0.096,0.3656,0.638,0.1289],"r":6.5994,"img":"img/E2/walk/p011_23_04.jpg","say":"예시 세 가지. 재생섬유 흡음재, 재활용 섬유판재, **재활용골재(Recycled Aggregate)** 예요."},{"b":[0.14,0.795,0.74,0.04],"c":[0.103,0.7328,0.814,0.1645],"r":6.5978,"img":"img/E2/walk/p011_23_05.jpg","say":"사진 이름표예요. 콘크리트용 (25m), 도로공사용 (40m), 아스팔트콘크리트용 (19m)."},{"b":[0.185,0.862,0.63,0.06],"c":[0.1535,0.822,0.693,0.14],"r":6.6,"img":"img/E2/walk/p011_23_06.jpg","say":"회사 안내문이에요. 폐기물관리법 기준과 한국산업규격에 맞게 생산된다고 적혀 있어요."}]}},{"p":12,"title":"선정기준 4개 분야와 6개 항목","terms":["Human","Energy","Environmental Impact","Recycling or Reuse"],"pass1":[{"kind":"say","lines":["여기부터는 재료에 성적을 매기는 이야기예요.","과목이 4개, 세부 평가가 6개, 겹치는 것까지 세면 10개예요.","이 쪽은 과목 4개와 세부 6개의 이름을 외우는 쪽이에요."]},{"kind":"analogy","head":"학교 성적표처럼 생겼어요","scene":"성적표에는 과목이 있고, 과목마다 세부 평가가 있어요. 1학기, 2학기처럼 시기별로도 매겨요.","map":[["과목 4개","선정기준 4개 분야"],["세부 평가 6개","H1, H2, E, E.I1, E.I2, R1"],["학기별 성적","제조, 생산 / 사용 / 폐기, 활용"],["겹쳐 세는 칸","중복 검토되는 항목 포함 총 10개"]]}],"pass2":[{"kind":"points","head":"선정기준 4개 분야","items":["**인체유해성(Human)**","**에너지소비(Energy)**","**환경부하(Environmental Impact)**","**재생 또는 재활용(Recycling or Reuse)**","6개 항목 / 중복 검토되는 항목 포함 총 10개 항목에서 평가 가능해요."]},{"kind":"compare","head":"분야별 세부 항목과 기호 (슬라이드 표 그대로)","cols":["분야","세부 항목","기호"],"rows":[["**인체유해성(Human)**","원재료의 채취, 생산, 가공과정이나 사용 중에 인체에 미치는 유해성의 정도","H1"],["**인체유해성(Human)**","실내 환경의 조정이나 건강을 증진시키는 효과의 정도","H2"],["**에너지소비(Energy)**","원재료의 채취, 생산, 가공과정에서 요구되는 에너지소비 정도","E"],["**에너지소비(Energy)**","건축재료의 운송, 이용과정에서 요구되는 에너지소비 정도","E"],["**에너지소비(Energy)**","이용 후 폐기과정에서 요구되는 에너지소비 정도","E"],["**환경부하(Environmental Impact)**","원재료의 채취, 생산, 가공과정에서 환경외손이나 자원고갈로 인한 환경부하 정도","E.I1"],["**환경부하(Environmental Impact)**","독성, 가스, 미세먼지의 발생 정도","E.I2"],["**재생 또는 재활용(Recycling or Reuse)**","폐기 후 재생 또는 재활용의 가능성 여부","R1"]]},{"kind":"points","head":"기호를 읽는 법","items":["H 는 **인체유해성(Human)** 의 머리글자예요. H1 은 유해성, H2 는 건강 증진 효과예요.","E 는 **에너지소비(Energy)** 예요. 채취와 생산, 운송과 이용, 폐기 세 곳에 똑같이 E 로 적혀요.","E.I 는 **환경부하(Environmental Impact)** 예요. E.I1 은 환경외손과 자원고갈, E.I2 는 독성, 가스, 미세먼지예요.","R1 은 **재생 또는 재활용(Recycling or Reuse)** 의 가능성 여부예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"선정기준 4개 분야에 들어가지 않는 것은?","choices":["**인체유해성(Human)**","**에너지소비(Energy)**","경제성","**재생 또는 재활용(Recycling or Reuse)**"],"a":2,"why":"4개 분야는 인체유해성, 에너지소비, 환경부하, 재생 또는 재활용이에요. 경제성은 없어요."},{"kind":"check","q":"'독성, 가스, 미세먼지의 발생 정도' 에 붙은 기호는?","choices":["H2","E","E.I1","E.I2"],"a":3,"why":"**환경부하(Environmental Impact)** 의 둘째 항목이라 E.I2 예요. E.I1 은 환경외손이나 자원고갈로 인한 부하예요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"환경적 관점의 건축재료 선정기준은 인체유해성, 에너지소비, 환경부하, 재생 또는 재활용의 4개 분야이며, 6개 항목과 중복 검토 항목을 포함해 총 10개 항목에서 평가한다.","ko":"분야 4개 이름, 항목 6개, 총 10개 세 숫자가 모두 들어가야 해요.","tip":"'4분야 6항목 10칸' 으로 숫자를 묶어서 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["'6개 항목' 과 '총 10개 항목' 을 같이 외워요. 10개는 중복 검토 항목을 포함한 수예요.","E 는 세 줄 모두 같은 기호 E 예요. E1, E2, E3 이 아니에요.","슬라이드는 '환경외손' 이라고 적었어요. 표기는 슬라이드를 그대로 따라요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.5966,0.063],"c":[0.0213,0.0701,0.6563,0.095],"r":9.2112,"img":"img/E2/walk/p012_h.jpg"},"parts":[{"b":[0.1,0.225,0.83,0.05],"c":[0.0585,0.1578,0.913,0.1845],"r":6.598,"img":"img/E2/walk/p012_23_01.jpg","say":"첫 줄에 4개 분야 이름이 다 나와요. 인체유해성, 에너지 소비, 환경부하, 재생 또는 재활용."},{"b":[0.1,0.285,0.73,0.05],"c":[0.0635,0.2289,0.803,0.1622],"r":6.6009,"img":"img/E2/walk/p012_23_02.jpg","say":"둘째 줄. 6개 항목 / 중복 검토되는 항목 포함 총 10개 항목에서 평가 가능."},{"b":[0.14,0.388,0.64,0.14],"c":[0.108,0.372,0.704,0.172],"r":5.4574,"img":"img/E2/walk/p012_23_03.jpg","say":"**인체유해성(Human)** 묶음이에요. 아래 두 줄 끝에 (H1), (H2) 가 붙어 있어요."},{"b":[0.14,0.523,0.53,0.18],"c":[0.1135,0.507,0.583,0.212],"r":3.6667,"img":"img/E2/walk/p012_23_04.jpg","say":"**에너지소비(Energy)** 묶음이에요. 세 줄 모두 끝이 (E) 라서 E 가 세 번 나와요."},{"b":[0.14,0.7,0.68,0.14],"c":[0.106,0.684,0.748,0.172],"r":5.7984,"img":"img/E2/walk/p012_23_05.jpg","say":"**환경부하(Environmental Impact)** 묶음이에요. (E.I1) 과 (E.I2) 두 줄이에요."},{"b":[0.14,0.838,0.37,0.09],"c":[0.1215,0.822,0.407,0.122],"r":4.4481,"img":"img/E2/walk/p012_23_06.jpg","say":"**재생 또는 재활용(Recycling or Reuse)** 묶음이에요. (R1) 한 줄뿐이에요."}]}},{"p":13,"title":"재료의 Life cycle 에 따른 친환경성 평가표","terms":["Life Cycle","Human","Energy","Environmental Impact","Recycling or Reuse","Natural Material","Environmental Material","Sustainable Material","Recycling Material"],"pass1":[{"kind":"say","lines":["앞 쪽에서 만든 10칸짜리 성적표에 네 재료의 점수를 채운 쪽이에요.","칸에는 플러스와 마이너스만 들어가요. 플러스는 좋다, 마이너스는 나쁘다예요.","한 줄만 기억하면 돼요. 천연재료는 전부 플러스예요."]}],"pass2":[{"kind":"figure","head":"평가표를 그대로 옮겼어요","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"54\" y=\"30\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b1\">과정<\/text><text x=\"54\" y=\"62\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b1\">평가기준<\/text><rect x=\"108\" y=\"12\" width=\"144\" height=\"28\" rx=\"2\" class=\"box b1\"/><text x=\"180\" y=\"31\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b1\">제조, 생산<\/text><rect x=\"252\" y=\"12\" width=\"108\" height=\"28\" rx=\"2\" class=\"box b1\"/><text x=\"306\" y=\"31\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b1\">사용<\/text><rect x=\"360\" y=\"12\" width=\"108\" height=\"28\" rx=\"2\" class=\"box b1\"/><text x=\"414\" y=\"31\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b1\">폐기, 활용<\/text><rect x=\"108\" y=\"44\" width=\"36\" height=\"28\" rx=\"2\" class=\"box2 b1\"/><text x=\"126\" y=\"63\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b1\">H1<\/text><rect x=\"144\" y=\"44\" width=\"36\" height=\"28\" rx=\"2\" class=\"box2 b1\"/><text x=\"162\" y=\"63\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b1\">E<\/text><rect x=\"180\" y=\"44\" width=\"36\" height=\"28\" rx=\"2\" class=\"box2 b1\"/><text x=\"198\" y=\"63\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b1\">E.I1<\/text><rect x=\"216\" y=\"44\" width=\"36\" height=\"28\" rx=\"2\" class=\"box2 b1\"/><text x=\"234\" y=\"63\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b1\">E.I2<\/text><rect x=\"252\" y=\"44\" width=\"36\" height=\"28\" rx=\"2\" class=\"box2 b1\"/><text x=\"270\" y=\"63\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b1\">H2<\/text><rect x=\"288\" y=\"44\" width=\"36\" height=\"28\" rx=\"2\" class=\"box2 b1\"/><text x=\"306\" y=\"63\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b1\">E<\/text><rect x=\"324\" y=\"44\" width=\"36\" height=\"28\" rx=\"2\" class=\"box2 b1\"/><text x=\"342\" y=\"63\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b1\">E.I2<\/text><rect x=\"360\" y=\"44\" width=\"36\" height=\"28\" rx=\"2\" class=\"box2 b1\"/><text x=\"378\" y=\"63\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b1\">E<\/text><rect x=\"396\" y=\"44\" width=\"36\" height=\"28\" rx=\"2\" class=\"box2 b1\"/><text x=\"414\" y=\"63\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b1\">E.I2<\/text><rect x=\"432\" y=\"44\" width=\"36\" height=\"28\" rx=\"2\" class=\"box2 b1\"/><text x=\"450\" y=\"63\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b1\">R1<\/text><text x=\"54\" y=\"98\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b2\">천연재료<\/text><text x=\"126\" y=\"99\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b2\">+<\/text><text x=\"162\" y=\"99\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b2\">+<\/text><text x=\"198\" y=\"99\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b2\">+<\/text><text x=\"234\" y=\"99\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b2\">+<\/text><text x=\"270\" y=\"99\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b2\">+<\/text><text x=\"306\" y=\"99\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b2\">+<\/text><text x=\"342\" y=\"99\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b2\">+<\/text><text x=\"378\" y=\"99\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b2\">+<\/text><text x=\"414\" y=\"99\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b2\">+<\/text><text x=\"450\" y=\"99\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b2\">+<\/text><text x=\"54\" y=\"132\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b3\">친환경재료<\/text><text x=\"126\" y=\"133\" font-size=\"18\" text-anchor=\"middle\" class=\"tm b3\">-<\/text><text x=\"162\" y=\"133\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b3\">+<\/text><text x=\"198\" y=\"133\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b3\">+<\/text><text x=\"234\" y=\"133\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b3\">+<\/text><text x=\"270\" y=\"133\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b3\">+<\/text><text x=\"306\" y=\"133\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b3\">+<\/text><text x=\"342\" y=\"133\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b3\">+<\/text><text x=\"378\" y=\"133\" font-size=\"18\" text-anchor=\"middle\" class=\"tm b3\">-<\/text><text x=\"414\" y=\"133\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b3\">+<\/text><text x=\"450\" y=\"133\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b3\">+<\/text><text x=\"54\" y=\"166\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b4\">지속가능<\/text><text x=\"126\" y=\"167\" font-size=\"18\" text-anchor=\"middle\" class=\"tm b4\">-<\/text><text x=\"162\" y=\"167\" font-size=\"18\" text-anchor=\"middle\" class=\"tm b4\">-<\/text><text x=\"198\" y=\"167\" font-size=\"18\" text-anchor=\"middle\" class=\"tm b4\">-<\/text><text x=\"234\" y=\"167\" font-size=\"18\" text-anchor=\"middle\" class=\"tm b4\">-<\/text><text x=\"270\" y=\"167\" font-size=\"18\" text-anchor=\"middle\" class=\"tm b4\">-<\/text><text x=\"306\" y=\"167\" font-size=\"18\" text-anchor=\"middle\" class=\"tm b4\">-<\/text><text x=\"342\" y=\"167\" font-size=\"18\" text-anchor=\"middle\" class=\"tm b4\">-<\/text><text x=\"378\" y=\"167\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b4\">+<\/text><text x=\"414\" y=\"167\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b4\">+<\/text><text x=\"450\" y=\"167\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b4\">+<\/text><text x=\"54\" y=\"200\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b5\">재활용재료<\/text><text x=\"162\" y=\"201\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b5\">+<\/text><text x=\"198\" y=\"201\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b5\">+<\/text><text x=\"234\" y=\"201\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b5\">+<\/text><text x=\"378\" y=\"201\" font-size=\"18\" text-anchor=\"middle\" class=\"tb b5\">+<\/text><text x=\"414\" y=\"201\" font-size=\"18\" text-anchor=\"middle\" class=\"tm b5\">-<\/text><text x=\"450\" y=\"201\" font-size=\"18\" text-anchor=\"middle\" class=\"tm b5\">-<\/text><line x1=\"252\" y1=\"12\" x2=\"252\" y2=\"212\" class=\"e b1\"/><line x1=\"360\" y1=\"12\" x2=\"360\" y2=\"212\" class=\"e b1\"/><text x=\"240\" y=\"240\" font-size=\"13\" text-anchor=\"middle\" class=\"tm b5\">+ 긍정효과, - 부정효과, 빈칸은 공란<\/text><\/svg>","caption":"한 줄씩 켜져요. 천연재료는 10칸 모두 +, 지속가능한 재료는 폐기, 활용 칸 3개만 + 예요.","builds":5},{"kind":"points","head":"표의 머리 두 줄","items":["과정은 제조, 생산 / 사용 / 폐기, 활용 세 덩어리예요.","제조, 생산 칸은 H1, E, E.I1, E.I2 네 개예요.","사용 칸은 H2, E, E.I2 세 개예요.","폐기, 활용 칸은 E, E.I2, R1 세 개예요. 오른쪽에 큰 화살표로 '10개' 라고 적혀 있어요."]},{"kind":"steps","head":"6개 항목이 어떻게 10개가 되는지 세어 봐요","given":"기호는 H1, H2, E, E.I1, E.I2, R1 여섯 개예요.","steps":["제조, 생산 과정: H1, E, E.I1, E.I2 이므로 4개","사용 과정: H2, E, E.I2 이므로 3개","폐기, 활용 과정: E, E.I2, R1 이므로 3개","4 더하기 3 더하기 3 은 10 이에요. E 가 세 번, E.I2 도 세 번 겹쳐요."],"answer":"6개 항목, 중복 포함 총 10개 항목"},{"kind":"compare","head":"네 재료의 10칸을 글로 읽어요","cols":["재료","제조, 생산 (H1 E E.I1 E.I2)","사용 (H2 E E.I2)","폐기, 활용 (E E.I2 R1)"],"rows":[["천연재료(N.M)","+ + + +","+ + +","+ + +"],["친환경재료(E.M)","- + + +","+ + +","- + +"],["지속가능한 재료(S.M)","- - - -","- - -","+ + +"],["재활용재료(R.M)","공란 + + +","공란 공란 공란","+ - -"]]},{"kind":"points","head":"표 아래 네 줄 설명","items":["**천연건축재료(Natural Material)**: 10개 항목에 대해 긍정적인 효과예요.","**친환경재료(Environmental Material)**: 제조과정에서 인체유해성 판단이 불분명해요. 대체로 제조, 생산, 시공 과정에서 긍정적인 효과예요.","**지속가능한 재료(Sustainable Material)**: 폐기, 재활용 과정을 제외하고는 모든 항목에서 부정적 영향이에요.","**재활용재료(Recycling Material)**: 어떠한 원재료를 재활용하였느냐에 따라 평가가 달라질 수 있어 공란이 많아요.","재활용 재료는 **지속가능한 재료(Sustainable Material)** 에 비하여 제조, 생산과정에서 긍정적 영향이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"평가표에서 10개 항목 모두 긍정적인 효과인 재료는?","choices":["**천연건축재료(Natural Material)**","**친환경재료(Environmental Material)**","**지속가능한 재료(Sustainable Material)**","**재활용재료(Recycling Material)**"],"a":0,"why":"천연재료(N.M) 줄만 열 칸이 전부 + 예요."},{"kind":"check","q":"'폐기, 재활용 과정을 제외하고는 모든 항목에서 부정적 영향' 인 재료는?","choices":["**천연건축재료(Natural Material)**","**친환경재료(Environmental Material)**","**지속가능한 재료(Sustainable Material)**","**재활용재료(Recycling Material)**"],"a":2,"why":"**지속가능한 재료(Sustainable Material)** 는 폐기, 활용 칸 세 개만 + 예요. 금속재의 생산 부하가 크다는 앞 쪽 내용과 같아요."},{"kind":"check","q":"**재활용재료(Recycling Material)** 칸에 공란이 많은 까닭은?","choices":["평가를 아직 안 해서","어떠한 원재료를 재활용하였느냐에 따라 평가가 달라질 수 있어서","항목 수가 모자라서","모두 부정적이어서"],"a":1,"why":"슬라이드 설명 그대로예요. 공란은 '나쁨' 이 아니라 '평가가 달라질 수 있음' 이라는 뜻이에요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"천연재료는 전과정 10개 항목에서 긍정적이고, 지속가능한 재료는 폐기와 재활용 과정을 제외한 모든 항목에서 부정적이며, 재활용재료는 원재료에 따라 평가가 달라져 공란이 많다.","ko":"네 재료 중 세 줄만 정확히 써도 대부분의 점수가 나와요.","tip":"'천연은 다 플러스, 지속가능은 끝만 플러스' 로 짝지어 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["표의 빈칸과 마이너스는 다른 뜻이에요. 빈칸은 공란, 마이너스는 부정효과예요.","**친환경재료(Environmental Material)** 의 마이너스는 제조의 H1 과 폐기, 활용의 E 두 칸이에요.","슬라이드 표기는 'Life cycle' 이에요. 우리말로는 **전과정(Life Cycle)** 이라고 읽어요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.5966,0.063],"c":[0.0213,0.0701,0.6563,0.095],"r":9.2112,"img":"img/E2/walk/p013_h.jpg"},"parts":[{"b":[0.1,0.196,0.45,0.05],"c":[0.0775,0.166,0.495,0.11],"r":6.0,"img":"img/E2/walk/p013_25_01.jpg","say":"제목 줄이에요. '재료의 Life cycle 에 따른 친환경성 평가' 라고 적혀 있어요."},{"b":[0.26,0.272,0.68,0.055],"c":[0.226,0.2239,0.748,0.1511],"r":6.6005,"img":"img/E2/walk/p013_25_02.jpg","say":"표 첫 줄 '과정' 이에요. 제조, 생산 / 사용 / 폐기, 활용 세 칸으로 나뉘어요."},{"b":[0.26,0.316,0.72,0.05],"c":[0.208,0.261,0.792,0.16],"r":6.6,"img":"img/E2/walk/p013_25_03.jpg","say":"표 둘째 줄 '평가기준' 이에요. 왼쪽부터 H1 E E.I1 E.I2 H2 E E.I2 E E.I2 R1 열 칸이고 오른쪽 화살표에 10개라고 적혀 있어요."},{"b":[0.12,0.362,0.75,0.05],"c":[0.0825,0.3037,0.825,0.1667],"r":6.5987,"img":"img/E2/walk/p013_25_04.jpg","say":"천연재료(N.M) 줄이에요. 열 칸이 전부 + 예요."},{"b":[0.12,0.466,0.75,0.05],"c":[0.0825,0.4077,0.825,0.1667],"r":6.5987,"img":"img/E2/walk/p013_25_05.jpg","say":"지속가능한 재료(S.M) 줄이에요. 앞 일곱 칸이 -, 뒤 세 칸만 + 예요."},{"b":[0.1,0.61,0.82,0.35],"c":[0.059,0.5925,0.902,0.385],"r":3.1238,"img":"img/E2/walk/p013_25_06.jpg","say":"표 아래 설명 네 줄이에요. 재료마다 한 줄씩 결론을 적어 두었어요."}]}},{"p":14,"title":"주요 건축재료 별 특성: **목재(Wood)** 와 **점토벽돌(Clay Brick)**","terms":["Wood","Clay Brick"],"pass1":[{"kind":"say","lines":["1번 덩어리의 마지막 쪽이에요. 재료 하나하나의 성적표를 보는 쪽이에요.","표에는 두 줄이 있어요. **목재(Wood)** 와 **점토벽돌(Clay Brick)** 이에요.","한 줄 요약은 이래요. 목재는 장점이 아주 많고, 점토벽돌은 에너지가 아주 많이 들어요."]}],"pass2":[{"kind":"points","head":"쪽 위 두 줄을 그대로 읽어요","items":["구조체를 이루는 일반적인 건축재료는 목재, 점토벽돌 및 기와, 콘크리트, 점토 등이에요.","재료별로 건축물에 쓰이는 용도를 봐요.","생산방법 및 생산과정에서의 에너지 소비 정도를 봐요.","각 재료가 갖는 장점과 단점을 봐요."]},{"kind":"compare","head":"표의 앞 세 칸","cols":["건축재료","용도","생산"],"rows":[["**목재(Wood)**","건물 외장, 실내, 외장재","산림"],["**점토벽돌(Clay Brick)**, 점토","벽 / 지붕","점토 제품으로 에너지 투입이 매우 많음"]]},{"kind":"points","head":"**목재(Wood)** 의 장점 (표 그대로)","items":["다양한 부분에 사용 가능","기술 사양이 우수함 (열저장력, 통기성, 단열, 습도조절 등)","환경성이 검증된 원료","생산과정에서 환경 부하가 적고, 지속적 생산이 가능한 재료","CO2 배출 및 기후에 영향이 없음","목조 건축에서는 약한 목재도 사용이 가능함","대상 지역에서 생산이 가능함 (표에 같은 줄이 두 번 적혀 있어요)","재활용과 폐기물 처리에 문제가 없음","원자재 사용시 유해물질이 없음"]},{"kind":"compare","head":"두 재료의 단점","cols":["재료","단점 (표 그대로)"],"rows":[["**목재(Wood)**","사용되는 부분에 따라 습기 방지에 대한 대책이 필요함 / 지속적으로 생산하지 않는 경우 친환경적이지 못함"],["**점토벽돌(Clay Brick)**, 점토","점토 채굴 시 자연을 훼손하게 됨 / 유한 자원의 소모 / 일반적으로 추가적인 단열재 필요 / 기와의 활용은 제한적으로만 가능함"]]},{"kind":"points","head":"**점토벽돌(Clay Brick)** 의 장점은 두 줄뿐이에요","items":["천연 자재예요.","지하 건축물에 벽돌의 활용이 가능함.","**목재(Wood)** 장점 아홉 줄과 견주면 아주 짧아요. 이 길이 차이 자체가 답의 실마리예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"표에서 **점토벽돌(Clay Brick)** 의 생산 칸에 적힌 말은?","choices":["산림","점토 제품으로 에너지 투입이 매우 많음","재활용 원료","지역 생산"],"a":1,"why":"목재의 생산 칸은 '산림', 점토벽돌과 점토의 생산 칸은 '점토 제품으로 에너지 투입이 매우 많음' 이에요."},{"kind":"check","q":"**목재(Wood)** 의 단점으로 표에 적힌 것은?","choices":["CO2 배출이 많음","사용되는 부분에 따라 습기 방지에 대한 대책이 필요함","지하 건축물에 쓸 수 없음","기와의 활용이 제한적임"],"a":1,"why":"목재 단점은 습기 방지 대책 필요와, 지속적으로 생산하지 않는 경우 친환경적이지 못함 두 줄이에요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"목재는 용도가 넓고 기술 사양이 우수하며 CO2 배출이 없고 재활용과 폐기물 처리에 문제가 없으나 습기 방지 대책이 필요하고, 점토벽돌은 천연 자재이지만 생산에 에너지 투입이 매우 많고 채굴 시 자연을 훼손한다.","ko":"두 재료를 한 문장 안에서 견주어 쓰면 점수가 잘 나와요.","tip":"'목재는 길게, 점토는 짧게' 로 장점 칸 길이를 떠올리며 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["표에 '대상 지역에서 생산이 가능함' 이 두 번 적혀 있어요. 슬라이드 자체의 중복이에요.","기술 사양 괄호 안 네 가지는 열저장력, 통기성, 단열, 습도조절이에요. 강도가 아니에요.","**점토벽돌(Clay Brick)** 의 단점에 '일반적으로 추가적인 단열재 필요' 가 들어 있어요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2994,0.063],"c":[0.0362,0.0701,0.3293,0.095],"r":4.6218,"img":"img/E2/walk/p014_h.jpg"},"parts":[{"b":[0.1,0.218,0.83,0.13],"c":[0.0585,0.1908,0.913,0.1845],"r":6.598,"img":"img/E2/walk/p014_25_01.jpg","say":"쪽 위 두 줄이에요. 일반적인 건축재료 목록과, 표에서 무엇을 볼지가 적혀 있어요."},{"b":[0.125,0.405,0.74,0.05],"c":[0.088,0.3478,0.814,0.1645],"r":6.5978,"img":"img/E2/walk/p014_25_02.jpg","say":"표 머리줄이에요. 건축재료, 용도, 생산, 장점, 단점 다섯 칸이에요."},{"b":[0.125,0.455,0.74,0.35],"c":[0.088,0.4375,0.814,0.385],"r":2.819,"img":"img/E2/walk/p014_25_03.jpg","say":"**목재(Wood)** 줄이에요. 장점 칸이 아홉 줄로 가장 길어요."},{"b":[0.125,0.812,0.74,0.16],"c":[0.088,0.796,0.814,0.192],"r":5.6528,"img":"img/E2/walk/p014_25_04.jpg","say":"**점토벽돌(Clay Brick)** 줄이에요. 생산 칸에 '에너지 투입이 매우 많음' 이 적혀 있어요."}]}},{"p":15,"title":"**목재(Wood)** 의 특성 8가지와 단점 3가지","terms":["Wood","Breathability","Micropore","Preservative","Phenol","Formalin"],"pass1":[{"kind":"say","lines":["2장 천연 건축재료가 시작돼요. 첫 재료는 **목재(Wood)** 예요.","이 쪽의 이야기는 하나예요. 나무는 숨을 쉬는 재료예요.","숨을 쉬니까 좋고, 숨을 쉬니까 물에 약해요. 장점과 단점이 한 뿌리예요."]},{"kind":"analogy","head":"나무는 숨 쉬는 피부예요","scene":"사람 피부에는 땀구멍이 있어서 숨을 쉬고 땀을 내요. 나무에도 아주 작은 구멍이 있어서 공기와 습기가 드나들어요.","map":[["피부의 땀구멍","**미세기공(Micropore)**"],["피부가 숨 쉬는 것","**통기성(Breathability)**"],["땀을 머금는 속옷","습기를 흡수하는 **목재(Wood)**"],["피부에 바르는 독한 화장품","유독성 **방부제(Preservative)** 와 접합제"]]},{"kind":"figure","head":"숨 쉬는 **목재(Wood)**","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"58\" width=\"200\" height=\"132\" rx=\"2\" class=\"n3 b1\"/><circle cx=\"60\" cy=\"94\" r=\"5\" class=\"n b1\"/><circle cx=\"96\" cy=\"120\" r=\"5\" class=\"n b1\"/><circle cx=\"140\" cy=\"90\" r=\"5\" class=\"n b1\"/><circle cx=\"180\" cy=\"130\" r=\"5\" class=\"n b1\"/><circle cx=\"70\" cy=\"160\" r=\"5\" class=\"n b1\"/><circle cx=\"126\" cy=\"164\" r=\"5\" class=\"n b1\"/><circle cx=\"186\" cy=\"86\" r=\"5\" class=\"n b1\"/><circle cx=\"160\" cy=\"160\" r=\"5\" class=\"n b1\"/><text x=\"120\" y=\"46\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">나무 속 작은 구멍<\/text><line x1=\"40\" y1=\"230\" x2=\"83\" y2=\"201\" class=\"e2 b2\"/><polygon points=\"90,196 85,205 80,197\" class=\"arrow b2\"/><line x1=\"150\" y1=\"196\" x2=\"193\" y2=\"225\" class=\"e2 b2\"/><polygon points=\"200,230 190,229 195,221\" class=\"arrow b2\"/><text x=\"120\" y=\"252\" font-size=\"14\" text-anchor=\"middle\" class=\"t b2\">습기와 공기가 드나들어요<\/text><rect x=\"250\" y=\"52\" width=\"220\" height=\"40\" rx=\"2\" class=\"box2 b3\"/><text x=\"360\" y=\"77\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b3\">건축 수명 100년 이상<\/text><rect x=\"250\" y=\"108\" width=\"220\" height=\"40\" rx=\"2\" class=\"box2 b3\"/><text x=\"360\" y=\"133\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b3\">건축재료의 95%까지 대체<\/text><rect x=\"250\" y=\"164\" width=\"220\" height=\"40\" rx=\"2\" class=\"box b3\"/><text x=\"360\" y=\"189\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b3\">약점: 부패, 벌레, 버섯, 불<\/text><\/svg>","caption":"**미세기공(Micropore)** 로 습기와 공기가 드나들어요. 오른쪽은 외울 숫자 두 개와 약점이에요.","builds":3}],"pass2":[{"kind":"points","head":"**목재(Wood)** 의 특성 1~4 (슬라이드 번호 그대로)","items":["1) 재생될 수 있는 건축재료 중에서 가장 비중 있는 재료예요. 괄호에 (많이 쓰임) 이라고 적혀 있어요.","2) 인간에게 쾌적함을 주는 긍정적 영향: 자연성, 친근한 색채, 고유의 향 (실험).","3) 높은 **통기성(Breathability)** 및 흡수 능력: **미세기공(Micropore)** 덕분이에요.","4) 가변성과 응용성이 뛰어나 부분적인 교체, 전면적인 개조 등이 용이해요."]},{"kind":"points","head":"**목재(Wood)** 의 특성 5~8","items":["5) 건축 수명 100년 이상 가능해요.","6) 생산현장이 널리 분포하여 에너지 절약적이에요.","7) 적용 범위가 넓음: 모든 건축재료의 95%까지 대체 가능하고 구조재부터 장식까지 써요.","8) 직접 재활용 가능, 자연으로 순환 용이해요.","8) 괄호: 유독성 **방부제(Preservative)** 와 접합제를 사용하면 안 돼요."]},{"kind":"points","head":"**목재(Wood)** 의 단점 3가지","items":["1) 산업용 가공 시, 유독성 접합제(**페놀(Phenol)** 또는 **포르말린(Formalin)**)가 첨가되어 인체에 해로울 가능성이 있어요.","2) 부적합 가공 시, 목재의 질이 떨어지고 목재 자체에서 유해 성분이 발산될 가능성이 있어요.","3) 부패되기 쉽고, 벌레나 버섯, 화재에 취약해요."]},{"kind":"compare","head":"장점과 단점을 짝지어 봐요","cols":["장점","그 반대편 단점"],"rows":[["**통기성(Breathability)** 와 흡수 능력","부패되기 쉬움"],["자연으로 순환 용이","유독성 **방부제(Preservative)** 와 접합제를 쓰면 순환이 어려움"],["인간에게 쾌적함","가공 때 **페놀(Phenol)**, **포르말린(Formalin)** 은 인체에 해로울 가능성"],["적용 범위 95%","벌레, 버섯, 화재에 취약"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**미세기공(Micropore)** 덕분에 **목재(Wood)** 가 갖는 특성은?","choices":["높은 **통기성(Breathability)** 및 흡수 능력","불에 강함","벌레에 강함","접합제가 필요 없음"],"a":0,"why":"슬라이드 3) 은 '높은 통기성 및 흡수 능력 : 미세 기공' 이에요."},{"kind":"check","q":"**목재(Wood)** 특성에 나온 숫자로 옳은 것은?","choices":["건축 수명 50년, 건축재료의 50% 대체","건축 수명 100년 이상, 건축재료의 95%까지 대체","건축 수명 30년, 건축재료의 100% 대체","건축 수명 100년 이상, 건축재료의 59%까지 대체"],"a":1,"why":"5) 건축 수명 100년 이상 가능, 7) 모든 건축재료의 95%까지 대체 가능이에요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"목재는 재생될 수 있는 건축재료 중 가장 비중이 크고, 미세 기공에 의한 높은 통기성과 흡수 능력을 가지며, 건축 수명 100년 이상, 모든 건축재료의 95%까지 대체가 가능하다.","ko":"특성 여덟 줄 중 1), 3), 5), 7) 네 줄만 써도 핵심이 들어가요.","tip":"'가장 많이 - 숨 쉬고 - 100년 - 95%' 네 마디로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["유독성 접합제는 **페놀(Phenol)** 또는 **포르말린(Formalin)** 이에요. 둘 중 하나만 써도 되지만 이름을 바꾸면 틀려요.","95% 는 적용 범위(대체 가능 비율), 100년은 건축 수명이에요. 숫자를 바꿔 내기 좋아요.","**목재(Wood)** 는 부패, 벌레, 버섯, 화재에 약해요. 튼튼하다고 불에 강한 것은 아니에요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.0757,0.063],"c":[0,0.0701,0.2,0.095],"r":2.807,"img":"img/E2/walk/p015_h.jpg"},"parts":[{"b":[0.095,0.222,0.13,0.05],"c":[0.06,0.192,0.2,0.11],"r":2.4242,"img":"img/E2/walk/p015_24_01.jpg","say":"윗덩어리 제목이에요. 여기부터 여덟 줄이 **목재(Wood)** 의 특성이에요."},{"b":[0.065,0.275,0.86,0.17],"c":[0.022,0.259,0.946,0.202],"r":6.2442,"img":"img/E2/walk/p015_24_02.jpg","say":"1)부터 4)까지예요. 3) 에 **통기성(Breathability)** 와 **미세기공(Micropore)** 가 나와요."},{"b":[0.065,0.49,0.82,0.2],"c":[0.024,0.474,0.902,0.232],"r":5.1839,"img":"img/E2/walk/p015_24_03.jpg","say":"5)부터 8)까지예요. 숫자 두 개, 100년과 95% 가 여기 있어요."},{"b":[0.095,0.755,0.1,0.05],"c":[0.045,0.725,0.2,0.11],"r":2.4242,"img":"img/E2/walk/p015_24_04.jpg","say":"아랫덩어리 제목 '단점' 이에요. 세 줄뿐이라 통째로 외우기 좋아요."},{"b":[0.065,0.808,0.87,0.16],"c":[0.0215,0.7913,0.957,0.1933],"r":6.6011,"img":"img/E2/walk/p015_24_05.jpg","say":"단점 1)2)3) 이에요. 1) 은 '산업용 가공 시' 라는 조건이 앞에 붙어 있어요."}]}},{"p":16,"title":"목구조에 사용되는 목재의 분류표","terms":["Structural Panel","Glue Laminated Timbers","Laminated Veneer Lumber","I-Joist","Preservative-treated Wood"],"pass1":[{"kind":"say","lines":["여기부터 27쪽까지는 목구조에 쓰는 가공 목재 다섯 가지를 봐요.","이 쪽은 그 다섯 가지를 한 표에 모은 지도예요.","가로는 재료 다섯, 세로는 건축부위 일곱이고 쓰는 곳에 동그라미가 있어요."]},{"kind":"analogy","head":"나무로 만든 블록 장난감이에요","scene":"작은 나무 조각을 겹겹이 붙이면 길고 크고 휘어진 모양도 만들 수 있어요. 붙이는 방향에 따라 튼튼함도 달라져요.","map":[["얇은 종이를 엇갈려 붙인 두꺼운 종이","**구조용 판넬(Structural Panel)**"],["작은 막대를 이어 붙여 만든 긴 막대","**글루램(Glue Laminated Timbers)**"],["결을 한 방향으로 모은 막대","**LVL(Laminated Veneer Lumber)**"],["알파벳 I 모양 블록","**아이조이스트(I-Joist)**"],["비를 맞아도 되게 약을 바른 막대","**방부목(Preservative-treated Wood)**"]]}],"pass2":[{"kind":"points","head":"표 읽는 법","items":["가로 머리줄은 **구조용 판넬(Structural Panel)**, 글루렘, LVL, I-joist, 방부목 다섯이에요.","세로 이름줄은 바닥, 벽, 천정, 데크, 지붕, 사이딩, 거푸집 일곱이에요.","칸에 O 가 있으면 그 부위에 그 재료를 쓴다는 뜻이에요.","이 쪽에서는 왼쪽 부위 이름과 **구조용 판넬(Structural Panel)** 열이 노랗게 강조돼 있어요."]},{"kind":"compare","head":"분류표를 글자로 옮겼어요 (O 는 사용, - 는 표에 빈칸)","cols":["건축부위","구조용 판넬","글루렘","LVL","I-joist","방부목"],"rows":[["바닥","O","O","O","O","O"],["벽","O","-","O","O","-"],["천정","O","-","O","-","-"],["데크","O","-","-","-","O"],["지붕","O","O","O","O","-"],["사이딩","O","-","-","-","O"],["거푸집","O","-","O","-","-"]]},{"kind":"points","head":"**구조용 판넬(Structural Panel)** 열만 보면","items":["일곱 부위 모두에 O 가 있어요. 표에서 가장 넓게 쓰이는 재료예요.","바닥, 벽, 천정, 데크, 지붕, 사이딩, 거푸집 전부예요.","그래서 이 쪽이 **구조용 판넬(Structural Panel)** 설명(17쪽)으로 이어져요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"분류표에서 일곱 부위 모두에 O 가 있는 재료는?","choices":["**구조용 판넬(Structural Panel)**","**글루램(Glue Laminated Timbers)**","**아이조이스트(I-Joist)**","**방부목(Preservative-treated Wood)**"],"a":0,"why":"구조용 판넬 열만 바닥, 벽, 천정, 데크, 지붕, 사이딩, 거푸집 일곱 칸이 다 O 예요."},{"kind":"check","q":"다섯 재료가 모두 O 인 건축부위는?","choices":["바닥","벽","지붕","거푸집"],"a":0,"why":"바닥 줄만 구조용 판넬, 글루렘, LVL, I-joist, 방부목 다섯이 모두 O 예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["표 머리줄은 '글루렘' 이라고 적혀 있고, 18쪽 본문은 '글루램' 이라고 적혀 있어요. 같은 재료예요.","슬라이드는 '천정' 이라고 적었어요. 흔히 쓰는 말은 천장이지만 표기는 슬라이드를 따라요.","빈칸은 '못 쓴다' 가 아니라 표에 O 가 없다는 뜻이에요. 표 문제는 표대로 답해요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.3174,0.063],"c":[0.0353,0.0701,0.3491,0.095],"r":4.8996,"img":"img/E2/walk/p016_h.jpg"},"parts":[{"b":[0.11,0.225,0.38,0.05],"c":[0.091,0.195,0.418,0.11],"r":5.0667,"img":"img/E2/walk/p016_23_01.jpg","say":"소제목 '목구조에 사용되는 목재의 분류' 예요. 21, 24, 27쪽에 같은 표가 또 나와요."},{"b":[0.11,0.315,0.81,0.072],"c":[0.0695,0.261,0.891,0.18],"r":6.6,"img":"img/E2/walk/p016_23_02.jpg","say":"표 머리줄이에요. 왼쪽부터 구조용 판넬, 글루렘, LVL, I-joist, 방부목이에요."},{"b":[0.11,0.315,0.14,0.54],"c":[0.0645,0.288,0.231,0.594],"r":0.5185,"img":"img/E2/walk/p016_23_03.jpg","say":"노란 타원이 친 왼쪽 열이에요. 바닥, 벽, 천정, 데크, 지붕, 사이딩, 거푸집 일곱 부위예요."},{"b":[0.24,0.315,0.15,0.54],"c":[0.1995,0.288,0.231,0.594],"r":0.5185,"img":"img/E2/walk/p016_23_04.jpg","say":"노란 네모가 친 **구조용 판넬(Structural Panel)** 열이에요. 일곱 칸 모두 O 예요."},{"b":[0.11,0.385,0.81,0.07],"c":[0.0695,0.33,0.891,0.18],"r":6.6,"img":"img/E2/walk/p016_23_05.jpg","say":"바닥 줄이에요. 다섯 재료 모두 O 인 유일한 줄이에요."}]}},{"p":17,"title":"1) **구조용 판넬(Structural Panel)**: **합판(Plywood)** 와 **OSB 판넬(Oriented Strand Board)**","terms":["Structural Panel","Plywood","Oriented Strand Board","I-Joist"],"pass1":[{"kind":"say","lines":["다섯 재료 중 첫 번째, **구조용 판넬(Structural Panel)** 이에요.","얇은 나무를 여러 겹 붙여 만든 넓은 판이에요.","겹쳐 붙이니까 휘지도 처지지도 않고 충격에 강해져요."]}],"pass2":[{"kind":"points","head":"**구조용 판넬(Structural Panel)** 을 그대로 읽어요","items":["종류: **합판(Plywood)**, **OSB 판넬(Oriented Strand Board)**, 집성판넬 등이에요.","강도와 내구성이 우수해요. 휨, 처짐, 부서짐 등이 거의 없고 충격에 강해요.","다양하게 사용돼요: 바닥, 벽, 천정, 거푸집용, 가구, **아이조이스트(I-Joist)** 웹 부분 등이에요."]},{"kind":"compare","head":"**합판(Plywood)** 와 **OSB 판넬(Oriented Strand Board)** 의 차이","cols":["이름","만드는 법 (슬라이드 그대로)"],"rows":[["**합판(Plywood)**","얇은 목재 단판을 각 단판의 결 방향이 서로 교차되도록 적층해요. 그래서 강도가 올라가요."],["**OSB 판넬(Oriented Strand Board)**","접착제를 사용하여 나무조각들로 패널을 만들어내요."]]},{"kind":"points","head":"아래 사진 세 장","items":["왼쪽은 **합판(Plywood)** 예요. 옆면에 얇은 층이 여러 겹 보여요.","가운데는 **OSB 판넬(Oriented Strand Board)** 예요. 나무 조각이 얼룩덜룩 붙어 있어요.","오른쪽은 집성판넬이에요. 긴 나뭇조각을 나란히 이어 붙인 모양이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"'얇은 목재 단판을 각 단판의 결 방향이 서로 교차되도록 적층' 한 것은?","choices":["**합판(Plywood)**","**OSB 판넬(Oriented Strand Board)**","집성판넬","**방부목(Preservative-treated Wood)**"],"a":0,"why":"결을 교차해 쌓는 것이 **합판(Plywood)** 예요. 그래서 강도가 올라가요."},{"kind":"check","q":"**구조용 판넬(Structural Panel)** 의 쓰임으로 슬라이드에 적히지 않은 것은?","choices":["거푸집용","가구","**아이조이스트(I-Joist)** 웹 부분","옥외 조경물"],"a":3,"why":"옥외 조경물은 26쪽 **방부목(Preservative-treated Wood)** 의 쓰임이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**합판(Plywood)** 는 결 교차, **LVL(Laminated Veneer Lumber)** 은 결 평행이에요. 22쪽과 짝지어 외워요.","**OSB 판넬(Oriented Strand Board)** 의 핵심 낱말은 '접착제' 와 '나무조각' 이에요.","본문 쓰임에는 지붕과 사이딩이 없지만 분류표에는 O 가 있어요. 표 문제는 표대로 답해요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.3174,0.063],"c":[0.0353,0.0701,0.3491,0.095],"r":4.8996,"img":"img/E2/walk/p017_h.jpg"},"parts":[{"b":[0.068,0.225,0.18,0.05],"c":[0.056,0.195,0.204,0.11],"r":2.4727,"img":"img/E2/walk/p017_23_01.jpg","say":"제목 줄이에요. 1) 구조용 판넬이에요."},{"b":[0.1,0.285,0.33,0.05],"c":[0.0835,0.255,0.363,0.11],"r":4.4,"img":"img/E2/walk/p017_23_02.jpg","say":"종류 세 가지. 합판, OSB 판넬, 집성판넬 등이에요."},{"b":[0.1,0.345,0.77,0.05],"c":[0.0615,0.2844,0.847,0.1711],"r":6.6004,"img":"img/E2/walk/p017_23_03.jpg","say":"강도와 내구성이 우수. 휨, 처짐, 부서짐이 거의 없고 충격에 강해요."},{"b":[0.1,0.405,0.75,0.05],"c":[0.0625,0.3467,0.825,0.1667],"r":6.5987,"img":"img/E2/walk/p017_23_04.jpg","say":"쓰는 곳. 바닥, 벽, 천정, 거푸집용, 가구, **아이조이스트(I-Joist)** 웹 부분 등이에요."},{"b":[0.1,0.465,0.85,0.05],"c":[0.0575,0.3955,0.935,0.1889],"r":6.5996,"img":"img/E2/walk/p017_23_05.jpg","say":"시험 단골 줄. **합판(Plywood)** 는 결 방향이 서로 교차되도록 적층해요."},{"b":[0.105,0.525,0.7,0.05],"c":[0.07,0.4722,0.77,0.1556],"r":6.5981,"img":"img/E2/walk/p017_23_06.jpg","say":"**OSB 판넬(Oriented Strand Board)** 는 접착제로 나무조각들을 붙여 패널을 만들어요."}]}},{"p":18,"title":"2) **글루램(Glue Laminated Timbers)**","terms":["Glue Laminated Timbers","집성재"],"pass1":[{"kind":"say","lines":["두 번째 재료, **글루램(Glue Laminated Timbers)** 예요.","작은 나무 토막을 이어 붙여 아주 길고 휘어진 보까지 만드는 재료예요.","우리말 이름은 **집성재** 예요. 접착가공목재라는 뜻이에요."]},{"kind":"figure","head":"작은 각재가 큰 보가 되기까지","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240\" y=\"24\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">작은 각재로 긴 보를 만들어요<\/text><rect x=\"30\" y=\"52\" width=\"80\" height=\"18\" rx=\"2\" class=\"n3 b1\"/><rect x=\"118\" y=\"52\" width=\"80\" height=\"18\" rx=\"2\" class=\"n3 b1\"/><rect x=\"206\" y=\"52\" width=\"80\" height=\"18\" rx=\"2\" class=\"n3 b1\"/><text x=\"360\" y=\"66\" font-size=\"14\" text-anchor=\"middle\" class=\"t b1\">두께 5cm 미만 각재<\/text><rect x=\"30\" y=\"100\" width=\"256\" height=\"18\" rx=\"2\" class=\"n2 b2\"/><text x=\"360\" y=\"114\" font-size=\"14\" text-anchor=\"middle\" class=\"t b2\">끝을 이어 긴 판재로<\/text><rect x=\"30\" y=\"146\" width=\"256\" height=\"14\" rx=\"2\" class=\"n2 b3\"/><rect x=\"30\" y=\"162\" width=\"256\" height=\"14\" rx=\"2\" class=\"n2 b3\"/><rect x=\"30\" y=\"178\" width=\"256\" height=\"14\" rx=\"2\" class=\"n2 b3\"/><text x=\"360\" y=\"176\" font-size=\"14\" text-anchor=\"middle\" class=\"t b3\">접착제로 적층, 접착<\/text><path d=\"M30 240 Q158 200 286 240\" class=\"e2 b3\" fill=\"none\"/><text x=\"158\" y=\"262\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b3\">직선과 곡선 모양으로<\/text><\/svg>","caption":"두께 5cm 미만 각재를 끝끼리 이어 긴 판재로 만들고, 접착제로 겹겹이 붙여 직선과 곡선을 만들어요.","builds":3}],"pass2":[{"kind":"points","head":"**글루램(Glue Laminated Timbers)** 를 그대로 읽어요","items":["두께 5cm 미만의 각재를 접착해서 만든 목재예요.","괄호 설명: **집성재** 는 접착가공목재를 말해요.","서로 끝부분 이음을 함으로써 긴 길이의 판재를 만들어요.","그 뒤 접착제로 서로 적층 또는 접착하여 직선, 곡선모양으로 다양하게 생산해요.","우수한 강도 및 내구성이 있어서 구조용으로 적절해요."]},{"kind":"steps","head":"만드는 순서를 네 걸음으로","given":"재료는 두께 5cm 미만의 각재예요.","steps":["첫째, 각재의 끝부분끼리 이음을 해서 길게 만들어요.","둘째, 그렇게 긴 길이의 판재를 얻어요.","셋째, 접착제로 판재를 서로 적층하거나 접착해요.","넷째, 직선 모양이나 곡선 모양으로 다양하게 생산해요."],"answer":"우수한 강도 및 내구성을 가져서 구조용으로 적절해요."},{"kind":"points","head":"아래 사진 두 장","items":["왼쪽은 공장 바닥에 세워 둔 아치 모양 부재예요. 휘어진 모양을 만들 수 있다는 증거예요.","오른쪽은 물결처럼 굽이치는 지붕 구조예요.","둘 다 **글루램(Glue Laminated Timbers)** 로만 가능한 곡선이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**글루램(Glue Laminated Timbers)** 를 만드는 각재의 두께는?","choices":["두께 5cm 미만","두께 5cm 이상","두께 10cm 미만","두께 제한 없음"],"a":0,"why":"슬라이드는 '두께 5cm 미만의 각재를 접착해서 만든 목재' 라고 했어요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"글루램은 두께 5cm 미만의 각재를 접착해서 만든 집성재로, 끝부분 이음으로 긴 판재를 만든 뒤 접착제로 적층하여 직선과 곡선 모양으로 생산하며 강도와 내구성이 우수해 구조용으로 적절하다.","ko":"5cm 미만, **집성재**, 직선과 곡선, 구조용 네 가지가 들어가야 해요.","tip":"'작게 잘라 - 길게 이어 - 겹겹이 붙여 - 휘어서' 로 순서를 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["'5cm 이상' 이 아니라 '5cm 미만' 이에요. 부등호를 바꿔 내기 좋아요.","**집성재** 는 괄호 안 우리말 이름이에요. 접착가공목재라는 뜻이에요.","분류표에서 **글루램(Glue Laminated Timbers)** 는 바닥과 지붕 두 곳만 O 예요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.3174,0.063],"c":[0.0353,0.0701,0.3491,0.095],"r":4.8996,"img":"img/E2/walk/p018_h.jpg"},"parts":[{"b":[0.068,0.225,0.43,0.05],"c":[0.0465,0.195,0.473,0.11],"r":5.7333,"img":"img/E2/walk/p018_23_01.jpg","say":"제목 줄. 2) 글루램 (Glue Laminated Timbers) 이에요. 영어 이름까지 외워요."},{"b":[0.1,0.285,0.78,0.05],"c":[0.061,0.2233,0.858,0.1733],"r":6.6013,"img":"img/E2/walk/p018_23_02.jpg","say":"숫자가 나오는 줄이에요. 두께 5cm 미만의 각재를 접착해서 만들어요."},{"b":[0.1,0.345,0.86,0.115],"c":[0.054,0.3069,0.946,0.1911],"r":6.6004,"img":"img/E2/walk/p018_23_03.jpg","say":"끝부분 이음으로 긴 판재를 만든 뒤 적층 또는 접착해서 직선, 곡선모양을 만들어요."},{"b":[0.068,0.465,0.49,0.05],"c":[0.0435,0.435,0.539,0.11],"r":6.5333,"img":"img/E2/walk/p018_23_04.jpg","say":"우수한 강도 및 내구성이라 구조용으로 적절하다는 줄이에요."},{"b":[0.05,0.55,0.45,0.43],"c":[0.0275,0.527,0.495,0.473],"r":1.3953,"img":"img/E2/walk/p018_23_05.jpg","say":"왼쪽 사진. 공장에 세워 둔 아치 부재예요."},{"b":[0.51,0.55,0.44,0.43],"c":[0.488,0.527,0.484,0.473],"r":1.3643,"img":"img/E2/walk/p018_23_06.jpg","say":"오른쪽 사진. 굽이치는 물결 모양 지붕이에요."}]}},{"p":19,"title":"**글루램(Glue Laminated Timbers)** 공장 사진: 진짜 이렇게 생겼어요","terms":["Glue Laminated Timbers","집성재"],"pass1":[{"kind":"say","lines":["앞 쪽과 같은 제목에 사진만 크게 붙인 쪽이에요.","글로 읽은 **글루램(Glue Laminated Timbers)** 가 실제로 어떻게 생겼는지 보여 줘요.","남는 문장은 하나예요. 두께 5cm 미만의 각재를 접착해서 만든 목재예요."]}],"pass2":[{"kind":"points","head":"사진에서 볼 것","items":["두 사진 모두 공장 안에 쌓아 둔 큰 부재예요.","왼쪽 사진의 노란 동그라미 안을 보면 끝면에 얇은 층이 겹겹이 보여요.","그 층 하나하나가 두께 5cm 미만의 각재예요. 이것이 **집성재** 의 모습이에요.","오른쪽 사진에는 줄자를 대고 길이를 적어 둔 외국어 글자가 있어요. 13,8 미터로 읽혀요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"왼쪽 사진의 노란 동그라미가 보여 주는 것은?","choices":["부재 끝면에 겹겹이 붙은 각재 층","나무의 옹이","접착제 통","톱날 자국"],"a":0,"why":"끝면에 층이 여러 겹 보이는 것이 **글루램(Glue Laminated Timbers)** 가 **집성재** 라는 증거예요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.3174,0.063],"c":[0.0353,0.0701,0.3491,0.095],"r":4.8996,"img":"img/E2/walk/p019_h.jpg"},"parts":[{"b":[0.068,0.225,0.43,0.05],"c":[0.0465,0.195,0.473,0.11],"r":5.7333,"img":"img/E2/walk/p019_21_01.jpg","say":"제목은 18쪽과 같아요. 2) 글루램 (Glue Laminated Timbers) 이에요."},{"b":[0.1,0.285,0.78,0.05],"c":[0.061,0.2233,0.858,0.1733],"r":6.6013,"img":"img/E2/walk/p019_21_02.jpg","say":"남아 있는 글은 이 한 줄뿐이에요. 두께 5cm 미만의 각재를 접착해서 만든 목재."},{"b":[0.01,0.41,0.48,0.56],"c":[0,0.382,0.528,0.616],"r":1.1429,"img":"img/E2/walk/p019_21_03.jpg","say":"왼쪽 사진. 노란 동그라미가 부재 끝면을 가리켜요. 겹겹이 붙인 층이 보여요."},{"b":[0.5,0.41,0.49,0.56],"c":[0.461,0.382,0.539,0.616],"r":1.1667,"img":"img/E2/walk/p019_21_04.jpg","say":"오른쪽 사진. 줄자를 길게 대어 부재의 길이를 재고 있어요."}]}},{"p":20,"title":"**글루램(Glue Laminated Timbers)** 로 지은 실내: 곡선이 되는 나무","terms":["Glue Laminated Timbers"],"pass1":[{"kind":"say","lines":["제목만 있고 사진 한 장이 쪽을 가득 채운 쪽이에요.","**글루램(Glue Laminated Timbers)** 로 지은 실내를 보여 줘요.","이 쪽의 이야기는 하나예요. 나무도 이렇게 휘어질 수 있어요."]}],"pass2":[{"kind":"points","head":"사진에서 볼 것","items":["기둥이 위로 갈수록 부드럽게 휘어져 아치를 이루고 있어요.","이 곡선은 통나무 하나를 깎아서는 만들기 어려워요.","얇은 판재를 겹겹이 붙이면서 휘었기 때문에 가능한 모양이에요.","18쪽에서 읽은 '직선, 곡선모양으로 다양하게 생산' 이 바로 이 모습이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"이 쪽 사진이 보여 주는 **글루램(Glue Laminated Timbers)** 의 장점은?","choices":["직선뿐 아니라 곡선 모양으로도 생산할 수 있다","불에 타지 않는다","약품 처리가 필요 없다","값이 가장 싸다"],"a":0,"why":"18쪽 본문의 '직선, 곡선모양으로 다양하게 생산' 을 사진으로 보여 주는 쪽이에요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.3174,0.063],"c":[0.0353,0.0701,0.3491,0.095],"r":4.8996,"img":"img/E2/walk/p020_h.jpg"},"parts":[{"b":[0.07,0.215,0.43,0.06],"c":[0.0485,0.19,0.473,0.11],"r":5.7333,"img":"img/E2/walk/p020_21_01.jpg","say":"제목만 남아 있어요. 2) 글루램 (Glue Laminated Timbers) 이에요."},{"b":[0.07,0.32,0.86,0.66],"c":[0.027,0.274,0.946,0.726],"r":1.7374,"img":"img/E2/walk/p020_21_02.jpg","say":"사진 한 장이에요. 휘어진 기둥과 아치, 그리고 그 위를 덮은 나무 천정이 보여요."}]}},{"p":21,"title":"분류표 다시 보기: **글루램(Glue Laminated Timbers)** 열","terms":["Glue Laminated Timbers","Structural Panel"],"pass1":[{"kind":"say","lines":["16쪽과 똑같은 표가 다시 나왔어요. 강조된 자리만 달라졌어요.","이번에는 글루렘 열에 노란 네모가 쳐져 있어요.","방금 배운 **글루램(Glue Laminated Timbers)** 가 어디에 쓰이는지 확인하는 쪽이에요."]}],"pass2":[{"kind":"points","head":"글루렘 열만 읽어요","items":["바닥에 O 가 있어요.","지붕에 O 가 있어요.","벽, 천정, 데크, 사이딩, 거푸집은 빈칸이에요.","곧 **글루램(Glue Laminated Timbers)** 는 표에서 O 가 가장 적은 재료예요. 두 곳뿐이에요."]},{"kind":"compare","head":"O 개수로 견주어 봐요","cols":["재료","O 가 있는 부위","개수"],"rows":[["**구조용 판넬(Structural Panel)**","바닥, 벽, 천정, 데크, 지붕, 사이딩, 거푸집","7"],["글루렘","바닥, 지붕","2"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"분류표에서 **글루램(Glue Laminated Timbers)** 에 O 가 있는 부위는?","choices":["바닥, 지붕","바닥, 벽","데크, 사이딩","천정, 거푸집"],"a":0,"why":"글루렘 열은 바닥과 지붕 두 칸만 O 예요. 표에서 가장 적어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["표의 이름은 '글루렘', 본문의 이름은 '글루램' 이에요. 같은 **글루램(Glue Laminated Timbers)** 예요.","O 가 적다고 덜 중요한 재료가 아니에요. 구조용 큰 부재에 쓰는 재료예요.","표에서 O 가 가장 많은 것은 **구조용 판넬(Structural Panel)** 의 일곱 곳이에요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.3174,0.063],"c":[0.0353,0.0701,0.3491,0.095],"r":4.8996,"img":"img/E2/walk/p021_h.jpg"},"parts":[{"b":[0.11,0.225,0.38,0.05],"c":[0.091,0.195,0.418,0.11],"r":5.0667,"img":"img/E2/walk/p021_22_01.jpg","say":"소제목은 16쪽과 같아요. 목구조에 사용되는 목재의 분류예요."},{"b":[0.38,0.315,0.14,0.072],"c":[0.35,0.296,0.2,0.11],"r":2.4242,"img":"img/E2/walk/p021_22_02.jpg","say":"노란 네모가 글루렘 머리칸으로 옮겨 왔어요."},{"b":[0.38,0.385,0.14,0.47],"c":[0.3495,0.3615,0.2011,0.517],"r":0.5186,"img":"img/E2/walk/p021_22_03.jpg","say":"글루렘 열이에요. 맨 위 바닥과 다섯째 줄 지붕에만 O 가 있어요."},{"b":[0.11,0.385,0.81,0.07],"c":[0.0695,0.33,0.891,0.18],"r":6.6,"img":"img/E2/walk/p021_22_04.jpg","say":"바닥 줄. 글루렘도 여기에 O 가 있어요."},{"b":[0.11,0.652,0.81,0.07],"c":[0.0695,0.597,0.891,0.18],"r":6.6,"img":"img/E2/walk/p021_22_05.jpg","say":"지붕 줄. 글루렘의 두 번째 O 가 여기예요."}]}},{"p":22,"title":"3) **LVL(Laminated Veneer Lumber)**: 결을 나란히 쌓아요","terms":["Laminated Veneer Lumber","Plywood","I-Joist"],"pass1":[{"kind":"say","lines":["세 번째 재료, **LVL(Laminated Veneer Lumber)** 이에요.","얇은 나무 한 장을 단판이라고 해요. 그 단판을 결이 나란하게 쌓은 재료예요.","한 줄 비교로 외워요. **합판(Plywood)** 는 엇갈려 쌓고, LVL 은 나란히 쌓아요."]},{"kind":"figure","head":"결 방향이 갈라요","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"120\" y=\"26\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">합판: 결을 교차해서<\/text><text x=\"360\" y=\"26\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">LVL: 결을 나란하게<\/text><rect x=\"30\" y=\"50\" width=\"180\" height=\"30\" rx=\"2\" class=\"n3 b1\"/><line x1=\"40\" y1=\"60\" x2=\"200\" y2=\"60\" class=\"e b1\"/><line x1=\"40\" y1=\"70\" x2=\"200\" y2=\"70\" class=\"e b1\"/><rect x=\"30\" y=\"90\" width=\"180\" height=\"30\" rx=\"2\" class=\"n3 b1\"/><line x1=\"60\" y1=\"94\" x2=\"60\" y2=\"116\" class=\"e b1\"/><line x1=\"100\" y1=\"94\" x2=\"100\" y2=\"116\" class=\"e b1\"/><line x1=\"140\" y1=\"94\" x2=\"140\" y2=\"116\" class=\"e b1\"/><line x1=\"180\" y1=\"94\" x2=\"180\" y2=\"116\" class=\"e b1\"/><rect x=\"30\" y=\"130\" width=\"180\" height=\"30\" rx=\"2\" class=\"n3 b1\"/><line x1=\"40\" y1=\"140\" x2=\"200\" y2=\"140\" class=\"e b1\"/><line x1=\"40\" y1=\"150\" x2=\"200\" y2=\"150\" class=\"e b1\"/><rect x=\"270\" y=\"50\" width=\"180\" height=\"30\" rx=\"2\" class=\"n3 b2\"/><line x1=\"280\" y1=\"60\" x2=\"440\" y2=\"60\" class=\"e b2\"/><line x1=\"280\" y1=\"70\" x2=\"440\" y2=\"70\" class=\"e b2\"/><rect x=\"270\" y=\"90\" width=\"180\" height=\"30\" rx=\"2\" class=\"n3 b2\"/><line x1=\"280\" y1=\"100\" x2=\"440\" y2=\"100\" class=\"e b2\"/><line x1=\"280\" y1=\"110\" x2=\"440\" y2=\"110\" class=\"e b2\"/><rect x=\"270\" y=\"130\" width=\"180\" height=\"30\" rx=\"2\" class=\"n3 b2\"/><line x1=\"280\" y1=\"140\" x2=\"440\" y2=\"140\" class=\"e b2\"/><line x1=\"280\" y1=\"150\" x2=\"440\" y2=\"150\" class=\"e b2\"/><text x=\"120\" y=\"196\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">강도를 높여요<\/text><text x=\"360\" y=\"196\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">보, 서까래, 플랜지<\/text><line x1=\"270\" y1=\"226\" x2=\"441\" y2=\"226\" class=\"e2 b2\"/><polygon points=\"450,226 441,231 441,221\" class=\"arrow b2\"/><text x=\"360\" y=\"220\" font-size=\"13\" text-anchor=\"middle\" class=\"tm b2\">길이 방향<\/text><\/svg>","caption":"**합판(Plywood)** 는 층마다 결이 엇갈리고, **LVL(Laminated Veneer Lumber)** 은 모든 층의 결이 길이 방향으로 나란해요.","builds":2}],"pass2":[{"kind":"points","head":"**LVL(Laminated Veneer Lumber)** 을 그대로 읽어요","items":["얇은 목재 단판을 나뭇결이 길이 방향에 평행하도록 적층해요.","그렇게 만든 큰 장작 형태를 최종 사용될 제품의 크기로 잘라 만든 것이에요.","보, 서까래, **아이조이스트(I-Joist)** 플랜지 부분 등에 사용해요."]},{"kind":"points","head":"아래 그림 읽는 법","items":["왼쪽 더미에 Veneer 라고 적혀 있어요. 얇은 단판을 쌓아 놓은 모습이에요.","가운데 덩어리에 LVL 이라고 적혀 있어요. 단판을 붙여 만든 큰 덩어리예요.","오른쪽 위 조각에는 Vertical (Longitudinal) 이라고 적혀 있어요.","오른쪽 아래 조각에는 Horizontal direction (Horizontal) 이라고 적혀 있어요.","곧 큰 덩어리를 세로나 가로 방향으로 잘라서 제품을 만든다는 그림이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"'얇은 목재 단판을 나뭇결이 길이 방향에 평행하도록 적층' 한 목재는?","choices":["**합판(Plywood)**","OSB 판넬","**LVL(Laminated Veneer Lumber)**","방부목"],"a":2,"why":"**LVL(Laminated Veneer Lumber)** 은 결을 나란하게, **합판(Plywood)** 는 결을 교차해서 쌓아요."},{"kind":"check","q":"**LVL(Laminated Veneer Lumber)** 을 쓰는 곳으로 슬라이드에 적힌 것은?","choices":["보, 서까래, **아이조이스트(I-Joist)** 플랜지","담장과 발코니","거푸집과 가구만","지붕 기와"],"a":0,"why":"슬라이드는 '보, 서까래, I-Joist 플랜지 부분 등에 사용' 이라고 했어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["결 방향을 바꿔 내기 딱 좋아요. 교차는 **합판(Plywood)**, 평행은 **LVL(Laminated Veneer Lumber)** 이에요.","'큰 장작 형태' 는 만드는 중간 모습이에요. 그것을 제품 크기로 잘라서 써요.","**아이조이스트(I-Joist)** 에서 LVL 이 쓰이는 자리는 플랜지예요. 웹이 아니에요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.3174,0.063],"c":[0.0353,0.0701,0.3491,0.095],"r":4.8996,"img":"img/E2/walk/p022_h.jpg"},"parts":[{"b":[0.068,0.228,0.42,0.05],"c":[0.047,0.198,0.462,0.11],"r":5.6,"img":"img/E2/walk/p022_22_01.jpg","say":"제목 줄. 3) LVL (Laminated Veneer Lumber) 이에요."},{"b":[0.1,0.285,0.84,0.115],"c":[0.058,0.2492,0.924,0.1867],"r":6.5988,"img":"img/E2/walk/p022_22_02.jpg","say":"시험 단골 줄. 나뭇결이 길이 방향에 평행하도록 적층하여 만든 큰 장작 형태예요."},{"b":[0.105,0.405,0.46,0.05],"c":[0.082,0.375,0.506,0.11],"r":6.1333,"img":"img/E2/walk/p022_22_03.jpg","say":"쓰는 곳. 보, 서까래, **아이조이스트(I-Joist)** 플랜지 부분 등이에요."},{"b":[0.17,0.55,0.28,0.35],"c":[0.156,0.5325,0.308,0.385],"r":1.0667,"img":"img/E2/walk/p022_22_04.jpg","say":"Veneer, 곧 얇은 단판 더미예요. 여기서 출발해요."},{"b":[0.42,0.63,0.25,0.28],"c":[0.4075,0.614,0.275,0.312],"r":1.1752,"img":"img/E2/walk/p022_22_05.jpg","say":"가운데 LVL 덩어리예요. 단판이 나란히 붙어 있어요."},{"b":[0.66,0.52,0.3,0.45],"c":[0.645,0.4975,0.33,0.495],"r":0.8889,"img":"img/E2/walk/p022_22_06.jpg","say":"오른쪽 두 조각. 세로(Vertical)와 가로(Horizontal) 방향으로 잘라 쓴다는 뜻이에요."}]}},{"p":23,"title":"**LVL(Laminated Veneer Lumber)** 실물 사진","terms":["Laminated Veneer Lumber","I-Joist"],"pass1":[{"kind":"say","lines":["앞 쪽과 글은 같고 그림만 실물 사진으로 바뀐 쪽이에요.","**LVL(Laminated Veneer Lumber)** 이 실제로 어떤 모습인지 보여 줘요.","왼쪽은 잘라 놓은 제품, 오른쪽은 집에 설치된 모습이에요."]}],"pass2":[{"kind":"points","head":"사진에서 볼 것","items":["왼쪽 사진은 두께와 폭이 다른 여러 제품을 계단처럼 세워 놓은 모습이에요.","옆면을 보면 얇은 층이 나란히 붙어 있어요. 결이 평행하다는 뜻이에요.","오른쪽 사진은 바닥 구조에 보가 걸린 모습이에요. 금속 철물로 이어 놓았어요.","옆에 세로로 서 있는 부재들이 **아이조이스트(I-Joist)** 예요. 25쪽에서 다시 만나요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"왼쪽 사진에서 **LVL(Laminated Veneer Lumber)** 의 옆면이 보여 주는 것은?","choices":["얇은 층이 나란히 붙어 있는 모습","나무 조각이 얼룩덜룩한 모습","약품을 바른 초록색 겉면","속이 빈 관 모양"],"a":0,"why":"결이 길이 방향에 평행하도록 단판을 쌓았기 때문에 옆면에 층이 나란히 보여요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.3174,0.063],"c":[0.0353,0.0701,0.3491,0.095],"r":4.8996,"img":"img/E2/walk/p023_h.jpg"},"parts":[{"b":[0.068,0.228,0.42,0.05],"c":[0.047,0.198,0.462,0.11],"r":5.6,"img":"img/E2/walk/p023_21_01.jpg","say":"제목은 22쪽과 같아요. 3) LVL (Laminated Veneer Lumber) 이에요."},{"b":[0.1,0.285,0.84,0.115],"c":[0.058,0.2492,0.924,0.1867],"r":6.5988,"img":"img/E2/walk/p023_21_02.jpg","say":"글도 22쪽과 같아요. 나뭇결이 길이 방향에 평행하도록 적층한 큰 장작 형태예요."},{"b":[0.01,0.5,0.42,0.44],"c":[0,0.478,0.462,0.484],"r":1.2727,"img":"img/E2/walk/p023_21_03.jpg","say":"왼쪽 사진. 크기가 다른 제품들을 세워 놓았어요. 옆면에 얇은 층이 보여요."},{"b":[0.43,0.5,0.55,0.44],"c":[0.395,0.478,0.605,0.484],"r":1.6667,"img":"img/E2/walk/p023_21_04.jpg","say":"오른쪽 사진. 바닥 구조에 보가 걸려 있고 금속 철물로 고정돼 있어요."}]}},{"p":24,"title":"분류표 다시 보기: **LVL(Laminated Veneer Lumber)** 열","terms":["Laminated Veneer Lumber","Glue Laminated Timbers"],"pass1":[{"kind":"say","lines":["같은 분류표가 세 번째로 나왔어요. 이번에는 LVL 열이 노랗게 강조돼 있어요.","방금 배운 **LVL(Laminated Veneer Lumber)** 이 어디에 쓰이는지 확인하는 쪽이에요."]}],"pass2":[{"kind":"points","head":"LVL 열만 읽어요","items":["바닥, 벽, 천정에 O 가 있어요.","지붕에도 O 가 있어요.","거푸집에도 O 가 있어요.","빈칸은 데크와 사이딩 두 곳이에요. 바깥에 드러나는 부위가 빠졌어요."]},{"kind":"compare","head":"LVL 과 **글루램(Glue Laminated Timbers)** 를 견주어 봐요","cols":["재료","O 가 있는 부위","개수"],"rows":[["**LVL(Laminated Veneer Lumber)**","바닥, 벽, 천정, 지붕, 거푸집","5"],["**글루램(Glue Laminated Timbers)**","바닥, 지붕","2"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"분류표에서 천정과 거푸집에 O 가 있는 재료 두 가지는?","choices":["구조용 판넬과 LVL","글루렘과 방부목","I-joist 와 방부목","LVL 과 글루렘"],"a":0,"why":"천정 줄과 거푸집 줄은 **구조용 판넬(Structural Panel)** 과 **LVL(Laminated Veneer Lumber)** 두 칸에만 O 가 있어요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.3174,0.063],"c":[0.0353,0.0701,0.3491,0.095],"r":4.8996,"img":"img/E2/walk/p024_h.jpg"},"parts":[{"b":[0.11,0.225,0.38,0.05],"c":[0.091,0.195,0.418,0.11],"r":5.0667,"img":"img/E2/walk/p024_22_01.jpg","say":"소제목은 그대로예요. 목구조에 사용되는 목재의 분류."},{"b":[0.515,0.315,0.14,0.072],"c":[0.485,0.296,0.2,0.11],"r":2.4242,"img":"img/E2/walk/p024_22_02.jpg","say":"노란 네모가 LVL 머리칸으로 옮겨 왔어요."},{"b":[0.515,0.385,0.14,0.47],"c":[0.4845,0.3615,0.2011,0.517],"r":0.5186,"img":"img/E2/walk/p024_22_03.jpg","say":"LVL 열이에요. 바닥, 벽, 천정, 지붕, 거푸집 다섯 칸에 O 가 있어요."},{"b":[0.11,0.518,0.81,0.07],"c":[0.0695,0.463,0.891,0.18],"r":6.6,"img":"img/E2/walk/p024_22_04.jpg","say":"천정 줄이에요. 구조용 판넬과 LVL 둘만 O 예요."},{"b":[0.11,0.785,0.81,0.07],"c":[0.0695,0.73,0.891,0.18],"r":6.6,"img":"img/E2/walk/p024_22_05.jpg","say":"거푸집 줄이에요. 여기도 구조용 판넬과 LVL 둘만 O 예요."}]}},{"p":25,"title":"4) **아이조이스트(I-Joist)**: 알파벳 I 를 닮은 보","terms":["I-Joist","Plywood","Oriented Strand Board","Laminated Veneer Lumber"],"pass1":[{"kind":"say","lines":["네 번째 재료, **아이조이스트(I-Joist)** 예요. 이름 그대로 단면이 알파벳 I 를 닮았어요.","앞에서 배운 재료 두 가지를 합쳐 만든 보예요.","가운데 세로판은 판재, 위아래 가로판은 LVL 이에요."]},{"kind":"figure","head":"**아이조이스트(I-Joist)** 는 두 재료의 합작","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240\" y=\"24\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">I-Joist 단면<\/text><rect x=\"150\" y=\"44\" width=\"180\" height=\"34\" rx=\"2\" class=\"n2 b1\"/><rect x=\"150\" y=\"204\" width=\"180\" height=\"34\" rx=\"2\" class=\"n2 b1\"/><text x=\"418\" y=\"64\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">플랜지: LVL<\/text><rect x=\"226\" y=\"78\" width=\"28\" height=\"126\" rx=\"2\" class=\"n3 b2\"/><text x=\"400\" y=\"146\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">웹: 합판, OSB<\/text><line x1=\"348\" y1=\"140\" x2=\"267\" y2=\"140\" class=\"e2 b2\"/><polygon points=\"258,140 267,135 267,145\" class=\"arrow b2\"/><text x=\"82\" y=\"136\" font-size=\"15\" text-anchor=\"middle\" class=\"t b3\">가볍고 길게<\/text><text x=\"82\" y=\"160\" font-size=\"15\" text-anchor=\"middle\" class=\"t b3\">바닥, 지붕 구조용<\/text><\/svg>","caption":"위아래 플랜지는 **LVL(Laminated Veneer Lumber)**, 가운데 웹은 **합판(Plywood)** 나 **OSB 판넬(Oriented Strand Board)** 예요.","builds":3}],"pass2":[{"kind":"points","head":"**아이조이스트(I-Joist)** 를 그대로 읽어요","items":["웹: **합판(Plywood)** 나 **OSB 판넬(Oriented Strand Board)** 예요.","플랜지: **LVL(Laminated Veneer Lumber)** 을 사용하여 만들어지는 재료예요.","시공 간단, 경량, 긴 길이의 제품 생산 가능이에요.","바닥 또는 지붕구조용 자재로 사용해요."]},{"kind":"compare","head":"웹과 플랜지 자리 외우기","cols":["자리","어디에 있나","무슨 재료인가"],"rows":[["웹(Web)","가운데 세로판","**합판(Plywood)** 나 **OSB 판넬(Oriented Strand Board)**"],["플랜지(Flanges)","위아래 가로판","**LVL(Laminated Veneer Lumber)**"]]},{"kind":"points","head":"아래 사진과 오른쪽 그림","items":["왼쪽 사진은 지붕 아래에 나란히 걸린 부재들이에요. 가운데가 얼룩덜룩한 판으로 보여요.","오른쪽 그림에는 Flanges 와 Web 이라는 글자와 화살표가 있어요.","화살표가 위아래 가로판을 Flanges, 가운데 세로판을 Web 으로 가리켜요.","가운데를 얇게 비워서 무게를 줄인 것이 **아이조이스트(I-Joist)** 의 요령이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**아이조이스트(I-Joist)** 의 플랜지에 쓰는 재료는?","choices":["**LVL(Laminated Veneer Lumber)**","**합판(Plywood)**","**OSB 판넬(Oriented Strand Board)**","방부목"],"a":0,"why":"웹은 **합판(Plywood)** 나 **OSB 판넬(Oriented Strand Board)**, 플랜지는 **LVL(Laminated Veneer Lumber)** 이에요."},{"kind":"check","q":"슬라이드가 든 **아이조이스트(I-Joist)** 의 장점이 아닌 것은?","choices":["시공 간단","경량","긴 길이의 제품 생산 가능","불연성"],"a":3,"why":"장점은 시공 간단, 경량, 긴 길이의 제품 생산 가능 세 가지예요. 불에 관한 말은 없어요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"I-Joist 는 웹에 합판이나 OSB 판넬을, 플랜지에 LVL 을 사용하여 만드는 재료로, 시공이 간단하고 가벼우며 긴 길이의 제품 생산이 가능해 바닥 또는 지붕구조용 자재로 사용한다.","ko":"웹과 플랜지의 재료를 바꿔 쓰지 않는 것이 점수의 갈림길이에요.","tip":"'가운데는 판, 위아래는 LVL' 로 위치와 재료를 묶어서 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["웹과 플랜지를 바꿔 쓰면 틀려요. 웹은 판재, 플랜지는 **LVL(Laminated Veneer Lumber)** 이에요.","본문은 '바닥 또는 지붕구조용' 이라고 했지만 분류표에는 벽에도 O 가 있어요.","슬라이드 표기는 'I-Joist (아이조이스트)' 이고, 분류표 머리칸은 'I-joist' 예요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.3174,0.063],"c":[0.0353,0.0701,0.3491,0.095],"r":4.8996,"img":"img/E2/walk/p025_h.jpg"},"parts":[{"b":[0.065,0.225,0.29,0.05],"c":[0.0505,0.195,0.319,0.11],"r":3.8667,"img":"img/E2/walk/p025_23_01.jpg","say":"제목 줄. 4) I-Joist (아이조이스트) 예요."},{"b":[0.1,0.285,0.27,0.05],"c":[0.0865,0.255,0.297,0.11],"r":3.6,"img":"img/E2/walk/p025_23_02.jpg","say":"웹 : 합판이나 OSB 판넬. 가운데 세로판 이야기예요."},{"b":[0.1,0.345,0.44,0.05],"c":[0.078,0.315,0.484,0.11],"r":5.8667,"img":"img/E2/walk/p025_23_03.jpg","say":"플랜지 : LVL 사용하여 만들어지는 재료. 위아래 가로판 이야기예요."},{"b":[0.1,0.405,0.48,0.05],"c":[0.076,0.375,0.528,0.11],"r":6.4,"img":"img/E2/walk/p025_23_04.jpg","say":"장점 세 가지. 시공 간단, 경량, 긴 길이의 제품 생산 가능."},{"b":[0.1,0.465,0.39,0.05],"c":[0.0805,0.435,0.429,0.11],"r":5.2,"img":"img/E2/walk/p025_23_05.jpg","say":"쓰는 곳. 바닥 또는 지붕구조용 자재로 사용해요."},{"b":[0.6,0.44,0.38,0.52],"c":[0.581,0.414,0.418,0.572],"r":0.9744,"img":"img/E2/walk/p025_23_06.jpg","say":"오른쪽 그림이에요. Flanges 와 Web 이 화살표로 표시돼 있어요."}]}},{"p":26,"title":"5) **방부목(Preservative-treated Wood)**","terms":["Preservative-treated Wood","Wood","Preservative"],"pass1":[{"kind":"say","lines":["다섯 번째이자 마지막 재료, **방부목(Preservative-treated Wood)** 이에요.","비를 맞는 곳에 쓰려고 약품을 처리한 나무예요.","15쪽에서 본 **목재(Wood)** 의 단점 '부패되기 쉬움' 을 메우려는 재료예요."]}],"pass2":[{"kind":"points","head":"**방부목(Preservative-treated Wood)** 을 그대로 읽어요","items":["습기에 의한 부패를 막기 위해 인공적으로 약품을 처리한 목재예요.","발코니, 담장, 옥외 조경물 등에 사용해요.","쓰는 곳이 모두 바깥이라는 점을 기억해요."]},{"kind":"points","head":"아래 사진 두 장","items":["왼쪽은 데크 바닥을 가까이 찍은 사진이에요. 나뭇결이 그대로 보여요.","오른쪽은 관광안내소 건물과 그 앞 데크예요. 바닥과 벽 마감에 나무를 썼어요.","둘 다 비와 습기를 맞는 자리예요. 그래서 **방부목(Preservative-treated Wood)** 을 써요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**방부목(Preservative-treated Wood)** 을 쓰는 곳으로 슬라이드에 적힌 것은?","choices":["발코니, 담장, 옥외 조경물","거푸집과 가구","천정과 벽","지붕 기와"],"a":0,"why":"슬라이드는 '발코니, 담장, 옥외 조경물 등에 사용' 이라고 했어요. 모두 바깥 자리예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**방부목(Preservative-treated Wood)** 은 '인공적으로 약품을 처리한' 목재예요. 천연 그대로가 아니에요.","15쪽 8) 에서는 유독성 **방부제(Preservative)** 를 쓰면 안 된다고 했어요. 두 이야기를 함께 기억해요.","분류표에서 **방부목(Preservative-treated Wood)** 은 바닥, 데크, 사이딩 세 곳에 O 가 있어요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.3174,0.063],"c":[0.0353,0.0701,0.3491,0.095],"r":4.8996,"img":"img/E2/walk/p026_h.jpg"},"parts":[{"b":[0.068,0.225,0.12,0.05],"c":[0.028,0.195,0.2,0.11],"r":2.4242,"img":"img/E2/walk/p026_22_01.jpg","say":"제목 줄. 5) 방부목이에요. 다섯 재료 중 유일하게 영어 이름이 없어요."},{"b":[0.1,0.285,0.7,0.05],"c":[0.065,0.2322,0.77,0.1556],"r":6.5981,"img":"img/E2/walk/p026_22_02.jpg","say":"정의 줄. 습기에 의한 부패를 막기 위해 인공적으로 약품을 처리한 목재예요."},{"b":[0.1,0.345,0.41,0.05],"c":[0.0795,0.315,0.451,0.11],"r":5.4667,"img":"img/E2/walk/p026_22_03.jpg","say":"쓰는 곳. 발코니, 담장, 옥외 조경물 등이에요."},{"b":[0.02,0.48,0.5,0.47],"c":[0,0.4565,0.55,0.517],"r":1.4184,"img":"img/E2/walk/p026_22_04.jpg","say":"왼쪽 사진. 바깥 데크 바닥을 가까이 찍었어요."},{"b":[0.54,0.48,0.44,0.47],"c":[0.516,0.4565,0.484,0.517],"r":1.2482,"img":"img/E2/walk/p026_22_05.jpg","say":"오른쪽 사진. 길가 안내소 건물과 그 앞 나무 데크예요."}]}},{"p":27,"title":"분류표 마무리: **아이조이스트(I-Joist)** 와 **방부목(Preservative-treated Wood)** 열","terms":["I-Joist","Preservative-treated Wood","Structural Panel","Glue Laminated Timbers","Laminated Veneer Lumber"],"pass1":[{"kind":"say","lines":["같은 분류표의 마지막 등장이에요. 이번에는 오른쪽 두 열이 함께 강조돼 있어요.","다섯 재료를 다 배웠으니 표 전체를 한 번에 읽을 수 있어요."]},{"kind":"recap","items":["**구조용 판넬(Structural Panel)**: 합판, OSB 판넬, 집성판넬. 일곱 부위 모두.","**글루램(Glue Laminated Timbers)**: 5cm 미만 각재를 접착. 바닥, 지붕.","**LVL(Laminated Veneer Lumber)**: 결을 길이 방향에 평행하게 적층. 바닥, 벽, 천정, 지붕, 거푸집.","**아이조이스트(I-Joist)**: 웹은 판재, 플랜지는 LVL. 바닥, 벽, 지붕.","**방부목(Preservative-treated Wood)**: 약품 처리한 목재. 바닥, 데크, 사이딩."]}],"pass2":[{"kind":"points","head":"오른쪽 두 열을 읽어요","items":["**아이조이스트(I-Joist)** 열: 바닥, 벽, 지붕 세 칸에 O 가 있어요.","**방부목(Preservative-treated Wood)** 열: 바닥, 데크, 사이딩 세 칸에 O 가 있어요.","둘 다 세 칸씩이지만 자리가 달라요. I-joist 는 안쪽 구조, 방부목은 바깥쪽이에요.","데크와 사이딩에 O 가 있는 재료는 구조용 판넬과 방부목 둘뿐이에요."]},{"kind":"compare","head":"다섯 재료의 분류표 전체 (O 는 사용, - 는 표에 빈칸)","cols":["건축부위","구조용 판넬","글루렘","LVL","I-joist","방부목"],"rows":[["바닥","O","O","O","O","O"],["벽","O","-","O","O","-"],["천정","O","-","O","-","-"],["데크","O","-","-","-","O"],["지붕","O","O","O","O","-"],["사이딩","O","-","-","-","O"],["거푸집","O","-","O","-","-"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"데크와 사이딩에 O 가 있는 재료 두 가지는?","choices":["구조용 판넬과 방부목","LVL 과 I-joist","글루렘과 LVL","I-joist 와 방부목"],"a":0,"why":"바깥에 드러나는 데크와 사이딩에는 **구조용 판넬(Structural Panel)** 과 **방부목(Preservative-treated Wood)** 만 O 가 있어요."},{"kind":"check","q":"분류표에서 **아이조이스트(I-Joist)** 에 O 가 있는 부위는?","choices":["바닥, 벽, 지붕","바닥, 데크, 사이딩","바닥, 지붕","천정, 거푸집"],"a":0,"why":"I-joist 열은 바닥, 벽, 지붕 세 칸이에요. 바닥, 데크, 사이딩은 방부목이에요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"목구조에 사용되는 목재는 구조용 판넬, 글루램, LVL, I-Joist, 방부목 다섯 가지이며, 구조용 판넬은 일곱 부위 모두에, 방부목은 바닥과 데크, 사이딩에 사용된다.","ko":"다섯 이름을 순서대로 쓰고, 가장 넓게 쓰이는 것과 바깥에 쓰이는 것을 덧붙이면 좋아요.","tip":"'판넬 - 글루램 - LVL - I - 방부' 다섯 마디로 순서를 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**아이조이스트(I-Joist)** 와 **방부목(Preservative-treated Wood)** 은 둘 다 O 가 세 개지만 자리가 완전히 달라요.","표에서 벽에 O 가 있는 재료는 구조용 판넬, LVL, I-joist 세 가지예요.","본문 설명과 표가 어긋나는 곳이 있어요. 표를 묻는 문제는 표대로 답해요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.3174,0.063],"c":[0.0353,0.0701,0.3491,0.095],"r":4.8996,"img":"img/E2/walk/p027_h.jpg"},"parts":[{"b":[0.11,0.225,0.38,0.05],"c":[0.091,0.195,0.418,0.11],"r":5.0667,"img":"img/E2/walk/p027_22_01.jpg","say":"소제목은 그대로예요. 목구조에 사용되는 목재의 분류."},{"b":[0.648,0.315,0.272,0.072],"c":[0.6344,0.296,0.2992,0.11],"r":3.6267,"img":"img/E2/walk/p027_22_02.jpg","say":"노란 네모가 오른쪽 두 머리칸을 함께 감쌌어요. I-joist 와 방부목이에요."},{"b":[0.648,0.385,0.14,0.47],"c":[0.6175,0.3615,0.2011,0.517],"r":0.5186,"img":"img/E2/walk/p027_22_03.jpg","say":"**아이조이스트(I-Joist)** 열이에요. 바닥, 벽, 지붕 세 칸에 O 가 있어요."},{"b":[0.787,0.385,0.133,0.47],"c":[0.753,0.3615,0.2011,0.517],"r":0.5186,"img":"img/E2/walk/p027_22_04.jpg","say":"**방부목(Preservative-treated Wood)** 열이에요. 바닥, 데크, 사이딩 세 칸에 O 가 있어요."},{"b":[0.11,0.585,0.81,0.07],"c":[0.0695,0.53,0.891,0.18],"r":6.6,"img":"img/E2/walk/p027_22_05.jpg","say":"데크 줄이에요. 구조용 판넬과 방부목 둘만 O 예요."},{"b":[0.11,0.718,0.81,0.07],"c":[0.0695,0.663,0.891,0.18],"r":6.6,"img":"img/E2/walk/p027_22_06.jpg","say":"사이딩 줄이에요. 여기도 구조용 판넬과 방부목 둘만 O 예요."}]}},{"p":28,"title":"흙의 특성 5가지와 단점 2가지","terms":["Earth Architecture","Humidity Control","Heat Storage","Wood","Breathability"],"pass1":[{"kind":"say","lines":["천연 건축재료의 두 번째, 흙으로 넘어가요.","이 쪽의 이야기는 하나예요. 흙은 숨 쉬고 열을 머금는 재료예요.","대신 약점도 분명해요. 물이에요."]},{"kind":"analogy","head":"흙벽은 뚝배기예요","scene":"뚝배기는 늦게 데워지고 늦게 식어요. 흙벽도 낮의 열을 머금었다가 천천히 내놓아요. 습기도 먹었다 내놓아요.","map":[["늦게 데워지고 늦게 식는 뚝배기","**축열(Heat Storage)**"],["물기를 먹었다 내놓는 스펀지","**습도 조절(Humidity Control)**"],["흙 알갱이 사이의 틈","공극, 그래서 공기 정화"],["비를 맞으면 풀어지는 흙덩이","수분에 취약함"]]}],"pass2":[{"kind":"points","head":"흙의 특성 1~3 (슬라이드 번호 그대로)","items":["1) 천연의 습도 조절기능: 실내의 습도를 쾌적하게 유지해요. 이것이 **습도 조절(Humidity Control)** 이에요.","2) 단열과 축열기능: 여름에는 최고기온이 실외보다 3~10도 정도 낮아요.","2) 이어서: 겨울에는 최저기온이 실외보다 5~7도 정도 높은 온도를 유지해요.","3) 공기 정화 기능: 흙의 미립자에 공극이 많아 공기교환이 용이하고 오염물질 제거 효과가 있어요."]},{"kind":"points","head":"흙의 특성 4~5","items":["4) 항균과 방충 효과: 토양 미생물과 효소작용에 의해요.","5) 폐기물 발생 없음: 건축물 폐기 시 자연으로 환원돼요.","5) 가 1강에서 배운 재료 순환 그 자체예요. **흙건축(Earth Architecture)** 은 다 쓰면 흙으로 돌아가요.","주문도 그대로예요. 자연에서 빌려 쓰고, 돌려주며 순환시켜요."]},{"kind":"steps","head":"**축열(Heat Storage)** 숫자를 손으로 써 봐요","given":"예시 날씨로 여름 바깥 최고 33도, 겨울 바깥 최저 영하 5도를 가정해요. (연습용 가정이에요)","steps":["여름은 3~10도 낮으니 33 빼기 10 은 23, 33 빼기 3 은 30 이에요.","그래서 흙집 안 최고기온은 약 23도에서 30도 사이예요.","겨울은 5~7도 높으니 영하 5 더하기 5 는 0, 영하 5 더하기 7 은 2 예요.","그래서 흙집 안 최저기온은 약 0도에서 2도 사이예요."],"answer":"여름은 3~10도 낮게, 겨울은 5~7도 높게 유지해요."},{"kind":"points","head":"흙의 단점 2가지와 마무리 화살표","items":["1) 수분에 취약함: 재료 사용 위치나 방법을 면밀히 검토할 필요가 있어요.","2) 갈라짐 현상: 배합비율과 건조 시 주의가 필요해요.","화살표 줄: 건축재료로 사용할 경우, 건축부위별로 요구되는 성능 및 물성 확인이 필요해요.","이 화살표가 다음 쪽으로 이어져요. **흙건축(Earth Architecture)** 의 공법 이야기가 뒤따라요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"흙의 단열과 축열기능에 대한 설명으로 옳은 것은?","choices":["여름 최고기온이 실외보다 5~7도 낮다","여름 최고기온이 실외보다 3~10도 정도 낮다","겨울 최저기온이 실외보다 3~10도 낮다","겨울과 여름 모두 실외와 같다"],"a":1,"why":"여름은 3~10도 정도 낮고, 겨울 최저기온은 5~7도 정도 높아요. 숫자 짝을 바꾸면 틀려요."},{"kind":"check","q":"흙의 공기 정화 기능의 까닭으로 슬라이드가 든 것은?","choices":["흙의 미립자에 공극이 많아서","토양 미생물과 효소작용 때문에","습도를 조절해서","폐기물이 없어서"],"a":0,"why":"공기 정화는 '공극', 항균과 방충은 '토양 미생물과 효소작용' 이에요. 까닭을 바꿔 내기 좋아요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"흙은 천연의 습도 조절기능, 단열과 축열기능, 공기 정화 기능, 항균과 방충 효과, 폐기물 발생 없음의 특성을 가지며, 수분에 취약하고 갈라짐 현상이 생기는 단점이 있다.","ko":"특성 다섯 가지 이름과 단점 두 가지를 한 문장에 넣으면 돼요.","tip":"'습도 - 열 - 공기 - 균 - 폐기물' 다섯 글자로 특성을 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["여름 3~10도 낮게, 겨울 5~7도 높게예요. 두 숫자를 서로 바꿔 내기 딱 좋아요.","나무는 **통기성(Breathability)** 가 높았고, 흙은 공극이 많아요. 까닭이 서로 달라요.","마지막 화살표는 다음 쪽으로 넘기는 줄이에요. 부위별 성능 표는 이 쪽에 없어요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.0478,0.063],"c":[0,0.0701,0.2,0.095],"r":2.807,"img":"img/E2/walk/p028_h.jpg"},"parts":[{"b":[0.095,0.222,0.12,0.05],"c":[0.055,0.192,0.2,0.11],"r":2.4242,"img":"img/E2/walk/p028_24_01.jpg","say":"윗덩어리 제목 '흙의 특성' 이에요. 아래 다섯 줄이 이어져요."},{"b":[0.065,0.275,0.85,0.17],"c":[0.0225,0.259,0.935,0.202],"r":6.1716,"img":"img/E2/walk/p028_24_02.jpg","say":"1) 과 2) 예요. 2) 는 두 줄이고 숫자 3~10도와 5~7도가 여기 있어요."},{"b":[0.065,0.435,0.82,0.11],"c":[0.024,0.3989,0.902,0.1822],"r":6.6008,"img":"img/E2/walk/p028_24_03.jpg","say":"3) 공기 정화와 4) 항균, 방충이에요. 까닭이 각각 공극, 토양 미생물과 효소작용이에요."},{"b":[0.065,0.54,0.56,0.05],"c":[0.037,0.5028,0.616,0.1245],"r":6.5971,"img":"img/E2/walk/p028_24_04.jpg","say":"5) 폐기물 발생 없음이에요. 건축물 폐기 시 자연으로 환원돼요."},{"b":[0.095,0.648,0.1,0.05],"c":[0.045,0.618,0.2,0.11],"r":2.4242,"img":"img/E2/walk/p028_24_05.jpg","say":"아랫덩어리 제목 '단점' 이에요. 두 줄뿐이에요."},{"b":[0.065,0.7,0.78,0.16],"c":[0.026,0.684,0.858,0.192],"r":5.9583,"img":"img/E2/walk/p028_24_06.jpg","say":"단점 두 줄과 마무리 화살표예요. 건축부위별 성능과 물성을 확인해야 한다고 했어요."}]}},{"p":29,"title":"흙 건축부위별 요구 성능: 어디에 쓰느냐에 따라 필요한 힘이 달라요","terms":["Earth Architecture","Compressive Strength","Bond Strength","Frost Resistance","Non-shrinkage","Incombustibility","Humidity Control","Heat Storage"],"pass1":[{"kind":"say","lines":["앞에서 **흙건축(Earth Architecture)** 의 좋은 점을 봤어요.","흙은 **습도 조절(Humidity Control)** 와 **축열(Heat Storage)** 가 뛰어난 재료였죠.","이 쪽의 이야기는 딱 하나예요. 흙을 '어디에' 쓰느냐에 따라 필요한 힘이 달라요.","무게를 받치는 자리와 실내 벽에 바르는 자리는 요구가 서로 달라요."]},{"kind":"analogy","head":"바깥 신발과 실내화","scene":"밖에서 신는 신발은 튼튼하고 얼어도 갈라지지 않아야 해요. 실내화는 발에 잘 붙고 벗겨지지 않으면 돼요. 흙도 쓰는 자리에 따라 필요한 힘이 달라요.","map":[["밖에서 신는 튼튼한 신발","구조재료에 필요한 **압축강도(Compressive Strength)**"],["얼어도 갈라지지 않는 밑창","**동해저항(Frost Resistance)**"],["발에 잘 붙는 실내화","실내 마감재료에 필요한 **부착강도(Bond Strength)**"],["어디에 쓰든 모양이 줄지 않기","**비수축성(Non-shrinkage)**"]]}],"pass2":[{"kind":"points","head":"이 쪽에 나오는 성능 용어부터 풀어요","items":["**압축강도(Compressive Strength)**: 물체가 누르는 힘을 어느 정도 견디는지예요.","**부착강도(Bond Strength)**: 재료가 견고하게 잘 붙어 있는지예요.","**동해저항(Frost Resistance)**: 추위로 인해 얼지 않는 것이에요.","**비수축성(Non-shrinkage)**: 마르면서 줄어들지 않는 성질이에요.","**불연성(Incombustibility)**: 불에 타지 않는 성질이에요."]},{"kind":"look","walked":1},{"kind":"compare","head":"표 읽기: 건축부위별 요구 성능","cols":["건축부위","역학적 성능","물리적 성능","내구적 성능","화재 성능"],"rows":[["구조재료 (기둥, 내력벽)","압축강도","비 수축성","동해 저항, 항 곰팡이","불연성"],["실내마감재료 (미장, 벽돌, 패널)","부착강도","비 수축성","항 곰팡이","불연성, 비유독 가스"],["실외 마감재료 (벽돌, 패널)","압축강도","비 수축성","동해 저항, 항 곰팡이","불연성"],["조경재료 (산책로, 바닥)","압축 휨강도","비 수축성","동해 저항","-"]]},{"kind":"points","head":"표의 오른쪽 두 칸은 네 부위가 함께 써요","items":["감각적 성능: 색채, 촉감, 질감, 디자인이에요.","생산성능: 시공성, 성형성, 가공성이에요.","**비수축성(Non-shrinkage)** 은 네 부위 모두에 들어가요.","조경재료의 화재 성능 칸만 '-' 로 비어 있어요."]}],"pass3":[{"kind":"check","q":"흙을 실내 마감재료로 사용할 때 역학적 성능으로 필요한 것은?","choices":["**압축강도(Compressive Strength)**","**부착강도(Bond Strength)**","**동해저항(Frost Resistance)**","압축 휨강도"],"a":1,"why":"실내 마감재료는 **부착강도(Bond Strength)** 예요. 구조재료와 실외 마감재료가 **압축강도(Compressive Strength)** 이고, 조경재료만 압축 휨강도예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["비유독가스 성능은 실내마감재료 칸에만 붙어요.","**동해저항(Frost Resistance)** 은 실내마감재료 칸에는 없어요. 나머지 세 부위에만 있어요.","조경재료의 역학적 성능은 '압축 휨강도' 로 따로 적혀 있어요."]},{"kind":"english","head":"시험 답안에 쓸 문장","en":"흙을 구조재료로 쓸 때는 압축강도, 실내 마감재료로 쓸 때는 부착강도가 필요하다.","ko":"**압축강도(Compressive Strength)** 는 누르는 힘을 견디는 성능, **부착강도(Bond Strength)** 는 잘 붙어 있는 성능이에요.","tip":"'기둥은 눌러서 압축, 실내 벽은 붙여서 부착' 으로 외우면 안 헷갈려요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.0478,0.063],"c":[0,0.0701,0.2,0.095],"r":2.807,"img":"img/E2/walk/p029_h.jpg"},"parts":[{"b":[0.098,0.226,0.285,0.04],"c":[0.0837,0.191,0.3135,0.11],"r":3.8,"img":"img/E2/walk/p029_21_01.jpg","say":"제목이에요. 흙을 건축부위별로 나눠 요구 성능을 정리한 쪽이에요."},{"b":[0.16,0.285,0.75,0.042],"c":[0.1225,0.2227,0.825,0.1667],"r":6.5987,"img":"img/E2/walk/p029_21_02.jpg","say":"구조재료로 사용할 경우 첫 줄이에요. **압축강도(Compressive Strength)** 가 필요해요."},{"b":[0.49,0.344,0.412,0.1],"c":[0.4694,0.328,0.4532,0.132],"r":4.5778,"img":"img/E2/walk/p029_21_03.jpg","say":"이어서 **동해저항(Frost Resistance)**, **비수축성(Non-shrinkage)**, 항 곰팡이, **불연성(Incombustibility)** 이 필요해요."},{"b":[0.158,0.465,0.776,0.042],"c":[0.1192,0.3998,0.8536,0.1725],"r":6.5979,"img":"img/E2/walk/p029_21_04.jpg","say":"실내 마감재료로 사용할 경우예요. 여기는 **부착강도(Bond Strength)** 가 필요해요."},{"b":[0.545,0.524,0.32,0.1],"c":[0.529,0.508,0.352,0.132],"r":3.5556,"img":"img/E2/walk/p029_21_05.jpg","say":"실내는 **비수축성(Non-shrinkage)**, 항 곰팡이, **불연성(Incombustibility)**, 비유독가스 성능이 필요해요."},{"b":[0.085,0.658,0.835,0.292],"c":[0.0432,0.642,0.9185,0.324],"r":3.7798,"img":"img/E2/walk/p029_21_06.jpg","say":"아래 표가 네 가지 건축부위의 요구 성능을 한눈에 보여 줘요."}]}},{"p":30,"title":"흙 건축재료 및 공법: 부위별로 쓸 수 있는 흙 재료 표","terms":["Earth Architecture","Rammed Earth","Clay Straw","Plaster","Load-bearing Wall","Non-load-bearing Wall"],"pass1":[{"kind":"say","lines":["이번 쪽은 표 한 장이 전부예요.","세로줄은 흙 재료 여덟 가지, 가로줄은 건물의 부위예요.","칸에 동그라미가 있으면 그 부위에 그 재료를 쓸 수 있다는 뜻이에요.","**흙건축(Earth Architecture)** 재료를 부위별로 골라 쓰는 지도라고 보면 돼요."]}],"pass2":[{"kind":"points","head":"표의 세로줄, 흙 재료 여덟 가지","items":["앞의 네 가지는 **담틀 공법(Rammed Earth)**, 진흙, **흙짚(Clay Straw)**, 경량흙 이에요.","뒤의 네 가지는 Loam filling, 흙몰탈, 흙벽돌, 흙판넬 이에요.","맨 아래 가로줄 **플라스터(Plaster)** 옆에는 '회반죽 (도장 등에 사용)' 이라고 풀이가 붙어 있어요."]},{"kind":"look","walked":1},{"kind":"compare","head":"표에서 동그라미가 있는 칸만 모으면","cols":["건축부위","쓸 수 있는 재료"],"rows":[["바닥(Floor)","담틀 공법, Loam filling"],["내력벽(Wall loadbearing)","담틀 공법, 진흙, 흙몰탈, 흙벽돌"],["비내력벽(wall-freestanding)","담틀 공법, 진흙, 흙짚, 경량흙, 흙몰탈, 흙벽돌, 흙판넬"],["천정/지붕(Ceiling/Roof)","흙짚, 경량흙, Loam filling, 흙벽돌, 흙판넬"],["건식공법(Dry construction)","흙벽돌, 흙판넬"],["플라스터(Plaster)","흙짚, 경량흙, 흙몰탈"]]}],"pass3":[{"kind":"check","q":"표에서 동그라미가 가장 많은, 곧 가장 다양한 흙 재료를 쓸 수 있는 부위는?","choices":["바닥(Floor)","**내력벽(Load-bearing Wall)**","**비내력벽(Non-load-bearing Wall)**","건식공법(Dry construction)"],"a":2,"why":"**비내력벽(Non-load-bearing Wall)** 는 Loam filling 을 뺀 일곱 가지에 동그라미가 있어요. 무게를 받치지 않으니 재료를 고르기 쉬워요."},{"kind":"check","q":"표 맨 아래 **플라스터(Plaster)** 아래 화살표에 붙은 풀이말은?","choices":["회반죽 (도장 등에 사용)","거푸집 (벽 세우기에 사용)","충진재 (속을 채우는 데 사용)"],"a":0,"why":"슬라이드는 **플라스터(Plaster)** 를 '회반죽 (도장 등에 사용)' 이라고 풀어 적었어요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2716,0.063],"c":[0.0376,0.0701,0.2987,0.095],"r":4.1923,"img":"img/E2/walk/p030_h.jpg"},"parts":[{"b":[0.33,0.343,0.625,0.042],"c":[0.2988,0.2946,0.6875,0.1389],"r":6.5995,"img":"img/E2/walk/p030_21_01.jpg","say":"표의 맨 윗줄이 재료 이름이에요. 맨 왼쪽이 **담틀 공법(Rammed Earth)** 이에요."},{"b":[0.088,0.428,0.868,0.046],"c":[0.0446,0.3545,0.9548,0.1929],"r":6.5996,"img":"img/E2/walk/p030_21_02.jpg","say":"**내력벽(Load-bearing Wall)** 줄이에요. 담틀 공법, 진흙, 흙몰탈, 흙벽돌 네 곳에만 동그라미예요."},{"b":[0.088,0.474,0.868,0.046],"c":[0.0446,0.4005,0.9548,0.1929],"r":6.5996,"img":"img/E2/walk/p030_21_03.jpg","say":"**비내력벽(Non-load-bearing Wall)** 줄이에요. Loam filling 만 빼고 일곱 곳에 동그라미예요."},{"b":[0.088,0.519,0.868,0.046],"c":[0.0446,0.4455,0.9548,0.1929],"r":6.5996,"img":"img/E2/walk/p030_21_04.jpg","say":"천정/지붕 줄이에요. **흙짚(Clay Straw)**, 경량흙, Loam filling, 흙벽돌, 흙판넬이에요."},{"b":[0.088,0.565,0.868,0.046],"c":[0.0446,0.4915,0.9548,0.1929],"r":6.5996,"img":"img/E2/walk/p030_21_05.jpg","say":"건식공법 줄이에요. 미리 만들어 두는 흙벽돌, 흙판넬 두 가지뿐이에요."},{"b":[0.088,0.61,0.868,0.046],"c":[0.0446,0.5365,0.9548,0.1929],"r":6.5996,"img":"img/E2/walk/p030_21_06.jpg","say":"**플라스터(Plaster)** 줄이에요. **흙짚(Clay Straw)**, 경량흙, 흙몰탈이 쓰여요."}]}},{"p":31,"title":"담틀 공법, 흙짚 방식, 심벽: 흙으로 벽을 만드는 세 가지 방법","terms":["Earth Architecture","Rammed Earth","Clay Straw","심벽","Load-bearing Wall"],"pass1":[{"kind":"say","lines":["흙으로 벽을 만드는 방법 세 가지가 표로 나와요.","**담틀 공법(Rammed Earth)** 은 틀에 흙을 넣고 꾹꾹 다져요.","**흙짚(Clay Straw)** 은 짚을 점토물에 담갔다가 틀에 채워 다져요.","**심벽** 은 나무 뼈대에 심을 얽고 흙을 안팎으로 발라요."]},{"kind":"analogy","head":"모래성 만들 때를 떠올려요","scene":"양동이에 모래를 꾹꾹 눌러 담거나, 지푸라기를 섞어 붙이거나, 막대 뼈대에 진흙을 바르거나. 흙벽도 딱 이 세 가지 방법이에요.","map":[["양동이에 꾹꾹 눌러 담기","**담틀 공법(Rammed Earth)**"],["지푸라기 섞은 진흙 채우기","**흙짚(Clay Straw)**"],["막대 뼈대에 진흙 바르기","**심벽**"]]}],"pass2":[{"kind":"points","head":"**담틀 공법(Rammed Earth)** 칸 읽기","items":["목재나 철제 거푸집을 이용해 흙을 채워 넣고 다져서 벽을 구축하는 방법이에요.","물을 함수율에 맞게 배합하여 다져서 벽체의 강도를 견고하게 만드는 방식이에요.","흙벽 자체가 **내력벽(Load-bearing Wall)** 으로 지붕의 하중을 지지하는 구조체가 돼요.","밀도 1700~2200kg/m³ 로 흙건축 형태에서 가장 밀도가 높아요."]},{"kind":"points","head":"**흙짚(Clay Straw)** 칸 읽기","items":["북유럽에서 발전한 방식이에요. 유기섬유질의 짚을 점토에 개어 놓은 물속에 하루 정도 담가 둬요.","그다음 이를 거푸집 속에 채워 다져 나가요.","벽체 안팎으로 다시 흙으로 미장하는 방법이라 단열효과가 뛰어나요.","완전 건조시키면 밀도는 1200~1700kg/m³ 가 돼요.","젖어 있을 때 유동성이 있어 리노베이션이나 목구조 건축물의 충진재로 쓰고, 벽돌이나 판넬로도 만들어요."]},{"kind":"points","head":"**심벽** 칸 읽기","items":["목구조 사이에 대나무나 나뭇가지, 수수깡 등으로 심을 얽어요.","여기에 진흙에 물과 짚을 넣어 이긴 흙을 안팎으로 바르는 것이에요.","집을 지을 때 순서는 구덩이 파고 돌 넣고 흙 고르기(기초공사)로 시작해요.","이어서 주추 놓기, 기둥세우기, 서까래 올리기, 벽체에 흙 치기 과정을 거쳐 완성해요."]},{"kind":"look","walked":1},{"kind":"figure","head":"세 가지 방법을 그림 한 장으로","svg":"<svg viewBox=\"0 0 480 250\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"80\" y=\"22\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">담틀 공법<\/text><rect x=\"20\" y=\"40\" width=\"12\" height=\"140\" rx=\"2\" class=\"n b1\"/><rect x=\"128\" y=\"40\" width=\"12\" height=\"140\" rx=\"2\" class=\"n b1\"/><rect x=\"32\" y=\"140\" width=\"96\" height=\"40\" rx=\"2\" class=\"n3 b1\"/><rect x=\"32\" y=\"100\" width=\"96\" height=\"40\" rx=\"2\" class=\"n3 b1\"/><rect x=\"32\" y=\"60\" width=\"96\" height=\"40\" rx=\"2\" class=\"n3 b1\"/><text x=\"80\" y=\"202\" font-size=\"13\" text-anchor=\"middle\" class=\"t b1\">다져서 내력벽<\/text><text x=\"80\" y=\"224\" font-size=\"13\" text-anchor=\"middle\" class=\"tm b1\">1700~2200<\/text><text x=\"240\" y=\"22\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">흙짚 방식<\/text><rect x=\"180\" y=\"40\" width=\"12\" height=\"140\" rx=\"2\" class=\"n b2\"/><rect x=\"288\" y=\"40\" width=\"12\" height=\"140\" rx=\"2\" class=\"n b2\"/><rect x=\"192\" y=\"60\" width=\"96\" height=\"120\" rx=\"2\" class=\"n2 b2\"/><line x1=\"200\" y1=\"82\" x2=\"232\" y2=\"72\" class=\"e b2\"/><line x1=\"240\" y1=\"112\" x2=\"276\" y2=\"102\" class=\"e b2\"/><line x1=\"200\" y1=\"152\" x2=\"236\" y2=\"142\" class=\"e b2\"/><text x=\"240\" y=\"202\" font-size=\"13\" text-anchor=\"middle\" class=\"t b2\">짚을 점토물에 담가<\/text><text x=\"240\" y=\"224\" font-size=\"13\" text-anchor=\"middle\" class=\"tm b2\">1200~1700<\/text><text x=\"400\" y=\"22\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b3\">심벽<\/text><rect x=\"344\" y=\"40\" width=\"14\" height=\"140\" rx=\"2\" class=\"n b3\"/><rect x=\"442\" y=\"40\" width=\"14\" height=\"140\" rx=\"2\" class=\"n b3\"/><line x1=\"358\" y1=\"72\" x2=\"442\" y2=\"72\" class=\"e2 b3\"/><line x1=\"358\" y1=\"110\" x2=\"442\" y2=\"110\" class=\"e2 b3\"/><line x1=\"358\" y1=\"148\" x2=\"442\" y2=\"148\" class=\"e2 b3\"/><line x1=\"380\" y1=\"42\" x2=\"380\" y2=\"178\" class=\"e2 b3\"/><line x1=\"420\" y1=\"42\" x2=\"420\" y2=\"178\" class=\"e2 b3\"/><text x=\"400\" y=\"202\" font-size=\"13\" text-anchor=\"middle\" class=\"t b3\">심 얽고 흙 바르기<\/text><\/svg>","caption":"왼쪽은 거푸집에 흙을 켜켜이 다지고, 가운데는 짚 섞은 흙을 채우고, 오른쪽은 얽은 심에 흙을 발라요. 숫자는 밀도 kg/m³ 예요.","builds":3}],"pass3":[{"kind":"check","q":"'흙벽 자체가 내력벽으로 지붕의 하중을 지지하고, 밀도가 1700~2200kg/m³ 로 가장 높은' 방식은?","choices":["**담틀 공법(Rammed Earth)**","**흙짚(Clay Straw)**","**심벽**","Loam filling"],"a":0,"why":"**담틀 공법(Rammed Earth)** 이에요. **흙짚(Clay Straw)** 은 완전 건조 시 1200~1700kg/m³ 이고 단열효과가 뛰어나요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["밀도 경계가 1700 로 겹쳐요. **담틀 공법(Rammed Earth)** 1700~2200, **흙짚(Clay Straw)** 1200~1700 이에요.","북유럽에서 발전한 것은 **흙짚(Clay Straw)** 이에요. 담틀 공법이 아니에요.","**심벽** 의 심 재료는 대나무, 나뭇가지, 수수깡이에요. 짚은 심이 아니라 흙에 섞어요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2716,0.063],"c":[0.0376,0.0701,0.2987,0.095],"r":4.1923,"img":"img/E2/walk/p031_h.jpg"},"parts":[{"b":[0.098,0.19,0.79,0.04],"c":[0.0585,0.1222,0.869,0.1756],"r":6.5983,"img":"img/E2/walk/p031_23_01.jpg","say":"맨 위 줄이에요. 건축구조에 따라 적용 가능한 다양한 흙건축 재료를 숙지해야 한다고 했어요."},{"b":[0.098,0.252,0.68,0.04],"c":[0.064,0.1964,0.748,0.1511],"r":6.6005,"img":"img/E2/walk/p031_23_02.jpg","say":"**내력벽(Load-bearing Wall)** 의 경우는 일정강도를 유지하도록 흙을 가공하여 사용해요."},{"b":[0.098,0.312,0.64,0.042],"c":[0.066,0.2619,0.704,0.1422],"r":6.601,"img":"img/E2/walk/p031_23_03.jpg","say":"비내력벽, 천정, 지붕 등에는 다양한 흙건축 재료를 사용할 수 있어요."},{"b":[0.118,0.44,0.58,0.11],"c":[0.089,0.424,0.638,0.142],"r":5.9906,"img":"img/E2/walk/p031_23_04.jpg","say":"**담틀 공법(Rammed Earth)** 칸이에요. 마지막 줄의 밀도 1700~2200kg/m³ 가 시험에 잘 나와요."},{"b":[0.118,0.582,0.58,0.2],"c":[0.089,0.566,0.638,0.232],"r":3.6667,"img":"img/E2/walk/p031_23_05.jpg","say":"**흙짚(Clay Straw)** 칸이에요. 북유럽, 하루 정도 담그기, 밀도 1200~1700kg/m³ 를 챙겨요."},{"b":[0.118,0.82,0.58,0.14],"c":[0.089,0.804,0.638,0.172],"r":4.9457,"img":"img/E2/walk/p031_23_06.jpg","say":"**심벽** 칸이에요. 심을 얽는 재료와 집 짓는 순서가 적혀 있어요."}]}},{"p":32,"title":"흙벽돌: 아도브와 압축 흙벽돌, 그리고 굽지 않는 이유","terms":["Earth Architecture","Adobe","Bloc Terre Comprimé","Load-bearing Wall"],"pass1":[{"kind":"say","lines":["앞 쪽 표가 이어져요. 이번 칸은 흙벽돌이에요.","**아도브(Adobe)** 는 틀 속에 흙을 채워 만드는 방식이에요.","흙을 틀에 넣고 높은 압력을 가하면 **압축 흙벽돌(Bloc Terre Comprimé)** 이 돼요.","가장 중요한 한 줄은 '흙벽돌은 굽지 않는다' 예요."]}],"pass2":[{"kind":"points","head":"**아도브(Adobe)** 칸의 네 줄","items":["**아도브(Adobe)**: 틀 속에 흙을 채워 만드는 방식이에요.","중소형 벽돌제작 기계로 현장에서 찍는 흙벽돌은 15톤 하중 정도예요.","공장에서 제작된 기계압 벽돌은 35톤 하중 정도예요.","**압축 흙벽돌(Bloc Terre Comprimé)**: 흙을 틀 속에 넣어 높은 압력을 가하여 강도를 높인 것이에요."]},{"kind":"points","head":"흙벽돌을 만들고 쌓는 방법","items":["진흙에 물을 반죽하여 네모난 틀 속에 채워 넣고 형을 떠요.","이를 햇볕에 건조하여 조적하는 방식으로 **내력벽(Load-bearing Wall)** 의 구실을 해요.","지역에 따라 강도를 높이고 건조 시 수축과 균열을 피하려고 짚이나 풀잎, 동물의 털 등을 섞기도 해요.","흙벽돌은 불에 굽게 되면 대부분 흙의 성질을 잃게 되므로 굽지 않은 벽돌을 쓰도록 해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"흙벽돌을 불에 굽지 않는 이유로 슬라이드가 든 것은?","choices":["굽는 데 시간이 오래 걸려서","불에 구우면 대부분 흙의 성질을 잃게 되어서","구우면 색이 어두워져서","굽는 것이 법으로 금지되어서"],"a":1,"why":"슬라이드 마지막 줄이에요. 구우면 흙의 성질을 잃으니 굽지 않은 벽돌을 써요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["하중 숫자를 바꿔 내기 좋아요. 현장 중소형 기계 15톤, 공장 기계압 35톤이에요.","슬라이드 표기는 'Bloc Terre Comprim' 이지만 흔히 Bloc Terre Comprimé 로 써요.","**아도브(Adobe)** 는 통상 '어도비' 로도 옮겨요. 다음 쪽 밍케하우스의 '어도비 벽돌' 과 같은 말이에요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2716,0.063],"c":[0.0376,0.0701,0.2987,0.095],"r":4.1923,"img":"img/E2/walk/p032_h.jpg"},"parts":[{"b":[0.128,0.322,0.12,0.04],"c":[0.088,0.287,0.2,0.11],"r":2.4242,"img":"img/E2/walk/p032_22_01.jpg","say":"표의 머리줄이에요. 왼쪽이 유형, 오른쪽이 내용이에요."},{"b":[0.185,0.374,0.54,0.042],"c":[0.158,0.335,0.594,0.12],"r":6.6,"img":"img/E2/walk/p032_22_02.jpg","say":"**아도브(Adobe)** 를 설명하는 첫 줄이에요."},{"b":[0.185,0.405,0.54,0.07],"c":[0.158,0.38,0.594,0.12],"r":6.6,"img":"img/E2/walk/p032_22_03.jpg","say":"15톤과 35톤, 두 숫자가 붙어 있는 두 줄이에요."},{"b":[0.185,0.466,0.54,0.07],"c":[0.158,0.441,0.594,0.12],"r":6.6,"img":"img/E2/walk/p032_22_04.jpg","say":"**압축 흙벽돌(Bloc Terre Comprimé)** 줄이에요. 슬라이드 표기는 'Bloc Terre Comprim' 이에요."},{"b":[0.185,0.56,0.54,0.115],"c":[0.158,0.544,0.594,0.147],"r":5.3878,"img":"img/E2/walk/p032_22_05.jpg","say":"진흙을 반죽해 틀에 넣고 햇볕에 말려 쌓는 방법이에요."},{"b":[0.185,0.684,0.54,0.045],"c":[0.158,0.6465,0.594,0.12],"r":6.6,"img":"img/E2/walk/p032_22_06.jpg","say":"마지막 줄이 '굽지 않은 벽돌을 쓰도록 함' 이에요."}]}},{"p":33,"title":"독일 카셀의 밍케하우스: 흙집 국외 적용사례","terms":["Minke House","Adobe Brick","Green Roof","Humidity Control","Heat Storage","Earth Architecture"],"pass1":[{"kind":"say","lines":["이제 흙집을 실제로 지은 사례를 봐요.","독일 카셀의 생태단지 안에 있는 **밍케하우스(Minke House)** 예요.","돔처럼 둥근 집인데 지붕이 온통 풀로 덮여 있어요.","벽, 지붕, 바닥 대부분이 **어도비 벽돌(Adobe Brick)** 이에요."]},{"kind":"analogy","head":"풀 모자를 쓴 뚝배기 집","scene":"뚝배기 같은 흙 그릇에 두꺼운 풀 모자를 씌운 모습이에요. 모자가 더위와 추위를 막아 주고, 비는 모자와 마당 흙에 스며들어요.","map":[["푹신한 풀 모자","**지붕 녹화(Green Roof)**, 단열효과와 열손실 줄이기"],["뚝배기 그릇","**어도비 벽돌(Adobe Brick)** 이 만든 **축열(Heat Storage)**, 실내 온도차가 적음"],["숨 쉬는 흙벽","**습도 조절(Humidity Control)** 기능"],["비가 흙에 스며듦","빗물 침투, 일부분만 하천으로 유출"]]}],"pass2":[{"kind":"points","head":"슬라이드의 앞 네 줄","items":["돔형의 주거건물이에요. 목구조 및 흙벽돌을 이용하여 건축했어요.","**지붕 녹화(Green Roof)**: 단열효과가 있고 열손실이 거의 없는 구조예요.","구조체를 제외한 벽체, 지붕, 바닥 등 건물 대부분에 '어도비' 벽돌을 사용했어요.","**어도비 벽돌(Adobe Brick)** 로 인한 내부 디자인 효과 및 **습도 조절(Humidity Control)** 기능이 생겨요."]},{"kind":"points","head":"슬라이드의 뒤 세 줄","items":["자연적인 온도조절 기능이 있어요. 실내 온도차가 적어요.","온도차가 적은 것은 흙벽의 **축열(Heat Storage)** 덕분이에요. 뚝배기를 떠올리면 돼요.","빗물관리: 녹화된 지붕과 외부공간의 흙 바닥으로 침투해요.","일부분만 하천으로 유출되어 관개시설 비용이 절감돼요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**밍케하우스(Minke House)** 의 특징으로 슬라이드에 나오지 않는 것은?","choices":["돔형 주거건물, 목구조 및 흙벽돌","지붕 녹화로 단열효과와 열손실 감소","빗물을 모두 하천으로 바로 흘려보냄","어도비 벽돌로 내부 디자인 효과와 습도 조절"],"a":2,"why":"빗물은 녹화된 지붕과 외부공간의 흙 바닥으로 침투하고 일부분만 하천으로 유출돼요. 그래서 관개시설 비용이 절감돼요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"밍케하우스는 독일 카셀 생태단지의 돔형 주거건물로, 목구조와 흙벽돌로 짓고 지붕을 녹화해 열손실이 거의 없으며, 건물 대부분에 어도비 벽돌을 써서 습도 조절과 실내 온도차 감소 효과를 얻는다.","ko":"장소, 형태, 구조, **지붕 녹화(Green Roof)**, **어도비 벽돌(Adobe Brick)** 의 다섯 덩어리로 끊어 쓰면 돼요.","tip":"'카셀 - 돔 - 목구조와 흙벽돌 - 잔디지붕 - 어도비' 다섯 낱말로 외워요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2342,0.063],"c":[0.0391,0.0701,0.2582,0.095],"r":3.6239,"img":"img/E2/walk/p033_h.jpg"},"parts":[{"b":[0.068,0.192,0.47,0.042],"c":[0.0445,0.158,0.517,0.11],"r":6.2667,"img":"img/E2/walk/p033_22_01.jpg","say":"제목 줄이에요. < 독일 카셀의 생태단지 내 밍케하우스 > 라고 적혀 있어요."},{"b":[0.098,0.312,0.59,0.042],"c":[0.0685,0.2674,0.649,0.1311],"r":6.6006,"img":"img/E2/walk/p033_22_02.jpg","say":"돔형 주거건물, 목구조 및 흙벽돌이라는 첫 줄이에요."},{"b":[0.098,0.372,0.53,0.042],"c":[0.0715,0.3341,0.583,0.1178],"r":6.5988,"img":"img/E2/walk/p033_22_03.jpg","say":"**지붕 녹화(Green Roof)** 줄이에요. 단열효과, 열손실이 거의 없는 구조예요."},{"b":[0.098,0.432,0.79,0.1],"c":[0.0585,0.3942,0.869,0.1756],"r":6.5983,"img":"img/E2/walk/p033_22_04.jpg","say":"건물 대부분에 어도비 벽돌을 썼고 그래서 디자인과 습도 조절 효과가 생겨요."},{"b":[0.098,0.552,0.525,0.042],"c":[0.0718,0.5147,0.5775,0.1167],"r":6.5981,"img":"img/E2/walk/p033_22_05.jpg","say":"자연적인 온도조절 기능, 실내 온도차가 적다는 줄이에요."},{"b":[0.098,0.612,0.8,0.1],"c":[0.058,0.5731,0.88,0.1778],"r":6.5992,"img":"img/E2/walk/p033_22_06.jpg","say":"빗물관리 두 줄이에요. 침투 후 일부분만 하천으로 유출되어 관개시설 비용이 절감돼요."}]}},{"p":34,"title":"밍케하우스 바깥 모습: 풀에 파묻힌 집","terms":["Minke House","Green Roof","잔디지붕"],"pass1":[{"kind":"say","lines":["**밍케하우스(Minke House)** 의 바깥 사진이에요.","지붕이 풀 언덕처럼 보여서 집이 자연 속에 묻혀 있어요.","앞 쪽에서 읽은 **지붕 녹화(Green Roof)** 를 눈으로 확인하는 쪽이에요."]}],"pass2":[{"kind":"look","walked":1}],"pass3":[],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.3999,0.063],"c":[0.0311,0.0701,0.4399,0.095],"r":6.174,"img":"img/E2/walk/p034_h.jpg"},"parts":[{"b":[0.09,0.21,0.83,0.19],"c":[0.0485,0.194,0.913,0.222],"r":5.4835,"img":"img/E2/walk/p034_20_01.jpg","say":"지붕 위가 온통 풀이에요. 이것이 **잔디지붕**, 곧 **지붕 녹화(Green Roof)** 이에요."},{"b":[0.28,0.38,0.44,0.12],"c":[0.258,0.364,0.484,0.152],"r":4.2456,"img":"img/E2/walk/p034_20_02.jpg","say":"지붕 선이 낮게 이어지고 처마가 얇게 떨어져요. 흙집 위에 흙과 풀을 얹은 모습이에요."},{"b":[0.3,0.47,0.42,0.26],"c":[0.279,0.454,0.462,0.292],"r":2.1096,"img":"img/E2/walk/p034_20_03.jpg","say":"입구가 아치 모양이에요. 아치 둘레를 벽돌로 둘러 곡선을 만들었어요."},{"b":[0.09,0.6,0.35,0.34],"c":[0.0725,0.583,0.385,0.374],"r":1.3725,"img":"img/E2/walk/p034_20_04.jpg","say":"집 둘레가 풀과 꽃이에요. 빗물이 이런 흙바닥으로 침투해요."}]}},{"p":35,"title":"잔디지붕 단면: 처마 끝은 통나무로 흙을 잡아요","terms":["Minke House","잔디지붕","Green Roof"],"pass1":[{"kind":"say","lines":["**잔디지붕** 을 잘라서 속을 보여 주는 그림 두 장이에요.","풀과 흙이 지붕 위에 얹혀 있으니 처마 쪽으로 흘러내릴 수 있어요.","그래서 처마 끝을 통나무로 막아 흙을 붙잡아요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"그림을 위에서 아래로 읽으면","items":["맨 위는 풀이에요. 그 아래가 흙 켜예요.","흙 아래에는 Kies, 곧 자갈 켜가 있어요.","그 아래가 방수층(Bitumen-Dachbahn)과 구조 목재예요.","처마 끝에 통나무를 대어 흙과 자갈이 흘러내리지 않게 막아요."]}],"pass3":[{"kind":"check","q":"**잔디지붕** 의 처마 끝 부분에 통나무를 댄 까닭은?","choices":["흙의 흘러내림을 방지하려고","빗물을 모아 두려고","지붕을 더 높이려고"],"a":0,"why":"슬라이드 아래 글 그대로예요. 처마 끝 부분은 통나무를 이용하여 흙의 흘러내림을 방지해요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.3999,0.063],"c":[0.0311,0.0701,0.4399,0.095],"r":6.174,"img":"img/E2/walk/p035_h.jpg"},"parts":[{"b":[0.1,0.18,0.42,0.1],"c":[0.079,0.164,0.462,0.132],"r":4.6667,"img":"img/E2/walk/p035_20_01.jpg","say":"왼쪽 그림 이름표예요. Traufbalken 은 처마에 대는 보라는 뜻의 독일어예요."},{"b":[0.53,0.186,0.4,0.09],"c":[0.51,0.17,0.44,0.122],"r":4.8087,"img":"img/E2/walk/p035_20_02.jpg","say":"오른쪽 그림은 Rundholz als Traufbalken 이에요. 처마 보로 통나무를 썼다는 뜻이에요."},{"b":[0.15,0.236,0.15,0.04],"c":[0.125,0.201,0.2,0.11],"r":2.4242,"img":"img/E2/walk/p035_20_03.jpg","say":"Kies 는 자갈이에요. 흙 아래에 자갈 켜가 깔려 있어요."},{"b":[0.07,0.79,0.36,0.06],"c":[0.052,0.765,0.396,0.11],"r":4.8,"img":"img/E2/walk/p035_20_04.jpg","say":"아래쪽 이름표는 Noppenfolie 와 Bitumen-Dachbahn, 곧 방수층이에요."},{"b":[0.5,0.8,0.36,0.06],"c":[0.482,0.775,0.396,0.11],"r":4.8,"img":"img/E2/walk/p035_20_05.jpg","say":"오른쪽은 Vlies 와 Bitumen-Dachbahn 이에요. 흙과 방수층 사이에 들어가요."},{"b":[0.098,0.924,0.805,0.042],"c":[0.0578,0.8211,0.8855,0.1789],"r":6.5996,"img":"img/E2/walk/p035_20_06.jpg","say":"아래 글: 잔디지붕의 단면구조로 처마 끝 부분은 통나무를 이용하여 흙의 흘러내림을 방지."}]}},{"p":36,"title":"민케의 집 단면도: 지붕이 모두 잔디로 덮인 집","terms":["Minke House","잔디지붕","Green Roof","Adobe Brick"],"pass1":[{"kind":"say","lines":["집 전체를 세로로 자른 단면도예요.","둥근 돔이 네 개 이어져 있고 그 위를 풀이 덮고 있어요.","앞 쪽에서 본 **지붕 녹화(Green Roof)** 가 집 전체에 깔려 있다는 것이 한눈에 보여요."]}],"pass2":[{"kind":"look","walked":1}],"pass3":[{"kind":"warn","head":"표기가 헷갈리는 점","items":["슬라이드에 '**밍케하우스(Minke House)**' 와 '민케의 집' 두 표기가 섞여 있어요. 같은 집이에요.","'천정' 은 슬라이드 표기예요. 통상은 '천장' 으로 써요.","단면도의 둥근 벽이 바로 **어도비 벽돌(Adobe Brick)** 을 쌓아 만든 벽이에요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.3999,0.063],"c":[0.0311,0.0701,0.4399,0.095],"r":6.174,"img":"img/E2/walk/p036_h.jpg"},"parts":[{"b":[0.06,0.27,0.88,0.2],"c":[0.016,0.254,0.968,0.232],"r":5.5632,"img":"img/E2/walk/p036_20_01.jpg","say":"지붕 곡선 위가 전부 풀이에요. **잔디지붕** 이 집 전체를 덮고 있어요."},{"b":[0.18,0.3,0.3,0.3],"c":[0.165,0.284,0.33,0.332],"r":1.3253,"img":"img/E2/walk/p036_20_02.jpg","say":"돔 아래가 방이에요. 천정(천장)이 둥글게 올라가요."},{"b":[0.44,0.47,0.18,0.18],"c":[0.428,0.454,0.204,0.212],"r":1.283,"img":"img/E2/walk/p036_20_03.jpg","say":"가운데 아치가 중앙 홀로 들어가는 입구예요. 다음 쪽 사진이 바로 이 홀이에요."},{"b":[0.08,0.6,0.86,0.07],"c":[0.037,0.5394,0.946,0.1911],"r":6.6004,"img":"img/E2/walk/p036_20_04.jpg","say":"바닥 선 아래로 기초가 보여요. 집이 땅에 낮게 앉아 있어요."},{"b":[0.18,0.848,0.65,0.045],"c":[0.1475,0.7983,0.715,0.1445],"r":6.5975,"img":"img/E2/walk/p036_20_05.jpg","say":"아래 글: 민케의 집 단면도, 지붕이 모두 잔디로 덮여있는 집."}]}},{"p":37,"title":"집 중앙의 홀: 어도비 벽돌이 그대로 실내 디자인","terms":["Minke House","Adobe Brick"],"pass1":[{"kind":"say","lines":["**밍케하우스(Minke House)** 안으로 들어왔어요. 집 중앙의 홀, 곧 거실이에요.","벽이 모두 벽돌이고 아치가 여러 개 보여요.","'**어도비 벽돌(Adobe Brick)** 로 인한 내부 디자인 효과' 가 바로 이 모습이에요."]}],"pass2":[{"kind":"look","walked":1}],"pass3":[],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.3999,0.063],"c":[0.0311,0.0701,0.4399,0.095],"r":6.174,"img":"img/E2/walk/p037_h.jpg"},"parts":[{"b":[0.17,0.22,0.66,0.28],"c":[0.137,0.204,0.726,0.312],"r":3.1026,"img":"img/E2/walk/p037_20_01.jpg","say":"벽마다 아치가 뚫려 있어요. 벽돌을 곡선으로 쌓아 만든 입구예요."},{"b":[0.17,0.33,0.2,0.4],"c":[0.158,0.31,0.224,0.44],"r":0.6788,"img":"img/E2/walk/p037_20_02.jpg","say":"벽면 마감을 따로 하지 않고 벽돌을 그대로 드러냈어요."},{"b":[0.4,0.44,0.25,0.3],"c":[0.3875,0.424,0.275,0.332],"r":1.1044,"img":"img/E2/walk/p037_20_03.jpg","say":"사람들이 바닥에 앉아 이야기하고 있어요. 이 홀이 집의 가운데 공간이에요."},{"b":[0.2,0.7,0.62,0.23],"c":[0.169,0.684,0.682,0.262],"r":3.4707,"img":"img/E2/walk/p037_20_04.jpg","say":"바닥도 벽돌과 돌로 무늬를 만들었어요. 가운데에는 나무가 심겨 있어요."},{"b":[0.28,0.922,0.44,0.042],"c":[0.258,0.888,0.484,0.11],"r":5.8667,"img":"img/E2/walk/p037_20_05.jpg","say":"아래 글: 진흙벽돌로 지어진 집 중앙의 홀(거실) 전경."}]}},{"p":38,"title":"중앙 홀의 돔 천정: 벽돌이 둥글게 쌓여 올라가요","terms":["Minke House","Adobe Brick","Earth Architecture"],"pass1":[{"kind":"say","lines":["같은 홀을 위쪽으로 올려다본 사진이에요.","벽돌이 둥근 띠를 그리며 천정(천장)까지 올라가요.","**어도비 벽돌(Adobe Brick)** 만으로 돔을 만든 **흙건축(Earth Architecture)** 의 모습이에요."]}],"pass2":[{"kind":"look","walked":1}],"pass3":[],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.3999,0.063],"c":[0.0311,0.0701,0.4399,0.095],"r":6.174,"img":"img/E2/walk/p038_h.jpg"},"parts":[{"b":[0.3,0.17,0.4,0.33],"c":[0.28,0.1535,0.44,0.363],"r":1.6162,"img":"img/E2/walk/p038_20_01.jpg","say":"천정(천장)이 둥근 돔이에요. 벽돌을 가로띠로 촘촘히 쌓아 올렸어요."},{"b":[0.3,0.5,0.18,0.3],"c":[0.288,0.484,0.204,0.332],"r":0.8193,"img":"img/E2/walk/p038_20_02.jpg","say":"왼쪽에 아치 통로가 보여요. 다른 방으로 이어져요."},{"b":[0.5,0.52,0.22,0.18],"c":[0.488,0.504,0.244,0.212],"r":1.5346,"img":"img/E2/walk/p038_20_03.jpg","say":"벽에 그림을 걸었어요. 벽돌 벽이 그대로 배경이 돼요."},{"b":[0.31,0.8,0.38,0.14],"c":[0.291,0.784,0.418,0.172],"r":3.2403,"img":"img/E2/walk/p038_20_04.jpg","say":"바닥에도 벽돌로 방사형 무늬를 만들었어요."},{"b":[0.28,0.934,0.44,0.042],"c":[0.258,0.89,0.484,0.11],"r":5.8667,"img":"img/E2/walk/p038_20_05.jpg","say":"아래 글: 진흙벽돌로 지어진 집 중앙의 홀(거실) 전경."}]}},{"p":39,"title":"응접실 전경: 아치 창과 벽돌 벽","terms":["Minke House","Adobe Brick"],"pass1":[{"kind":"say","lines":["**밍케하우스(Minke House)** 의 응접실 사진이에요.","아치 모양 창 하나로 바깥 초록이 그대로 들어와요.","벽은 여기서도 **어도비 벽돌(Adobe Brick)** 을 그대로 드러냈어요."]}],"pass2":[{"kind":"look","walked":1}],"pass3":[],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.3999,0.063],"c":[0.0311,0.0701,0.4399,0.095],"r":6.174,"img":"img/E2/walk/p039_h.jpg"},"parts":[{"b":[0.42,0.25,0.18,0.37],"c":[0.408,0.2315,0.204,0.407],"r":0.6683,"img":"img/E2/walk/p039_20_01.jpg","say":"아치 창이에요. 창 둘레만 붉은 벽돌로 둘러 강조했어요."},{"b":[0.29,0.2,0.42,0.3],"c":[0.269,0.184,0.462,0.332],"r":1.8554,"img":"img/E2/walk/p039_20_02.jpg","say":"벽이 둥글게 휘어 있어요. 돔 안쪽이라 평평한 벽이 없어요."},{"b":[0.29,0.5,0.42,0.1],"c":[0.269,0.484,0.462,0.132],"r":4.6667,"img":"img/E2/walk/p039_20_03.jpg","say":"창 양옆으로 책장이 벽을 따라 둘러져 있어요."},{"b":[0.29,0.56,0.42,0.3],"c":[0.269,0.544,0.462,0.332],"r":1.8554,"img":"img/E2/walk/p039_20_04.jpg","say":"가운데 낮은 탁자와 소파가 놓인 응접 공간이에요."},{"b":[0.4,0.944,0.22,0.042],"c":[0.388,0.89,0.244,0.11],"r":2.9576,"img":"img/E2/walk/p039_20_05.jpg","say":"아래 글: 응접실 전경."}]}},{"p":40,"title":"스트로베일 특성 8가지와 두 가지 공법","terms":["Straw Bale","골조방식","무골조방식","Load-bearing Wall","Humidity Control"],"pass1":[{"kind":"say","lines":["재료가 흙에서 짚으로 바뀌어요.","**스트로베일(Straw Bale)** 는 건초(짚)를 네모나게 꽉 묶은 블록이에요.","이 블록을 벽돌처럼 쌓아서 벽을 만들어요.","이 쪽에는 특성 8가지가 번호를 달고 줄줄이 나와요."]},{"kind":"analogy","head":"건초 블록은 커다란 레고","scene":"짚을 꽉 눌러 묶으면 네모난 덩어리가 돼요. 이 덩어리를 레고처럼 쌓고 겉에 흙이나 석회를 발라 벽을 완성해요.","map":[["레고 블록 쌓기","건초 블록을 벽돌처럼 쌓기"],["레고 위에 색칠하기","양 벽면을 흙이나 석회로 미장"],["젖은 블록은 못 씀","습도 20% 이하 블록만 사용"],["뼈대 있는 레고와 없는 레고","**골조방식** 와 **무골조방식**"]]}],"pass2":[{"kind":"points","head":"**스트로베일(Straw Bale)** 특성 1~4","items":["1) 자연에서 재생산이 가능한 지속가능한 자연재료예요.","2) **습도 조절(Humidity Control)**, 탈취, 방음, 단열성능이 우수해요.","3) 재료 채취 시 에너지 투입량이 적어 가격이 저렴해요(수거 수준).","4) 시공이 간단해요."]},{"kind":"points","head":"**스트로베일(Straw Bale)** 특성 5~7","items":["5) 건초 블록을 벽돌처럼 쌓아서 벽을 구성하고 양 벽면을 흙이나 석회로 미장해요.","6) 외벽은 흙 또는 석회 등으로 마감해요. 건조되고 나면 습기가 들어오지 않는 구조로 시공해요.","7) 건초 블록은 습도 20% 이하의 블록만 사용하여 습기에 의한 부식을 방지해요."]},{"kind":"compare","head":"8) 공법 두 가지","cols":["공법","방법","층수"],"rows":[["**골조방식**","가구식 구조를 먼저 세운 후 건초블록을 쌓아서 벽 구성","5층 이상 건축 가능 (현재는 7층 이상도 가능)"],["**무골조방식**","건초블록 자체가 **내력벽(Load-bearing Wall)** 역할을 하는 구조","2층까지 시공 가능"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**스트로베일(Straw Bale)** 에 쓰는 건초 블록의 습도 기준은?","choices":["습도 10% 이하","습도 20% 이하","습도 30% 이하","습도 기준이 없다"],"a":1,"why":"7) 건초 블록은 습도 20% 이하의 블록만 사용하여 습기에 의한 부식을 방지해요."},{"kind":"check","q":"건초블록 자체가 내력벽 역할을 하는 공법과 그 층수는?","choices":["**골조방식**, 5층 이상","**무골조방식**, 2층까지","**골조방식**, 2층까지","**무골조방식**, 7층 이상"],"a":1,"why":"**무골조방식** 은 블록이 **내력벽(Load-bearing Wall)** 이라 2층까지예요. **골조방식** 은 뼈대를 먼저 세워 5층 이상, 현재는 7층 이상도 가능해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["층수를 바꿔 내기 좋아요. **골조방식** 5층 이상, **무골조방식** 2층까지예요.","**스트로베일(Straw Bale)** 는 에너지 투입량이 적어서 값이 싸요. 비싼 재료가 아니에요.","미장 재료는 흙 또는 석회예요. 시멘트가 아니에요."]},{"kind":"english","head":"시험 답안에 쓸 문장","en":"스트로베일은 재생산이 가능한 자연재료로 습도조절, 탈취, 방음, 단열 성능이 우수하고 값이 싸며, 건초 블록을 쌓아 흙이나 석회로 미장해 벽을 만든다.","ko":"성능 네 가지(습도조절, 탈취, 방음, 단열)를 묶어서 외우면 답안이 쉬워져요.","tip":"'습, 탈, 방, 단' 네 글자로 앞글자만 따서 외워요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.1592,0.063],"c":[0.0307,0.0701,0.2,0.095],"r":2.807,"img":"img/E2/walk/p040_h.jpg"},"parts":[{"b":[0.066,0.22,0.3,0.042],"c":[0.051,0.186,0.33,0.11],"r":4.0,"img":"img/E2/walk/p040_23_01.jpg","say":"제목이에요. 아래로 1)부터 8)까지 번호가 붙어 있어요."},{"b":[0.066,0.276,0.64,0.118],"c":[0.034,0.26,0.704,0.15],"r":6.2578,"img":"img/E2/walk/p040_23_02.jpg","say":"1)~3) 이에요. 재생산 가능, 성능 네 가지, 저렴한 가격이 적혀 있어요."},{"b":[0.066,0.436,0.86,0.118],"c":[0.023,0.3994,0.946,0.1911],"r":6.6004,"img":"img/E2/walk/p040_23_03.jpg","say":"4)~6) 이에요. 간단한 시공, 쌓고 미장하기, 외벽 마감이에요."},{"b":[0.066,0.596,0.86,0.042],"c":[0.023,0.5214,0.946,0.1911],"r":6.6004,"img":"img/E2/walk/p040_23_04.jpg","say":"7) 이에요. 습도 20% 이하 블록만 사용한다는 숫자가 여기 있어요."},{"b":[0.066,0.649,0.86,0.104],"c":[0.023,0.6054,0.946,0.1911],"r":6.6004,"img":"img/E2/walk/p040_23_05.jpg","say":"8) 의 첫째 **골조방식** 이에요. 가구식 구조를 먼저 세우고 5층 이상 가능해요."},{"b":[0.155,0.756,0.78,0.09],"c":[0.116,0.7143,0.858,0.1733],"r":6.6013,"img":"img/E2/walk/p040_23_06.jpg","say":"8) 의 둘째 **무골조방식** 이에요. 블록 자체가 내력벽이고 2층까지예요."}]}},{"p":41,"title":"스트로베일 하우스 공사 사진: 블록을 쌓아 벽을 만들어요","terms":["Straw Bale","골조방식","무골조방식"],"pass1":[{"kind":"say","lines":["**스트로베일(Straw Bale)** 하우스를 짓는 사진 두 장이에요.","아직 미장을 하지 않아서 짚 블록이 그대로 보여요.","앞 쪽에서 읽은 두 공법을 눈으로 확인할 수 있어요."]}],"pass2":[{"kind":"look","walked":1}],"pass3":[],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2435,0.1638],"c":[0.039,0.0701,0.2678,0.1958],"r":1.8236,"img":"img/E2/walk/p041_h.jpg"},"parts":[{"b":[0.01,0.35,0.47,0.22],"c":[0,0.334,0.517,0.252],"r":2.7354,"img":"img/E2/walk/p041_20_01.jpg","say":"왼쪽 사진은 나무 기둥과 보가 먼저 서 있어요. 뼈대를 세운 **골조방식** 에 가까워요."},{"b":[0.01,0.56,0.47,0.32],"c":[0,0.544,0.517,0.352],"r":1.9583,"img":"img/E2/walk/p041_20_02.jpg","say":"기둥 사이를 짚 블록이 채우고 있어요. 아직 미장을 하지 않은 상태예요."},{"b":[0.49,0.35,0.5,0.25],"c":[0.45,0.334,0.55,0.282],"r":2.6005,"img":"img/E2/walk/p041_20_03.jpg","say":"오른쪽 사진은 블록만으로 벽을 쌓아 올렸어요. **무골조방식** 의 모습이에요."},{"b":[0.49,0.6,0.5,0.28],"c":[0.45,0.584,0.55,0.312],"r":2.3504,"img":"img/E2/walk/p041_20_04.jpg","say":"창과 문 자리를 나무틀로 잡아 두고 블록을 그 둘레에 쌓았어요."}]}},{"p":42,"title":"완성된 스트로베일 하우스와 영상 자료","terms":["Straw Bale"],"pass1":[{"kind":"say","lines":["다 지은 **스트로베일(Straw Bale)** 하우스 사진 두 장이에요.","겉을 흙이나 석회로 미장하면 짚은 보이지 않아요.","제목 옆에 '건축탐구 집' 영상 주소가 붙어 있어요."]}],"pass2":[{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"완성된 **스트로베일(Straw Bale)** 하우스에서 짚이 겉으로 보이지 않는 이유는?","choices":["양 벽면을 흙이나 석회로 미장하기 때문","짚을 태워 없애기 때문","짚을 시멘트로 굳히기 때문"],"a":0,"why":"5) 와 6) 에 나와요. 건초 블록을 쌓은 뒤 양 벽면을 흙이나 석회로 미장하고 외벽을 마감해요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.1592,0.063],"c":[0.0307,0.0701,0.2,0.095],"r":2.807,"img":"img/E2/walk/p042_h.jpg"},"parts":[{"b":[0.098,0.202,0.61,0.042],"c":[0.0675,0.1552,0.671,0.1356],"r":6.5978,"img":"img/E2/walk/p042_20_01.jpg","say":"제목 줄이에요. 괄호 안에 건축탐구 집 영상 주소가 있어요."},{"b":[0.03,0.37,0.45,0.52],"c":[0.0075,0.344,0.495,0.572],"r":1.1538,"img":"img/E2/walk/p042_20_02.jpg","say":"왼쪽 집이에요. 벽을 미장해서 매끈하고, 지붕은 짚을 얹은 초가 모양이에요."},{"b":[0.03,0.74,0.45,0.16],"c":[0.0075,0.724,0.495,0.192],"r":3.4375,"img":"img/E2/walk/p042_20_03.jpg","say":"벽 아래쪽은 돌로 받쳐 두었어요. 땅에서 올라오는 습기를 막는 자리예요."},{"b":[0.5,0.4,0.47,0.48],"c":[0.4765,0.376,0.517,0.528],"r":1.3056,"img":"img/E2/walk/p042_20_04.jpg","say":"오른쪽 집이에요. 둥근 평면에 하얗게 미장했고 처마가 넓어요."}]}},{"p":43,"title":"라이스하우스: 쌀 부산물로 만든 100% 친환경 건축자재","terms":["Straw Bale","Ricehouse"],"pass1":[{"kind":"say","lines":["**스트로베일(Straw Bale)** 이야기의 마지막 사례예요.","슬라이드에 기사 한 편이 그대로 붙어 있어요.","이탈리아의 **라이스하우스(Ricehouse)** 는 쌀을 찧고 남은 것으로 건축자재를 만들어요.","볏짚만이 아니라 쌀겨, 왕겨까지 다 써요."]}],"pass2":[{"kind":"points","head":"기사 본문을 그대로 읽어요","items":["**라이스하우스(Ricehouse)** 는 볏짚뿐 아니라 쌀겨 등 쌀 생산 부산물과 천연석회 등 100% 친환경 천연 재료를 원료로 써요.","이 원료로 단열재 외 다양한 건축 자재를 만들어요.","건축자재 모델 이름은 RH시리즈예요."]},{"kind":"points","head":"RH시리즈에 들어 있는 것","items":["단열용 식물재료, 볏짚 단열 패널이 있어요.","왕겨 천연석회를 기본으로 한 베이스플라스터가 있어요.","바닥재, 마감재, 데크용 시스템, 왕겨 블록 등도 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**라이스하우스(Ricehouse)** 가 자재의 원료로 쓰는 것으로 기사에 나온 것은?","choices":["볏짚, 쌀겨 등 쌀 생산 부산물과 천연석회","폐플라스틱과 유리섬유","시멘트와 모래","폐타이어 가루"],"a":0,"why":"기사 그대로예요. 볏짚뿐 아니라 쌀겨 등 쌀 생산 부산물과 천연석회 등 100% 친환경 천연 재료를 원료로 써요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.1592,0.063],"c":[0.0307,0.0701,0.2,0.095],"r":2.807,"img":"img/E2/walk/p043_h.jpg"},"parts":[{"b":[0.066,0.195,0.79,0.042],"c":[0.0265,0.1282,0.869,0.1756],"r":6.5983,"img":"img/E2/walk/p043_22_01.jpg","say":"기사 제목이에요. 쌀겨로 만든 100% 친환경 건축자재, 이탈리아의 '쌀 혁신' 이에요."},{"b":[0.066,0.234,0.3,0.042],"c":[0.051,0.2,0.33,0.11],"r":4.0,"img":"img/E2/walk/p043_22_02.jpg","say":"기사 날짜와 주소예요. 23년 11월 기사예요."},{"b":[0.105,0.308,0.79,0.092],"c":[0.0655,0.2662,0.869,0.1756],"r":6.5983,"img":"img/E2/walk/p043_22_03.jpg","say":"기사 본문 앞부분이에요. **라이스하우스(Ricehouse)** 가 무엇으로 자재를 만드는지 나와요."},{"b":[0.105,0.394,0.79,0.092],"c":[0.0655,0.3522,0.869,0.1756],"r":6.5983,"img":"img/E2/walk/p043_22_04.jpg","say":"RH시리즈 목록이에요. 단열용 식물재료부터 왕겨 블록까지 이어져요."},{"b":[0.035,0.5,0.495,0.44],"c":[0.0102,0.478,0.5445,0.484],"r":1.5,"img":"img/E2/walk/p043_22_05.jpg","say":"왼쪽 사진은 볏짚을 눌러 굳힌 블록이에요."},{"b":[0.535,0.5,0.45,0.44],"c":[0.505,0.478,0.495,0.484],"r":1.3636,"img":"img/E2/walk/p043_22_06.jpg","say":"오른쪽 사진은 제품의 원재료들을 늘어놓은 것이에요."}]}},{"p":44,"title":"라이스하우스가 지은 집: 쌀 부산물 자재로 지은 주택","terms":["Ricehouse","Straw Bale"],"pass1":[{"kind":"say","lines":["**라이스하우스(Ricehouse)** 기사에 이어지는 사진 한 장이에요.","산을 배경으로 한 요즘 모양의 집이에요.","**스트로베일(Straw Bale)** 계열 자재로 지어도 겉모습은 보통 집과 같아요."]}],"pass2":[{"kind":"look","walked":1}],"pass3":[],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.1592,0.063],"c":[0.0307,0.0701,0.2,0.095],"r":2.807,"img":"img/E2/walk/p044_h.jpg"},"parts":[{"b":[0.066,0.195,0.79,0.042],"c":[0.0265,0.1282,0.869,0.1756],"r":6.5983,"img":"img/E2/walk/p044_20_01.jpg","say":"기사 제목이 한 번 더 붙어 있어요."},{"b":[0.02,0.27,0.48,0.4],"c":[0,0.25,0.528,0.44],"r":1.6,"img":"img/E2/walk/p044_20_02.jpg","say":"왼쪽은 나무를 가로로 붙인 벽과 짙은 색 금속 지붕이에요."},{"b":[0.48,0.38,0.5,0.42],"c":[0.45,0.359,0.55,0.462],"r":1.5873,"img":"img/E2/walk/p044_20_03.jpg","say":"오른쪽 벽은 하얗게 미장한 넓은 면이에요. 창이 거의 없어요."},{"b":[0.18,0.47,0.32,0.42],"c":[0.164,0.449,0.352,0.462],"r":1.0159,"img":"img/E2/walk/p044_20_04.jpg","say":"앞으로 나온 면은 큰 유리창이에요. 위쪽에는 나무 살로 짠 차양이 달려 있어요."},{"b":[0.02,0.952,0.4,0.042],"c":[0,0.89,0.44,0.11],"r":5.3333,"img":"img/E2/walk/p044_20_05.jpg","say":"왼쪽 아래에 라이스하우스 누리집 주소가 적혀 있어요."}]}},{"p":45,"title":"3장 시작, 단열재의 종류 및 특성","terms":["Insulation","Asbestos","Polystyrene","PUR","Mineral Wool","Glass Wool","Rock Wool","Straw Bale"],"pass1":[{"kind":"say","lines":["여기서 장이 바뀌어요. 위 제목이 '3. 친환경 건축재료의 특성 및 건축방법' 이 돼요.","3장의 첫 재료가 **단열재(Insulation)** 예요.","앞에서 **스트로베일(Straw Bale)** 도 단열성능이 우수했죠. 이제 단열만 따로 봐요.","이 쪽은 단열재가 갖춰야 할 것과 종류 세 무리를 알려 줘요."]},{"kind":"analogy","head":"단열재는 겨울 패딩","scene":"패딩은 몸의 열이 새지 않게 잡아 줘요. 그런데 패딩 속 충전재가 몸에 해롭거나 만들 때 공장이 공기를 더럽히면 좋은 패딩이 아니에요.","map":[["열을 붙잡는 패딩","**단열재(Insulation)**"],["패딩이 얼마나 따뜻한가","열전도율과 열전달성 같은 기술적 특성"],["피부에 닿아도 안전한가","성분이 인체에 유해하지 않아야 함, 예로 **석면(Asbestos)**"],["충전재가 무엇인가","**폴리스티렌(Polystyrene)**, **미네랄울(Mineral Wool)**, 광물"]]}],"pass2":[{"kind":"points","head":"**단열재(Insulation)** 가 갖춰야 할 세 가지","items":["건물에서 소모되거나 방출되는 에너지를 줄이는 기능이에요. 그래서 탄소배출이 줄어요.","열전도율과 열전달성 등과 같은 기술적 특성을 봐요.","성분이 친환경적이고 인체에 유해하지 않아야 해요. 슬라이드는 **석면(Asbestos)** 의 유해성을 예로 들었어요."]},{"kind":"points","head":"종류 세 무리","items":["**폴리스티렌(Polystyrene)** 와 **폴리우레탄(PUR)** 재질은 석유에서 생산해요.","**미네랄울(Mineral Wool)** 는 **유리면(Glass Wool)** 과 **암면(Rock Wool)** 을 함께 부르는 말이에요.","광물은 화산석이나 규산염 등이 원료예요.","이 세 무리의 장단점이 다음 쪽 표에 정리돼요."]},{"kind":"figure","head":"단열재 세 무리와 원료","svg":"<svg viewBox=\"0 0 480 200\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240\" y=\"22\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">단열재 세 무리와 원료<\/text><rect x=\"14\" y=\"40\" width=\"144\" height=\"40\" rx=\"2\" class=\"box2 b1\"/><text x=\"86\" y=\"66\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b1\">폴리스틸렌, PUR<\/text><text x=\"86\" y=\"106\" font-size=\"13\" text-anchor=\"middle\" class=\"t b1\">석유에서 생산<\/text><rect x=\"168\" y=\"40\" width=\"144\" height=\"40\" rx=\"2\" class=\"box2 b2\"/><text x=\"240\" y=\"66\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b2\">미네랄울<\/text><text x=\"240\" y=\"106\" font-size=\"13\" text-anchor=\"middle\" class=\"t b2\">유리면과 암면<\/text><rect x=\"322\" y=\"40\" width=\"144\" height=\"40\" rx=\"2\" class=\"box2 b3\"/><text x=\"394\" y=\"66\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b3\">광물<\/text><text x=\"394\" y=\"106\" font-size=\"13\" text-anchor=\"middle\" class=\"t b3\">화산석이나 규산염<\/text><rect x=\"90\" y=\"140\" width=\"300\" height=\"40\" rx=\"2\" class=\"box b4\"/><text x=\"240\" y=\"166\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b4\">천연단열재와 셀룰로우스는 뒤에서 따로<\/text><\/svg>","caption":"슬라이드에 적힌 순서 그대로예요. 맨 위 상자 이름은 슬라이드 표기 '폴리스틸렌' 을 그대로 옮겼어요.","builds":4},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"슬라이드가 **단열재(Insulation)** 의 기능으로 적은 것은?","choices":["건물에서 소모되거나 방출되는 에너지를 줄인다","실내 습도를 높인다","건물의 무게를 받친다","빗물을 모아 준다"],"a":0,"why":"첫 줄 그대로예요. 에너지를 줄이는 기능이라 탄소배출도 줄어요."},{"kind":"warn","head":"표기와 짝짓기에서 조심할 점","items":["이 쪽 표기는 '폴리스틸렌' 이에요. 다음 쪽 표는 '폴리스티렌' 이라고 써요. 같은 **폴리스티렌(Polystyrene)** 예요.","**미네랄울(Mineral Wool)** 는 **유리면(Glass Wool)** 과 **암면(Rock Wool)** 을 묶은 이름이에요. 따로 있는 재료가 아니에요.","석유에서 생산하는 것은 **폴리스티렌(Polystyrene)** 와 **폴리우레탄(PUR)** 이에요. 광물은 화산석이나 규산염이에요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.1035,0.063],"c":[0.0029,0.0701,0.2,0.095],"r":2.807,"img":"img/E2/walk/p045_h.jpg"},"parts":[{"b":[0.098,0.212,0.23,0.042],"c":[0.086,0.178,0.254,0.11],"r":3.0788,"img":"img/E2/walk/p045_23_01.jpg","say":"제목이에요. 단열재의 종류 및 특성."},{"b":[0.115,0.265,0.7,0.042],"c":[0.08,0.2082,0.77,0.1556],"r":6.5981,"img":"img/E2/walk/p045_23_02.jpg","say":"첫 줄이에요. 소모되거나 방출되는 에너지를 줄여 탄소배출을 낮춰요."},{"b":[0.115,0.319,0.7,0.096],"c":[0.08,0.2892,0.77,0.1556],"r":6.5981,"img":"img/E2/walk/p045_23_03.jpg","say":"둘째, 셋째 줄이에요. 기술적 특성과 인체 유해성 이야기예요."},{"b":[0.115,0.425,0.7,0.17],"c":[0.08,0.409,0.77,0.202],"r":5.0825,"img":"img/E2/walk/p045_23_04.jpg","say":"종류 세 무리가 한 덩어리로 적혀 있어요."},{"b":[0.02,0.64,0.3,0.33],"c":[0.005,0.6235,0.33,0.363],"r":1.2121,"img":"img/E2/walk/p045_23_05.jpg","say":"왼쪽 사진은 분홍색 판 모양 단열재예요."},{"b":[0.33,0.65,0.3,0.32],"c":[0.315,0.634,0.33,0.352],"r":1.25,"img":"img/E2/walk/p045_23_06.jpg","say":"가운데 사진은 노랗게 말린 솜이에요. **유리면(Glass Wool)** 이 이런 모양이에요."}]}},{"p":46,"title":"단열재 표: 세 무리의 제조, 장점, 단점","terms":["Insulation","Polystyrene","PUR","Mineral Wool","Glass Wool","Rock Wool","발암지수"],"pass1":[{"kind":"say","lines":["앞 쪽의 세 무리가 표 한 장으로 정리돼요.","칸은 왼쪽부터 단열재, 제조, 장점, 단점 네 개예요.","표 아래 작은 주석 한 줄에 시험에 잘 나오는 숫자가 숨어 있어요."]}],"pass2":[{"kind":"compare","head":"**폴리스티렌(Polystyrene)**(EPS/XPS 스티로폼)과 **폴리우레탄(PUR)**","cols":["칸","내용"],"rows":[["제조","석유에서 에너지 집약적 생산"],["장점","단열 특성이 뛰어남, 기후 내구성이 뛰어남, 따라서 외부 영역(지하실, 지붕, 벽)에 사용됨"],["단점","제조 과정에서 독성 물질 및 발암 물질 생성, 화재 시 인체에 매우 해로우며 분해가 어려운 물질 첨가, 제조 시 온실가스의 발생이 필수적임"]]},{"kind":"compare","head":"**미네랄울(Mineral Wool)**(**유리면(Glass Wool)** 과 **암면(Rock Wool)**)","cols":["칸","내용"],"rows":[["제조","70%까지 폐유리로 에너지 집약적 생산"],["장점","단열 특성이 뛰어남, 따라서 경사진 지붕(steep roof) 단열에 사용됨"],["단점","설치 시 충분한 밀봉이 안 되면 실내 공기에 안 좋은 응고용 화학제품 첨가, 1995년 이전 제조품은 직물구조 때문에 암을 일으킬 수 있음"],["1995년 이후","'no effect level' 로 간주되는 인체 발암지수 40 을 충족함"]]},{"kind":"compare","head":"광물 단열재","cols":["칸","내용"],"rows":[["제조","광물 원료에서 생산"],["장점","기초 재료(basic material)는 재활용이 불가능하지만 대부분 처리할 수 있음(화산석, 규산염), 인체에 무해함, 일반적으로 재활용 가능성이 뛰어남"],["장점 한 줄 더","기포유리는 **폴리우레탄(PUR)** 과 PS 단열재 대용으로 적합함"],["단점","일부 긴 운송경로를 요구함, 원료의 채광이 자연환경을 훼손할 우려가 높음, 사용 영역이 제한됨"]]},{"kind":"steps","head":"표의 숫자 두 개를 손으로 확인해요","given":"**미네랄울(Mineral Wool)** 100kg 과 표 아래 주석의 **발암지수** 기준 40","steps":["제조 칸: 폐유리 비율은 최대 70% 예요.","100 × 0.70 = 70, 곧 100kg 가운데 최대 70kg 이 폐유리예요.","표 아래 주석: 인체 **발암지수** 40 미만의 단열재는 인체에 무해한 것으로 간주돼요.","1995년 이후 생산된 제품은 이 기준 40 을 충족해요."],"answer":"70 은 폐유리 비율, 40 은 **발암지수** 기준, 1995년이 나누는 해예요."},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"'70%까지 폐유리로 에너지 집약적 생산, 경사진 지붕 단열에 사용' 하는 단열재는?","choices":["**폴리스티렌(Polystyrene)**","**미네랄울(Mineral Wool)**","광물 단열재","**폴리우레탄(PUR)**"],"a":1,"why":"**미네랄울(Mineral Wool)** 예요. **폴리스티렌(Polystyrene)** 와 **폴리우레탄(PUR)** 은 석유에서 생산해 외부 영역(지하실, 지붕, 벽)에 써요."},{"kind":"check","q":"인체 **발암지수** 에 대한 설명으로 옳은 것은?","choices":["40 미만이면 인체에 무해한 것으로 간주된다","40 이상이면 인체에 무해한 것으로 간주된다","1995년 이전 제품만 기준을 충족한다","광물 단열재에만 적용되는 수치다"],"a":0,"why":"표 아래 주석 그대로예요. 그리고 1995년 이후 생산된 **미네랄울(Mineral Wool)** 가 이 기준 40 을 충족해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["쓰는 곳을 바꿔 내기 좋아요. 외부 영역은 **폴리스티렌(Polystyrene)** 와 **폴리우레탄(PUR)**, 경사진 지붕은 **미네랄울(Mineral Wool)** 예요.","온실가스 발생이 '필수적' 이라는 단점은 석유계 단열재 줄에만 있어요.","'인체에 무해함' 은 광물 단열재의 장점 칸에 있는 말이에요."]},{"kind":"english","head":"시험 답안에 쓸 문장","en":"미네랄울은 70%까지 폐유리로 생산하며 경사진 지붕 단열에 쓰이고, 1995년 이전 제품은 직물구조 때문에 암을 일으킬 수 있으나 이후 제품은 인체 발암지수 40을 충족한다.","ko":"**미네랄울(Mineral Wool)** 한 줄만 외워도 숫자 세 개(70, 1995, 40)를 다 쓸 수 있어요.","tip":"'70 폐유리, 1995 경계, 40 무해' 세 마디로 끊어서 외워요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2811,0.1533],"c":[0.0371,0.0701,0.3092,0.1853],"r":2.2249,"img":"img/E2/walk/p046_h.jpg"},"parts":[{"b":[0.18,0.248,0.82,0.042],"c":[0.098,0.1779,0.902,0.1822],"r":6.6008,"img":"img/E2/walk/p046_24_01.jpg","say":"표의 머리줄이에요. 왼쪽부터 단열재, 제조, 장점, 단점이에요."},{"b":[0.18,0.298,0.82,0.15],"c":[0.098,0.2819,0.902,0.1822],"r":6.6008,"img":"img/E2/walk/p046_24_02.jpg","say":"첫 줄이에요. **폴리스티렌(Polystyrene)** 와 **폴리우레탄(PUR)** 이 한 칸에 묶여 있어요."},{"b":[0.18,0.478,0.82,0.2],"c":[0.098,0.462,0.902,0.232],"r":5.1839,"img":"img/E2/walk/p046_24_03.jpg","say":"둘째 줄 **미네랄울(Mineral Wool)** 이에요. 70%, 1995년, 40 세 숫자를 꼭 챙겨요."},{"b":[0.18,0.728,0.82,0.19],"c":[0.098,0.712,0.902,0.222],"r":5.4174,"img":"img/E2/walk/p046_24_04.jpg","say":"셋째 줄 광물 단열재예요. 장점이 네 줄로 가장 길어요."},{"b":[0.18,0.944,0.4,0.042],"c":[0.16,0.89,0.44,0.11],"r":5.3333,"img":"img/E2/walk/p046_24_05.jpg","say":"표 아래 주석이에요. 인체 **발암지수** 40 미만이면 인체에 무해한 것으로 간주돼요."}]}},{"p":47,"title":"천연단열재의 특성과 주의할 점","terms":["천연단열재","Insulation"],"pass1":[{"kind":"say","lines":["이번 쪽은 **천연단열재** 만 따로 봐요.","동물에서 온 것과 식물에서 온 것으로 나뉘어요.","그런데 이 쪽의 진짜 이야기는 '천연이라고 끝이 아니다' 예요."]}],"pass2":[{"kind":"points","head":"**천연단열재** 는 두 갈래예요","items":["친환경성이 첫 줄에 한 낱말로 적혀 있어요.","동물성 원료(양모 등) 제품과 식물성 원료 제품으로 나뉘어요.","식물성 원료는 코르크, 코코넛 섬유, 목재섬유, 폐지 등이에요."]},{"kind":"points","head":"원료마다 붙은 주의점","items":["동물성 양모: 살충제를 사용하기도 해요.","식물성 코르크: 주로 마감 재료로만 사용되어 사용이 제한적이에요.","식물성 코코넛 섬유: 내구성은 뛰어나지만 방화처리 필수 및 긴 운송경로가 단점이에요.","목재섬유나 폐지: 원료 자체는 충분하나 방화와 방습을 위한 처리가 필요해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**천연단열재** 에 대한 슬라이드 설명으로 옳은 것은?","choices":["동물성 양모는 살충제를 사용하기도 한다","식물성 코르크는 어디에나 제한 없이 쓴다","코코넛 섬유는 방화처리가 필요 없다","폐지는 원료 자체가 부족하다"],"a":0,"why":"코르크는 주로 마감 재료로만 쓰여 제한적이고, 코코넛 섬유는 방화처리가 필수이며, 폐지와 목재섬유는 원료는 충분하나 방화와 방습 처리가 필요해요."},{"kind":"warn","head":"맨 아래 화살표 줄을 꼭 외워요","items":["**천연단열재** 라도 살충제 사용 여부를 확인해야 해요.","유해물질 첨가 여부도 확인해야 해요.","암모늄 화합물과 같이 인체에 무해한 성분으로 제조되었는지 확인해야 해요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.1035,0.063],"c":[0.0029,0.0701,0.2,0.095],"r":2.807,"img":"img/E2/walk/p047_h.jpg"},"parts":[{"b":[0.098,0.212,0.33,0.042],"c":[0.0815,0.178,0.363,0.11],"r":4.4,"img":"img/E2/walk/p047_22_01.jpg","say":"제목이에요. **천연단열재** 의 특성과 주의할 점이에요."},{"b":[0.115,0.265,0.14,0.042],"c":[0.085,0.231,0.2,0.11],"r":2.4242,"img":"img/E2/walk/p047_22_02.jpg","say":"첫 줄은 한 낱말이에요. 친환경성."},{"b":[0.115,0.319,0.83,0.096],"c":[0.0735,0.2748,0.913,0.1845],"r":6.598,"img":"img/E2/walk/p047_22_03.jpg","say":"두 갈래로 나누는 줄이에요. 동물성과 식물성이에요."},{"b":[0.115,0.425,0.83,0.18],"c":[0.0735,0.409,0.913,0.212],"r":5.7421,"img":"img/E2/walk/p047_22_04.jpg","say":"원료별 주의점이 한 줄씩 네 줄 이어져요."},{"b":[0.115,0.69,0.83,0.1],"c":[0.0735,0.6478,0.913,0.1845],"r":6.598,"img":"img/E2/walk/p047_22_05.jpg","say":"맨 아래 화살표 줄이에요. 천연이라도 확인할 것이 세 가지예요."}]}},{"p":48,"title":"국내 단열재 현황과 국외 셀룰로우스 단열재","terms":["Insulation","Cellulose Insulation","천연단열재"],"pass1":[{"kind":"say","lines":["한 쪽에 **단열재(Insulation)** 의 국내 현황과 국외 현황이 위아래로 나와요.","국내는 아직 화학성분 제품이 주를 이뤄요.","국외 쪽 주인공이 **셀룰로우스 단열재(Cellulose Insulation)** 예요."]}],"pass2":[{"kind":"points","head":"국내 단열재 현황","items":["화학성분을 지니고 있는 제품이 주를 이뤄요.","괄호 안에 유해성은 낮아졌지만 환경 측면에서의 불리함은 여전하다고 적혀 있어요.","친환경적인 단열재 연구로 볏짚과 갈대를 이용하여 화학재료와 혼합해요.","왕겨, 종이, 톱밥, 황토 등을 이용하고 목섬유를 더하기도 해요."]},{"kind":"points","head":"국외 현황: **셀룰로우스 단열재(Cellulose Insulation)** 와 목섬유","items":["목재펄프를 주원료로 하여 생산해요.","분쇄한 형태로 구조체 내부에 충진하는 형태예요.","폐기 시 재활용이 가능해요.","경량이라 건축물 자체 하중을 줄여요. 단열 성능 및 방음 성능이 뛰어나고 오염물질 배출이 없어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**셀룰로우스 단열재(Cellulose Insulation)** 에 대한 설명으로 옳지 않은 것은?","choices":["목재펄프를 주원료로 한다","분쇄한 형태로 구조체 내부에 충진한다","무거워서 건축물 하중이 늘어난다","폐기 시 재활용이 가능하다"],"a":2,"why":"**셀룰로우스 단열재(Cellulose Insulation)** 는 경량이라 건축물 자체 하중을 줄여요. 단열과 방음도 뛰어나고 오염물질 배출도 없어요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"셀룰로우스 단열재는 목재펄프를 주원료로 생산해 분쇄한 형태로 구조체 내부에 충진하며, 폐기 시 재활용이 가능하고 경량이어서 건축물 하중을 줄이며 단열과 방음 성능이 뛰어나고 오염물질 배출이 없다.","ko":"원료, 시공 형태, 장점 네 가지 순서로 쓰면 빠짐이 없어요.","tip":"'펄프 - 불어넣기 - 재활용, 가벼움, 조용함, 깨끗함' 으로 외워요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.1035,0.063],"c":[0.0029,0.0701,0.2,0.095],"r":2.807,"img":"img/E2/walk/p048_h.jpg"},"parts":[{"b":[0.098,0.214,0.2,0.042],"c":[0.086,0.18,0.224,0.11],"r":2.7152,"img":"img/E2/walk/p048_22_01.jpg","say":"위쪽 제목이에요. 국내 단열재 현황."},{"b":[0.124,0.274,0.56,0.1],"c":[0.096,0.258,0.616,0.132],"r":6.2222,"img":"img/E2/walk/p048_22_02.jpg","say":"국내는 화학성분 제품이 주를 이룬다는 두 줄이에요."},{"b":[0.124,0.393,0.78,0.1],"c":[0.085,0.3563,0.858,0.1733],"r":6.6013,"img":"img/E2/walk/p048_22_03.jpg","say":"친환경적인 단열재 연구 두 줄이에요. 볏짚, 갈대, 왕겨, 종이, 톱밥, 황토, 목섬유예요."},{"b":[0.098,0.547,0.46,0.042],"c":[0.075,0.513,0.506,0.11],"r":6.1333,"img":"img/E2/walk/p048_22_04.jpg","say":"아래쪽 제목이에요. 국외 단열재 현황(셀룰로우스 & 목섬유)."},{"b":[0.124,0.607,0.78,0.1],"c":[0.085,0.5703,0.858,0.1733],"r":6.6013,"img":"img/E2/walk/p048_22_05.jpg","say":"목재펄프 주원료, 분쇄해 구조체 내부에 충진한다는 두 줄이에요."},{"b":[0.378,0.727,0.52,0.22],"c":[0.352,0.711,0.572,0.252],"r":3.0265,"img":"img/E2/walk/p048_22_06.jpg","say":"장점 네 줄이에요. 재활용 가능, 경량, 단열과 방음, 오염물질 배출 없음."}]}},{"p":49,"title":"셀룰로우스 단열재 사진: 판으로도, 불어넣기로도","terms":["Cellulose Insulation"],"pass1":[{"kind":"say","lines":["**셀룰로우스 단열재(Cellulose Insulation)** 사진 두 장이에요.","왼쪽은 굳혀 만든 판, 오른쪽은 벽 속에 불어 넣는 모습이에요.","'분쇄한 형태로 구조체 내부에 충진' 이 무엇인지 눈으로 보는 쪽이에요."]}],"pass2":[{"kind":"look","walked":1}],"pass3":[],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.1035,0.063],"c":[0.0029,0.0701,0.2,0.095],"r":2.807,"img":"img/E2/walk/p049_h.jpg"},"parts":[{"b":[0.098,0.196,0.23,0.042],"c":[0.086,0.162,0.254,0.11],"r":3.0788,"img":"img/E2/walk/p049_20_01.jpg","say":"제목이에요. **셀룰로우스 단열재(Cellulose Insulation)**."},{"b":[0.02,0.385,0.48,0.435],"c":[0,0.3633,0.528,0.4785],"r":1.4713,"img":"img/E2/walk/p049_20_02.jpg","say":"왼쪽은 판 모양이에요. 잘게 부순 종이 알갱이가 그대로 보여요."},{"b":[0.515,0.385,0.34,0.435],"c":[0.498,0.3633,0.374,0.4785],"r":1.0421,"img":"img/E2/walk/p049_20_03.jpg","say":"오른쪽은 나무 기둥 사이 벽 속에 재료를 채워 넣는 모습이에요."},{"b":[0.78,0.4,0.21,0.42],"c":[0.766,0.379,0.234,0.462],"r":0.6753,"img":"img/E2/walk/p049_20_04.jpg","say":"작업자가 초록 호스로 불어 넣고 있어요. 마스크와 보안경을 썼어요."}]}},{"p":50,"title":"천연도료의 특성과 구성 성분별 주원료(표9)","terms":["Natural Paint","VOCs"],"pass1":[{"kind":"say","lines":["재료가 단열재에서 페인트로 넘어가요.","**천연도료(Natural Paint)** 는 주요 성분에 순수 천연원료를 쓴 페인트예요.","중금속과 **휘발성유기화합물(VOCs)** 를 쓰지 않아서 인체에 무해해요.","아래에는 성분별 주원료를 모은 표9 가 있어요."]},{"kind":"analogy","head":"벽에 바르는 화장품","scene":"피부에 바르는 화장품이 순한지 따지듯, 건물 피부에 바르는 페인트도 따져야 해요. 천연 원료로만 만든 화장품이 천연도료예요.","map":[["100% 천연 원료 화장품","**천연도료(Natural Paint)**"],["화장품의 독한 향 성분","**휘발성유기화합물(VOCs)**"],["화장품의 원료 목록","표9 의 여섯 가지 구성성분"]]}],"pass2":[{"kind":"points","head":"**천연도료(Natural Paint)** 의 특성 다섯 줄","items":["주요 성분(수지, 오일, 용제 등)에 재생산이 가능한 순수 천연원료를 사용한 도료예요.","중금속과 휘발성 유기화합물(**휘발성유기화합물(VOCs)**)이 사용되지 않아 인체에 무해한 재료예요.","내구성, 내알카리성, 내마모성, 통기성 등이 우수해요.","인화성 물질이 없어 화재 위험을 방지하고, 화재 발생 시 유독가스 배출이 없어요.","생산, 도장 작업, 폐기 전 과정에서 오염물질 발생이 없어요."]},{"kind":"compare","head":"표9: 천연도료의 구성 성분별 주원료","cols":["구성성분","주원료"],"rows":[["수지","송진, 낙엽송수지, 코파이바수지, 페루수지, 프로폴리스 등"],["오일","아마인유, 스톤파인 유, 동유, 잇꽃유, 피마자유 등"],["용제","시츄러스 오일, 레몬껍질 오일, 터키레드 오일 등"],["왁스","카나우바 왁스, 캔디릴라 왁스, 밀랍왁스, 미네랄 왁스, 파라핀 왁스 등"],["안료","광물, 토양, 식물 등 천연자원으로부터 색소 추출"],["기능성 첨가제","카세인, 콩 레시틴, 칼슘, 셀룰로오즈, 허브오일 등"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"표9 에서 '송진, 낙엽송수지, 코파이바수지, 페루수지, 프로폴리스' 가 속한 구성성분은?","choices":["수지","오일","용제","왁스"],"a":0,"why":"오일은 아마인유, 동유, 피마자유 등이고, 용제는 시츄러스 오일, 레몬껍질 오일 등이에요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"천연도료는 수지, 오일, 용제 등 주요 성분에 재생산이 가능한 순수 천연원료를 사용하며, 중금속과 휘발성유기화합물이 쓰이지 않아 인체에 무해하고 화재 시에도 유독가스가 배출되지 않는다.","ko":"원료, **휘발성유기화합물(VOCs)** 없음, 화재 때 유독가스 없음 세 덩어리로 쓰면 돼요.","tip":"표9 의 여섯 성분은 '수, 오, 용, 왁, 안, 첨' 여섯 글자로 외워요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.3135,0.063],"c":[0.0355,0.0701,0.3449,0.095],"r":4.8407,"img":"img/E2/walk/p050_h.jpg"},"parts":[{"b":[0.098,0.212,0.18,0.042],"c":[0.086,0.178,0.204,0.11],"r":2.4727,"img":"img/E2/walk/p050_22_01.jpg","say":"위 제목이에요. **천연도료(Natural Paint)** 의 특성."},{"b":[0.115,0.265,0.82,0.096],"c":[0.074,0.2219,0.902,0.1822],"r":6.6008,"img":"img/E2/walk/p050_22_02.jpg","say":"앞 두 줄이에요. 순수 천연원료, 그리고 중금속과 **휘발성유기화합물(VOCs)** 를 쓰지 않는다는 말이에요."},{"b":[0.115,0.372,0.72,0.15],"c":[0.079,0.356,0.792,0.182],"r":5.8022,"img":"img/E2/walk/p050_22_03.jpg","say":"뒤 세 줄이에요. 여러 내성, 화재 때 유독가스 없음, 전 과정 오염물질 없음이에요."},{"b":[0.098,0.532,0.38,0.042],"c":[0.079,0.498,0.418,0.11],"r":5.0667,"img":"img/E2/walk/p050_22_04.jpg","say":"아래 제목이에요. 천연도료의 구성 성분별 주원료 (표9)."},{"b":[0.2,0.6,0.58,0.18],"c":[0.171,0.584,0.638,0.212],"r":4.0126,"img":"img/E2/walk/p050_22_05.jpg","say":"표9 의 앞 세 줄이에요. 수지, 오일, 용제."},{"b":[0.2,0.8,0.58,0.165],"c":[0.171,0.784,0.638,0.197],"r":4.3181,"img":"img/E2/walk/p050_22_06.jpg","say":"표9 의 뒤 세 줄이에요. 왁스, 안료, 기능성 첨가제."}]}},{"p":51,"title":"친환경도료의 특성: 석유화학 기반의 저VOCs 도료","terms":["Eco-friendly Paint","Natural Paint","VOCs"],"pass1":[{"kind":"say","lines":["이름이 비슷한 **친환경도료(Eco-friendly Paint)** 가 나와요.","**천연도료(Natural Paint)** 와 달리 원료는 기존 석유화학이에요.","대신 중금속과 **휘발성유기화합물(VOCs)** 의 함량을 낮춘 저공해 도료예요.","아래에는 두 도료의 실제 제품 사진이 나란히 있어요."]}],"pass2":[{"kind":"points","head":"**친환경도료(Eco-friendly Paint)** 의 특성 다섯 줄","items":["기존 석유화학을 이용한 저공해, 저**휘발성유기화합물(VOCs)** 도료예요.","일반도료에 비해 사용되는 주요성분에 중금속과 **휘발성유기화합물(VOCs)** 의 함량이 낮아요.","재료에서 발생하는 유해 가스 방출량을 최소화해요.","1970년대 초 독일에서 가장 먼저 연구 개발했고, 이어서 **천연도료(Natural Paint)** 도 개발 생산했어요.","국내는 천연도료보다는 저공해, 저독성, 저VOCs 페인트 개발 실정이에요."]},{"kind":"compare","head":"두 도료를 나란히 놓으면","cols":["항목","**천연도료(Natural Paint)**","**친환경도료(Eco-friendly Paint)**"],"rows":[["원료","재생산이 가능한 순수 천연원료","기존 석유화학"],["중금속과 **휘발성유기화합물(VOCs)**","사용되지 않음","함량이 낮음(저VOCs)"],["슬라이드 사진","독일 AURO 천연도료","미국 Benjamin Moore 친환경도료"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**휘발성유기화합물(VOCs)** 를 '사용하지 않는' 쪽은 어느 도료인가요?","choices":["**천연도료(Natural Paint)**","**친환경도료(Eco-friendly Paint)**","일반도료","셋 다 사용한다"],"a":0,"why":"**천연도료(Natural Paint)** 는 중금속과 **휘발성유기화합물(VOCs)** 가 사용되지 않아요. **친환경도료(Eco-friendly Paint)** 는 함량이 낮은 저VOCs 도료예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["'친환경' 이라는 말 때문에 천연으로 오해하기 쉬워요. **친환경도료(Eco-friendly Paint)** 의 원료는 기존 석유화학이에요.","1970년대 초 독일이 가장 먼저 연구 개발했다는 연도와 나라를 바꿔 내기 좋아요.","국내는 천연도료보다 저공해, 저독성, 저VOCs 페인트 개발이 중심이라고 적혀 있어요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.3135,0.063],"c":[0.0355,0.0701,0.3449,0.095],"r":4.8407,"img":"img/E2/walk/p051_h.jpg"},"parts":[{"b":[0.098,0.212,0.19,0.042],"c":[0.086,0.178,0.214,0.11],"r":2.5939,"img":"img/E2/walk/p051_22_01.jpg","say":"제목이에요. **친환경도료(Eco-friendly Paint)** 의 특성."},{"b":[0.115,0.265,0.71,0.096],"c":[0.0795,0.2341,0.781,0.1578],"r":6.5991,"img":"img/E2/walk/p051_22_02.jpg","say":"앞 두 줄이에요. 저공해 저VOCs 도료이고 함량이 낮다는 말이에요."},{"b":[0.115,0.372,0.71,0.096],"c":[0.0795,0.3411,0.781,0.1578],"r":6.5991,"img":"img/E2/walk/p051_22_03.jpg","say":"셋째와 넷째 줄이에요. 방출량 최소화, 1970년대 초 독일이 먼저 개발."},{"b":[0.115,0.478,0.66,0.042],"c":[0.082,0.4257,0.726,0.1467],"r":6.5985,"img":"img/E2/walk/p051_22_04.jpg","say":"국내 사정 줄이에요. 저공해 저독성 저VOCs 페인트 개발이 중심이에요."},{"b":[0.08,0.6,0.42,0.35],"c":[0.059,0.5825,0.462,0.385],"r":1.6,"img":"img/E2/walk/p051_22_05.jpg","say":"왼쪽 사진은 독일 AURO 제품으로 **천연도료(Natural Paint)** 예요."},{"b":[0.56,0.56,0.4,0.4],"c":[0.54,0.54,0.44,0.44],"r":1.3333,"img":"img/E2/walk/p051_22_06.jpg","say":"오른쪽 사진은 미국 Benjamin Moore 제품으로 **친환경도료(Eco-friendly Paint)** 예요."}]}},{"p":52,"title":"기타 - 창호: 목재, 알루미늄, 합성수지","terms":["Wooden Window","PVC Window","Airtightness","Environmental Material"],"pass1":[{"kind":"say","lines":["이제 '기타' 세 쪽이 이어져요. 첫째가 창호예요.","창호 종류는 목재, 플라스틱, 금속재 세 가지예요.","맨 윗줄에 에너지 효율 순서가 바로 나와요. 목재 or 플라스틱 > 금속재예요."]}],"pass2":[{"kind":"points","head":"**목재창(Wooden Window)**","items":["자연목재를 가공하여 만든 창호로 **친환경재료(Environmental Material)** 예요.","소재 자체의 공극이 많아 단열성이 높아요.","자연소재로서 주는 질감의 심미적 친화력이 높아요.","물에 취약한 것이 단점이에요."]},{"kind":"points","head":"알루미늄 창","items":["사용연한이 장기적이에요.","**기밀성(Airtightness)** 이 높고, 무게가 가벼워 여닫음이 편리해요.","알루미늄 생산에 많은 에너지가 투입되는 것이 단점이에요."]},{"kind":"points","head":"**합성수지창(PVC Window)**","items":["단열성, 내부식성, 내후성(기후변화에 견디는 능력), 방로효과(이슬방지)가 높아요.","**기밀성(Airtightness)** 과 방음성이 우수해요.","석유를 기초로 한 제품이라 재사용이 어렵고 환경적으로 불리한 단점이 있어요."]},{"kind":"compare","head":"창호 세 가지 한눈에","cols":["창호","좋은 점","약점"],"rows":[["**목재창(Wooden Window)**","친환경재료, 공극이 많아 단열성 높음, 질감의 심미적 친화력","물에 취약"],["알루미늄 창","사용연한이 장기적, **기밀성(Airtightness)** 높음, 가벼워 여닫기 편리","생산에 많은 에너지"],["**합성수지창(PVC Window)**","단열성, 내부식성, 내후성, 방로효과, 기밀성, 방음성","석유 기초, 재사용 어려움"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"창호의 에너지 효율 순서로 슬라이드에 적힌 것은?","choices":["금속재 > 목재 or 플라스틱","목재 or 플라스틱 > 금속재","금속재 > 플라스틱 > 목재","세 가지가 모두 같다"],"a":1,"why":"맨 윗줄 그대로예요. 알루미늄은 생산에도 많은 에너지가 들어요."},{"kind":"check","q":"'내후성과 방로효과가 높고 기밀성, 방음성이 우수하지만 석유를 기초로 해 재사용이 어려운' 창호는?","choices":["**목재창(Wooden Window)**","알루미늄 창","**합성수지창(PVC Window)**"],"a":2,"why":"**합성수지창(PVC Window)** 예요. 내후성은 기후변화에 견디는 능력, 방로효과는 이슬방지라고 괄호로 풀어 놓았어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**기밀성(Airtightness)** 은 알루미늄 창과 **합성수지창(PVC Window)** 두 곳에 모두 나와요.","물에 취약한 것은 **목재창(Wooden Window)**, 재사용이 어려운 것은 **합성수지창(PVC Window)** 예요.","알루미늄의 단점은 쓰는 동안이 아니라 '생산' 에 에너지가 많이 든다는 점이에요."]},{"kind":"english","head":"시험 답안에 쓸 문장","en":"창호의 에너지 효율은 목재 또는 플라스틱이 금속재보다 높으며, 목재창은 공극이 많아 단열성이 높지만 물에 취약하고, 합성수지창은 기밀성과 방음성이 우수하나 석유 기초 제품이라 재사용이 어렵다.","ko":"순서 한 줄, 목재창 한 줄, 합성수지창 한 줄로 끊어 쓰면 돼요.","tip":"'목재는 공극, 알루미늄은 생산 에너지, PVC는 재사용' 으로 한 낱말씩 묶어요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.158,0.063],"c":[0.0301,0.0701,0.2,0.095],"r":2.807,"img":"img/E2/walk/p052_h.jpg"},"parts":[{"b":[0.098,0.212,0.79,0.042],"c":[0.0585,0.1452,0.869,0.1756],"r":6.5983,"img":"img/E2/walk/p052_24_01.jpg","say":"맨 윗줄이에요. 창호 종류와 에너지 효율 순서가 한 줄에 다 들어 있어요."},{"b":[0.098,0.265,0.51,0.17],"c":[0.0725,0.249,0.561,0.202],"r":3.703,"img":"img/E2/walk/p052_24_02.jpg","say":"**목재창(Wooden Window)** 묶음이에요. 네 줄이 붙어 있어요."},{"b":[0.098,0.532,0.51,0.17],"c":[0.0725,0.516,0.561,0.202],"r":3.703,"img":"img/E2/walk/p052_24_03.jpg","say":"알루미늄 창 묶음이에요. 세 줄이에요."},{"b":[0.098,0.745,0.8,0.1],"c":[0.058,0.7061,0.88,0.1778],"r":6.5992,"img":"img/E2/walk/p052_24_04.jpg","say":"**합성수지창(PVC Window)** 제목과 첫 줄이에요. 내후성과 방로효과의 뜻이 괄호로 붙어 있어요."},{"b":[0.12,0.85,0.7,0.1],"c":[0.085,0.8222,0.77,0.1556],"r":6.5981,"img":"img/E2/walk/p052_24_05.jpg","say":"기밀성과 방음성, 그리고 석유 기초라 재사용이 어렵다는 단점 줄이에요."}]}},{"p":53,"title":"기타 - 접착제: 천연계와 합성계","terms":["Natural Adhesive","Synthetic Adhesive"],"pass1":[{"kind":"say","lines":["'기타' 두 번째는 접착제예요.","접착제는 천연계와 합성계로 구분해요.","**천연접착제(Natural Adhesive)** 는 무독성 천연원료로 만들어요.","**합성접착제(Synthetic Adhesive)** 는 수지, 고무, 비닐 등을 섞어 만들어요."]}],"pass2":[{"kind":"points","head":"**천연접착제(Natural Adhesive)**","items":["석유화학 제품과 달리 무독성 천연원료로 만들어져요.","대부분 수용성이라 불연성, 무독성 등의 면에서 유리하고 실내공기질에도 유리해요.","독성이 없어 인체에 무해해요.","예로 아교, 송진, 라텍스 등이 있어요."]},{"kind":"points","head":"**합성접착제(Synthetic Adhesive)**","items":["수지, 고무, 비닐 등의 혼합물질을 원료로 만들어져요.","슬라이드는 여기에 장점을 적지 않았어요. **천연접착제(Natural Adhesive)** 쪽에만 좋은 점이 붙어 있어요.","앞 쪽 마감재 이야기와 이어져요. 원목 바닥재도 접착제 선택이 중요해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**천연접착제(Natural Adhesive)** 의 예로 슬라이드에 적힌 것은?","choices":["아교, 송진, 라텍스","수지, 고무, 비닐","PVC, 합성고무","카세인, 칼슘, 허브오일"],"a":0,"why":"아교, 송진, 라텍스예요. 수지, 고무, 비닐은 **합성접착제(Synthetic Adhesive)** 의 원료예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["'대부분 수용성' 은 **천연접착제(Natural Adhesive)** 의 성질이에요.","수지, 고무, 비닐은 **합성접착제(Synthetic Adhesive)** 의 원료예요. 접착제의 예가 아니에요.","'수지' 라는 낱말은 천연도료 표9 에도 나와요. 거기서는 송진, 프로폴리스 같은 천연 수지예요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.1859,0.063],"c":[0.0391,0.0701,0.2099,0.095],"r":2.946,"img":"img/E2/walk/p053_h.jpg"},"parts":[{"b":[0.098,0.212,0.24,0.042],"c":[0.086,0.178,0.264,0.11],"r":3.2,"img":"img/E2/walk/p053_22_01.jpg","say":"맨 윗줄이에요. 천연계 / 합성계로 구분해요."},{"b":[0.098,0.319,0.13,0.042],"c":[0.063,0.285,0.2,0.11],"r":2.4242,"img":"img/E2/walk/p053_22_02.jpg","say":"**천연접착제(Natural Adhesive)** 제목 줄이에요."},{"b":[0.12,0.372,0.73,0.18],"c":[0.0835,0.356,0.803,0.212],"r":5.0503,"img":"img/E2/walk/p053_22_03.jpg","say":"네 줄이 이어져요. 마지막 줄에 아교, 송진, 라텍스가 나와요."},{"b":[0.098,0.639,0.13,0.042],"c":[0.063,0.605,0.2,0.11],"r":2.4242,"img":"img/E2/walk/p053_22_04.jpg","say":"**합성접착제(Synthetic Adhesive)** 제목 줄이에요."},{"b":[0.12,0.692,0.53,0.042],"c":[0.0935,0.6541,0.583,0.1178],"r":6.5988,"img":"img/E2/walk/p053_22_05.jpg","say":"한 줄뿐이에요. 수지, 고무, 비닐 등의 혼합물질이 원료예요."}]}},{"p":54,"title":"기타 - 마감재와 리놀륨","terms":["Finishing Material","Linoleum","Natural Adhesive"],"pass1":[{"kind":"say","lines":["'기타' 세 번째는 **마감재(Finishing Material)** 예요.","건축공사의 마무리 단계에 쓰는 재료라 사람에게 직접적으로 영향을 미쳐요.","이 쪽의 함정은 **리놀륨(Linoleum)** 이에요. 같은 이름인데 두 가지가 있어요."]}],"pass2":[{"kind":"points","head":"**마감재(Finishing Material)** 의 두 갈래","items":["환경친화 **마감재(Finishing Material)**: 목재, 리놀륨, 타일, 코르크와 같은 천연 가공 재료들이에요.","석유 원료 마감재: PVC, 합성고무예요.","원목 바닥재는 인체에 무해한 천연 바닥재인데, **천연접착제(Natural Adhesive)** 처럼 접착제 선택이 중요해요."]},{"kind":"points","head":"**리놀륨(Linoleum)** 두 줄의 뜻이 서로 달라요","items":["고무계와 혼합하여 만들어 PVC, 비닐 계통으로 분류되는 바닥과 구분이 필요해요.","코르크계 리놀륨은 천연재료들만 섞어서 만들어져요. 이것이 친환경 바닥재예요.","슬라이드에서 빨간 화살표는 앞 줄, 초록 화살표는 뒤 줄과 짝지어져 있어요."]},{"kind":"figure","head":"**리놀륨(Linoleum)** 은 두 갈래로 갈려요","svg":"<svg viewBox=\"0 0 480 230\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"150\" y=\"14\" width=\"180\" height=\"36\" rx=\"2\" class=\"box2 b1\"/><text x=\"240\" y=\"38\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">리놀륨<\/text><line x1=\"200\" y1=\"52\" x2=\"122\" y2=\"90\" class=\"e2 b2\"/><polygon points=\"113,96 119,86 124,96\" class=\"arrow b2\"/><rect x=\"14\" y=\"100\" width=\"200\" height=\"36\" rx=\"2\" class=\"box b2\"/><text x=\"114\" y=\"124\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b2\">고무계와 혼합한 것<\/text><text x=\"114\" y=\"166\" font-size=\"13\" text-anchor=\"middle\" class=\"t b2\">PVC, 비닐 계통 바닥과<\/text><text x=\"114\" y=\"188\" font-size=\"13\" text-anchor=\"middle\" class=\"t b2\">구분이 필요해요<\/text><line x1=\"280\" y1=\"52\" x2=\"358\" y2=\"90\" class=\"e2 b3\"/><polygon points=\"367,96 356,96 361,86\" class=\"arrow b3\"/><rect x=\"266\" y=\"100\" width=\"200\" height=\"36\" rx=\"2\" class=\"box b3\"/><text x=\"366\" y=\"124\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b3\">코르크계 리놀륨<\/text><text x=\"366\" y=\"166\" font-size=\"13\" text-anchor=\"middle\" class=\"t b3\">천연재료들만 섞어서<\/text><text x=\"366\" y=\"188\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b3\">친환경 바닥재<\/text><\/svg>","caption":"왼쪽 갈래는 PVC, 비닐 계통 바닥과 헷갈리지 않게 구분해야 하고, 오른쪽 갈래가 친환경 바닥재예요.","builds":3},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**리놀륨(Linoleum)** 에 대한 설명으로 옳은 것은?","choices":["코르크계 리놀륨은 천연재료들만 섞어서 만든 친환경 바닥재다","리놀륨은 모두 친환경 바닥재다","고무계와 혼합한 리놀륨이 친환경 바닥재다","리놀륨은 석유 원료 마감재로만 분류된다"],"a":0,"why":"고무계와 혼합하여 만든 것은 PVC, 비닐 계통으로 분류되는 바닥과 구분이 필요해요. 코르크계만 천연재료들만 섞어 만들어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["환경친화 **마감재(Finishing Material)** 는 목재, 리놀륨, 타일, 코르크예요. 석유 원료 마감재는 PVC, 합성고무예요.","이름이 **리놀륨(Linoleum)** 이라고 모두 친환경이 아니에요. 코르크계인지 확인해야 해요.","원목 바닥재는 천연이지만 접착제를 잘못 고르면 소용이 없어요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.1859,0.063],"c":[0.0391,0.0701,0.2099,0.095],"r":2.946,"img":"img/E2/walk/p054_h.jpg"},"parts":[{"b":[0.098,0.212,0.77,0.042],"c":[0.0595,0.1474,0.847,0.1711],"r":6.6004,"img":"img/E2/walk/p054_23_01.jpg","say":"첫 줄이에요. **마감재(Finishing Material)** 는 사람에게 직접적으로 영향을 미쳐요."},{"b":[0.098,0.265,0.7,0.096],"c":[0.063,0.2352,0.77,0.1556],"r":6.5981,"img":"img/E2/walk/p054_23_02.jpg","say":"환경친화 마감재와 석유 원료 마감재를 나눈 두 줄이에요."},{"b":[0.098,0.372,0.47,0.096],"c":[0.0745,0.356,0.517,0.128],"r":5.3854,"img":"img/E2/walk/p054_23_03.jpg","say":"원목 바닥재 묶음이에요. 접착제 선택이 중요하다고 적혀 있어요."},{"b":[0.098,0.479,0.79,0.15],"c":[0.0585,0.463,0.869,0.182],"r":6.3663,"img":"img/E2/walk/p054_23_04.jpg","say":"**리놀륨(Linoleum)** 묶음이에요. 두 줄의 뜻이 서로 달라요."},{"b":[0.12,0.68,0.36,0.3],"c":[0.102,0.664,0.396,0.332],"r":1.5904,"img":"img/E2/walk/p054_23_05.jpg","say":"빨간 화살표가 가리키는 왼쪽 사진은 둥글게 말아 둔 바닥재 롤이에요."},{"b":[0.56,0.66,0.33,0.32],"c":[0.5435,0.644,0.363,0.352],"r":1.375,"img":"img/E2/walk/p054_23_06.jpg","say":"초록 화살표가 가리키는 오른쪽 사진은 코르크계 바닥을 깐 실내예요."}]}},{"p":55,"title":"생태건축에서 친환경 재료의 방향 및 목표","terms":["Environmental Material","Insulation","Finishing Material"],"pass1":[{"kind":"say","lines":["3주차 강의의 마지막 쪽이에요.","**친환경재료(Environmental Material)** 를 쓰는 일의 방향과 목표를 세 줄로 정리해요.","불편을 참으라는 것도, 옛날로 돌아가자는 것도 아니에요.","발전된 기술로 사람과 자연이 함께 지내는 건축이 목표예요."]},{"kind":"recap","items":["흙: 부위별 요구 성능, 담틀 공법과 흙짚과 심벽, 흙벽돌은 굽지 않아요.","사례: 밍케하우스(잔디지붕, 어도비 벽돌), 스트로베일(골조 5층 이상, 무골조 2층), 라이스하우스.","**단열재(Insulation)**: 석유계, 미네랄울, 광물, 천연, 셀룰로우스.","도료, 창호, 접착제, **마감재(Finishing Material)**: 천연이냐 저VOCs 냐를 늘 따져요.","주문: 자연에서 빌려 쓰고, 돌려주며 순환시켜요."]}],"pass2":[{"kind":"points","head":"세 줄을 그대로 읽어요","items":["사람들로 하여금 무조건적으로 불편을 강요할 수 없어요.","옛날방식 그대로 자연으로의 회귀가 목표일 수 없어요.","발전된 환경기술로써 인간과 자연이 어우러질 수 있는 건축 환경을 목표로 해요.","이 세 줄이 이번 강의에서 본 **친환경재료(Environmental Material)** 전체를 묶어 주는 결론이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"생태건축에서 친환경 재료의 방향으로 슬라이드가 말한 것은?","choices":["사람에게 불편을 감수하도록 요구해야 한다","옛날방식 그대로 자연으로 회귀해야 한다","발전된 환경기술로 인간과 자연이 어우러지는 건축 환경을 목표로 한다","재료보다 설비로만 해결해야 한다"],"a":2,"why":"앞 두 줄은 '할 수 없음' 으로 끝나는 부정문이에요. 마지막 줄만 목표를 말해요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"생태건축의 친환경 재료는 사람에게 무조건 불편을 강요하거나 옛날방식 그대로 자연으로 회귀하는 것이 목표가 아니라, 발전된 환경기술로 인간과 자연이 어우러질 수 있는 건축 환경을 만드는 것을 목표로 한다.","ko":"부정 두 개를 먼저 쓰고 마지막에 목표를 쓰면 **친환경재료(Environmental Material)** 의 방향이 그대로 답안이 돼요.","tip":"'불편 강요 아님 - 회귀 아님 - 기술로 어우러짐' 세 마디로 외워요."}],"pass4":[],"walk":{"head":null,"parts":[{"b":[0.098,0.214,0.5,0.042],"c":[0.073,0.1794,0.55,0.1111],"r":6.6007,"img":"img/E2/walk/p055_21_01.jpg","say":"제목이에요. 생태건축에서의 친환경 재료의 방향 및 목표."},{"b":[0.124,0.333,0.64,0.042],"c":[0.092,0.2829,0.704,0.1422],"r":6.601,"img":"img/E2/walk/p055_21_02.jpg","say":"첫 줄이에요. 무조건적으로 불편을 강요할 수 없어요."},{"b":[0.124,0.394,0.62,0.042],"c":[0.093,0.3461,0.682,0.1378],"r":6.5989,"img":"img/E2/walk/p055_21_03.jpg","say":"둘째 줄이에요. 옛날방식 그대로 회귀가 목표일 수 없어요."},{"b":[0.124,0.454,0.78,0.1],"c":[0.085,0.4173,0.858,0.1733],"r":6.6013,"img":"img/E2/walk/p055_21_04.jpg","say":"셋째 줄이에요. 발전된 환경기술로 인간과 자연이 어우러지는 건축 환경이 목표예요."}]}}]};
